window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-cirurgia-med-cir-03"]={"block":"med:med-cirurgia-med-cir-03","label":"MED · MED CIR 03","count":432,"questions":[{"id":"med-cirurgia-med-cir-03-345461","number":"345461","sourceNumber":"345461","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem de 52 anos é admitido no serviço de emergência com hematêmese e relato de\num episódio de melena. Há dois meses\napresentou episódio semelhante e desde então tem\npassado bem. A investigação àquela época foi negativa. Ele nega ingerir bebida alcoólica e uso de\nanti-inflamatórios. Ao exame aparenta palidez cutânea discreta; pressão arterial sistólica de 110\nmmHg quando deitado e 100 mmHg na posição ortostática; frequência cardíaca de 106 bpm, sem\noutros achados importantes. Exames complementares iniciais: hemoglobina = 9,8g/dL; ureia = 72\nmf/dL; creatinina = 1,1 mg/dL; endoscopia digestiva alta realizada no dia seguinte à admissão\nmostrou mucosas gástrica e duodenal de aspecto normal. O diagnóstico mais provável para esse\npaciente é:","options":{"A":"Úlcera de Curling.","B":"Úlcera de Cushing.","C":"Lesão de Dieulafoy.","D":"Síndrome de Mallory-Weiss."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-345510","number":"345510","sourceNumber":"345510","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente sexo feminino, 63 anos, refere hematoquezia há 3 meses, sem outros\ncomemorativos. Das opções abaixo, qual a medida inicial mais adequada?","options":{"A":"Realizar toque retal.","B":"Solicitar colonoscopia.","C":"Solicitar retossigmoidoscopia.","D":"Dosagem de CEA (Antigo Carcinoembrionário)."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-345511","number":"345511","sourceNumber":"345511","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"O principal tratamento para o controle da hemorragia digestiva alta por ruptura das\nvarizes de esôfago na hipertensão portal esquistossomótica é:","options":{"A":"Tratamento endoscópico.","B":"Uso de terlipressina.","C":"Balão de Sengstaken-Blakemore.","D":"Propranolol."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-251862","number":"251862","sourceNumber":"251862","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A abordagem inicial de um paciente que se apresenta na sala de emergência com um\nquadro de hemorragia digestiva consiste em:","options":{"A":"Busca da etiologia do sangramento.","B":"Pesquisa de comorbidades importantes.","C":"Passagem de sonda nasogástrica calibrosa.","D":"Avaliação do estado volêmico."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-247160","number":"247160","sourceNumber":"247160","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem com 53 anos de idade, com diagnóstico de varizes de esôfago há 3 anos por\nhipertensão portal de etiologia esquistossomótica, deu entrada no pronto-socorro com história de\nvômitos com sangue em grande quantidade há 1 hora. Ao exame, PA = 70x40 mmHg, pulso fino de\n120bpm, pele fria, sudorese e confusão mental. A conduta recomendada é:","options":{"A":"Reposição volêmica vigorosa e passagem de balão esofagogástrico se mantiver instabilidade\nhemodinâmica.","B":"Endoscopia digestiva alta imediata com ligadura das varizes esofágicas.","C":"Reposição volêmica vigorosa seguida de laparotomia exploradora e realização da cirurgia de\nCrawford.","D":"Reposição volêmica vigorosa seguida de laparotomia exploradora e realização da cirurgia de\nWarren.","E":"Reposição volêmica, controle de Hb/Ht e endoscopia digestiva alta após 24 horas de\nestabilidade hemodinâmica."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-159123","number":"159123","sourceNumber":"159123","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A hemorragia digestiva alta (HDA) é um das principais causas de óbito entre os\nindíviduos com cirrose hepática. Diante de um\nquadro de HDA em um paciente portador de cirrose\nhepática pelo vírus da hepatite B, que após o manejo inicial estabiliza hemodinamicamente, você\nindica primariamente o tratamento:","options":{"A":"Endoscópico com escleroterapia.","B":"Endoscópico com ligadura elástica.","C":"Medicamentoso com terlipressina, um vasoconstritor esplâncnico.","D":"Medicamentoso com propranolol, um betabloqueador."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-159110","number":"159110","sourceNumber":"159110","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente sexo feminino, 60 anos, refere hematoquezia há 3 meses, sem outros\ncomemorativos. Das opções abaixo, qual a medida inicial mais adequada?","options":{"A":"Solicitar colonoscopia.","B":"Solicitar retossigmoidoscopia.","C":"Dosagem de CEA (Antígeno Carcinoembrionário).","D":"Realizar toque retal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-67006","number":"67006","sourceNumber":"67006","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Pac. sexo masculino. 26 anos, iniciou quadro de dor epigástrica e retroesternal,\nseguidos de vômitos com raios de sangue com\nevolução de 12h. Refere ingestão abusiva de álcool\nna noite anterior. Nega episódios semelhantes anteriormente e se apresenta hemodinamicamente\nestável. Qual a hipóstese diagnóstica?","options":{"A":"Síndrome de Mallory-Weiss;","B":"Úlcera duodenal;","C":"Síndrome de Boerhaave;","D":"Rutura de varizes de esôfago."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-66923","number":"66923","sourceNumber":"66923","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Pac. sexo masculino, 26 anos, iniciou quadro de dor epigástrica e retroesternal,\nseguidos de vômitos com raios de sangue com\nevolução de 12h. Refere ingestão abusiva de álcool\nna noite anterior. Nega episódios semelhantes anteriormente e se apresenta hemodinamicamente\nestável. Com relação ao caso clínico, qual a melhor conduta?","options":{"A":"Passar sonda nasogástrica e iniciar lavagem com soro fisiológico;","B":"Endoscopia digestiva alta de imediato;","C":"Solicitar hematócrito para avaliar a perda sanguínea;","D":"Solicitar seriografia esôfago-estômago-duodeno."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-37147","number":"37147","sourceNumber":"37147","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual destas patologias é a mais sugestiva em apresentar hemorragia maciça de origem\ncolônica de caráter agudo?","options":{"A":"colite granulomatosa","B":"colite ulcerativa","C":"carcinoma","D":"polipose familiar","E":"diverticulose difusa"},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-37148","number":"37148","sourceNumber":"37148","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"É possível observar Melena em decorrência de:","options":{"A":"Lesões sigmoideanas","B":"Lesões retais","C":"Lesões do cólon direito","D":"Lesões do canal anal","E":"Em todos os casos acima"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-313436","number":"313436","sourceNumber":"313436","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Dentre as alternativas apresentadas abaixo, assinale a correta em relação às\ntransfusões de concentrado de hemácias em pacientes com hemorragia digestiva.","options":{"A":"Em caso de pacientes com perdas sanguíneas contínuas e pacientes com quadro de choque\nhemorrágico, pode-se indicar a transfusão de concentrado de hemácias, mesmo sem ter o valor da\nhemoglobina dosada.","B":"Em pacientes com perdas sanguíneas e evolução para choque hemorrágico, necessita-se do\nvalor de hemoglobina abaixo do corte de 7 a 8g/dL, mesmo que haja perdas contínuas de sangue,\npara se indicar a transfusão.","C":"Não há necessidade de transfusão de concentrado de hemácias nas hemorragias digestivas, em\nespecial nas hemorragias digestivas altas.","D":"Atualmente, o valor de corte de hemoglobina que indica transfusão de concentrado de hemácias\né de 10g/dL, sem importar a situação."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-280427","number":"280427","sourceNumber":"280427","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"É a anomalia congênita mais encontrada no intestino delgado e geralmente está\nlocalizada na borda antimesentérica do íleo,\n45 a 60 cm proximal à válvula ileocecal e resulta de um\nfechamento incompleto do conduto onfalomesentérico, ou vitelínico.","options":{"A":"Dívertículo de Zenker.","B":"Divetículo de Meckel.","C":"Mucocele ileal.","D":"Úraco persistente."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-280440","number":"280440","sourceNumber":"280440","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente hepatopata crônico, é transferido ao pronto-atendimento com história de\nmelena há 4 dias e hematêmese volumosa\nhoje. Sinais vitais da admissão em sala de emergência:\npressão arterial: 60 x 40 mmHg, frequência cardíaca: 145 bpm, frequência respiratória: 20 irpm,\nsaturação de oxigênio periférica: 92%, temperatura axilar: 38,5o. Ao exame físico: mal estado geral,\ndescorado, ictérico, acianótico, ictérico, febril. Ausculta pulmonar com crepitações em ambas as\nbases pulmonares, bulhas cardíacas rítmicas e taquicárdicas, abafadas, sem sopros audíveis.\n\nAbdome com ruídos, levemente distendido, ascítico, presença de circulação colateral, doloroso à\npalpação difusa, com sinais de irritação peritoneal. As principais hipóteses diagnósticas são:","options":{"A":"Hemorragia digestiva alta (varicosa ou ulcerosa), abdome agudo perfurativo, peritonite\nbacteriana.","B":"Hemorragia digestiva alta (varicosa apenas), abdome agudo perfurativo, peritonite bacteriana.","C":"Hemorragia digestiva baixa, abdome agudo perfurativo, peritonite bacteriana.","D":"Hemorragia digestiva baixa (varicosa), abdome agudo perfurativo, peritonite bacteriana."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-212174","number":"212174","sourceNumber":"212174","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"É contraindicação absoluta a exame de endoscopia digestiva baixa:","options":{"A":"hemoglobina de 8.","B":"uso de ácido acetil salicílico.","C":"antecedente recente de abdome agudo obstrutivo.","D":"deixar de obter termo de consentimento livre e esclarecido.","E":"lesão em cólon transverso que ocupa mais de 80% da luz do órgão."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-183105","number":"183105","sourceNumber":"183105","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"São doenças que entram no diagnóstico diferencial das hemorragias digestivas na\ninfância todas a seguir, EXCETO:","options":{"A":"Divertículo de Meckel.","B":"Hemorroidas.","C":"Cetoacidose diabética.","D":"Intussuscepção."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-161309","number":"161309","sourceNumber":"161309","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinale a alternativa INCORRETA sobre a Laceração de Mallory-Weiss.","options":{"A":"Está relacionada com vômitos explosivos, regurgitação, tosse ou esforço excessivo.","B":"Ocorre ruptura da mucosa gástrica em uma parte alta da curvatura maior na junção\ngastroesofágica.","C":"Raramente está associada a um sangramento generoso.","D":"A maioria dos pacientes com sangramento ativo pode ser tratada com métodos endoscópicos,\ncomo a coagulação multipolar, a injeção de\nepinefrina, a ligadura com uma banda elástica e/ou a\nhemoclipagem endoscópica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-161193","number":"161193","sourceNumber":"161193","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A hemobilia letal, secundária a um trauma abdominal penetrante, foi descrita por\nGlisson em 1654. Sobre esta patologia, assinale a alternativa INCORRETA.","options":{"A":"A causa mais comum de hemobilia é o trauma iatrogênico do fígado e via biliar.","B":"A intervenção cirúrgica está indicada quando houver hemobilia de sangramento arterial.","C":"A tríade clássica é representada por dor abdominal superior, hemorragia digestiva\ngastrointestinal alta e icterícia.","D":"A primeira linha de tratamento para hemobilia volumosa é a embolização transarterial."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-161252","number":"161252","sourceNumber":"161252","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Marque a opção INCORRETA quanto à hemobilia.","options":{"A":"A exploração cirúrgica da árvore biliar pode resultar em hemobilia por lesão direta ou pela\nformação de pseudoaneurisma arterial.","B":"O tratamento de primeira linha para uma hemobilia volumosa é a intervenção cirúrgica e envolve\na ligadura de vasos sangrantes, excisão do\naneurisma ou a ligadura não seletiva de uma artéria\nhepática principal.","C":"A hemobilia secundária à lesão acidental é mais comum no trauma abdominal fechado do que\nno penetrante.","D":"A tríade clássica de sintomas e sinais de hemobilia são dor abdominal superior, hemorragia\ngastrointestinal alta e icterícia."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-152651","number":"152651","sourceNumber":"152651","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual das seguintes afirmações está CORRETA em relação às angiodisplasias do\ncólon?","options":{"A":"Fulguração da angiodisplasia deve ser realizada durante uma colonoscopia eletiva,\nindependentemente da história de sangramento anterior.","B":"O sangramento da angiodisplasia é mais comum no lado esquerdo do paciente idoso.","C":"Uma angiografia normal durante um sangramento ativo exclui angiodisplasia como causa de\nhemorragia.","D":"As angiodisplasias variam de 1,5 a 2 mm e histologicamente são caracterizadas por capilares\ndilatados e tortuosos localizados na lâmina própria.","E":"Nenhuma das alternativas acima está correta."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-131338","number":"131338","sourceNumber":"131338","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual das seguintes afirmações está CORRETA em relação às angiodisplasias do\ncólon?","options":{"A":"Fulguração da angiodisplasia deve ser realizada durante uma colonoscopia eletiva,\nindependente da história de sangramento anterior.","B":"O sangramento da angiodisplasia é mais comum no lado esquerdo do paciente idoso.","C":"Uma angiografia normal durante um sangramento ativo exclui angiodisplasia como causa de\nhemorragia.","D":"As angiodisplasias variam de 1,5 a 2 mm e histologicamente são caracterizadas por capilares\ndilatados e tortuosos localizados na lâmina própria.","E":"Nenhuma das alternativas acima está correta."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-110584","number":"110584","sourceNumber":"110584","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em um paciente com Hemorragia Digestiva Alta de moderada a severa é correto\nafirmar:","options":{"A":"Hematêmese, melena, hipotensão arterial e taquicardia são sinais importantes no diagnóstico e\navaliação clinica do paciente.","B":"Hematêmese, melena, hipertensão arterial e taquicardia são sinais importantes no diagnóstico e\navaliação clínica do paciente.","C":"Em relação à mensuração da hemorragia considera-se uma perda moderada o paciente que\napresente PA = 90 a 100 mmHg, FC = 120 bpm e perda sanguínea em torno de 1.000 ml.","D":"As alternativas B e C estão corretas.","E":"As alternativas A e C estão corretas."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-109777","number":"109777","sourceNumber":"109777","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à causa de abdome agudo hemorrágico, a MENOS provável é:","options":{"A":"laceração do fígado + baço no trauma.","B":"gravidez ectópica rota.","C":"úlcera perfurada + diverticulite aguda.","D":"laceração do mesentério no trauma."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-86674","number":"86674","sourceNumber":"86674","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As afirmativas abaixo são causas mais comuns de hemorragia digestiva baixa no adulto\njovem: I ? Divertículo de Meckel, pólipos. II ? Câncer, angiodisplasia. III ? Doença inflamatória\nintestinal, pólipos.","options":{"A":"Apenas afirmativa I está correta.","B":"Apenas afirmativas I e II estão corretas.","C":"Apenas afirmativa II está correta.","D":"Apenas afirmativa III está correta.","E":"Todas afirmativas estão erradas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-86820","number":"86820","sourceNumber":"86820","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A causa mais frequente de hemorragia digestiva baixa é:","options":{"A":"Neoplasia do intestino grosso;","B":"Hemorroidas;","C":"Doença diverticular;","D":"Varizes colônicas;","E":"Colites."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-86669","number":"86669","sourceNumber":"86669","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"J.M., masculino, 39 anos, deu entrada no Hospital de Pronto-Socorro com quadro de\nhematêmese severa. Endoscopia digestiva alta revela lesão em corpo gástrico com sangramento\nativo e pequena ulceração central. Este foi submetido à ressecção gástrica em cunha envolvendo\ntoda a lesão. Histopatológico trata-se de GIST, com alto grau, 15 mitoses por campo/50. Qual a\nconduta seguinte:","options":{"A":"Gastrectomia total.","B":"Radioterapia.","C":"Observação e seguimento com PET-CT.","D":"Quimioterapia com RITUXIMAB.","E":"Quimioterapia com MESILATO DE IMONTIMISE."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-49633","number":"49633","sourceNumber":"49633","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"São drogas utilizadas no tratamento das hemorragias digestivas por varizes\nesofageanas:","options":{"A":"Terlipressina, somatostatina e octreotide.","B":"Octreotide, nitroprussiato de sódio e captopril.","C":"Somatostatina, amiodarona e clonidina.","D":"Terlipressina, somatostatina e amiodarona.","E":"Captopril, nitroprussiato de sódio e pilocarpina."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-362508","number":"362508","sourceNumber":"362508","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 10 anos de idade, apresentando quadro de dor aguda e\nprogressiva em FID, associada a vómitos e febre e sinais de irritação peritoneal. Foi indicada a\nlaparotomia pela hipótese diagnóstica de apendicite aguda, porém durante a exploração cirúrgica\nfoi observado abcesso bloqueado em FID secundário a processo inflamatório e perfuração em\nestrutura saculiforme de 5cm de diâmetro localizado em íleo distal, há cerca de 50cm da vávula\níleo-ceçal. O apêndice não tinha sinais patológicos. Optou-se por enterectomia do segmento ileal\nacometido, enteroanastomose e apendicectomia incidental. A mãe do paciente solicitou\nesclarecimento sobre o achado cirúrgico e a patologia do filho. As seguintes orientações são\nadequadas para o caso, EXCETO:","options":{"A":"\"\"A maioria das pessoas não sabe que tem essa pequena alteração no intestino porque não tem\nsintomas e se pode passar a vida inteira sem apresentar complicações\"\".","B":"\"\"É uma doença de difícil diagnóstico porque ela normalmente passa despercebida nos exames\nde imagem como ultrassonografia e tomografia e\no diagnóstico geralmente é feito durante uma\ncirurgia para outras doenças\"\".","C":"\"\"Essa doença não complica apenas com inflamação e casos de obstrução intestinal e\nhemorragia digestiva também podem ocorrer\"\".","D":"\"\"As duas principais causas de inflamação são a presença de tecido de outras partes do tubo\ndigestivo (tecido ectópico), como esófago e duodeno, e perfuração por corpos estranhos como\nespinhas de peixe\"\"."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-362505","number":"362505","sourceNumber":"362505","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 45 anos, é achado desmaiado no banheiro da sua\nresidência e trazido para o pronto socorro. Apresenta-se hipocorado +++/4, FC: 120bpm, FR:\n28irpm, P.A.: 80x60mmHg e débito urinário reduzido. Não há icterícia, edema de membros\ninferiores ou abdome ascítico. Foi infundido inicialmente 1.000ml de ringer lactato durante\nressuscitação volêmica e transfundidos 2 concentrados de hemácias após hemograma revelar\nhemoglobina 7g/dl. Após as medidas iniciais, o paciente apresentou estabilização dos sinais\nclínicos e referiu a equipe estar apresentando fezes enegrecidas de odor fétido há vários dias.\nNega hematêmese e quadro febril. Sobre o caso descrito, assinale a alternativa INCORRETA:","options":{"A":"Na avaliação laboratorial deste paciente, devemos observar elevados índices de uréia sérica e\nrelação uréja/creatinina acima de 50.","B":"Os dados clínicos apresentados nos permitem afirmar que este paciente apresenta risco elevado\npara complicações e óbito, sendo indicada\ntratamento intervencionista urgente.","C":"Admissão do paciente com choque grave por si já fecha critério para tratamento cirúrgico\nprecoce para controle do sangramento.","D":"Caso a endoscopia digestiva alta não evidencie foco de sangramento, a angio-tomografia é\nopção adequada para identificação do sítio de\nsangramento."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-298217","number":"298217","sourceNumber":"298217","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 28 anos, vem ao pronto atendimento queixando dor\nsubesternal e epigástrica severas, que o\nacordaram durante a madrugada. O paciente refere ter ido\nà festa na noite anterior e ingerido uma quantidade significativa de álcool que o fez vomitar várias\nvezes ao chegar ao seu domicílio. Ao exame físico, o paciente apresentava-se com fascies de dor,\nfebril (38,8ºC), taquicárdico, taquipneico e normotenso. A ausculta do tórax revelou murmúrio\nvesicular diminuído à esquerda, ausência de ruídos adventícios e exame cardíaco apresentando\ntaquicardia sem outras alterações. Seu abdome era doloroso à palpação profunda do epigástrio,\nsem sinais de irritação peritoneal. Sua investigação laboratorial revelou leucocitose importante\n(26.000 leucócitos com desvio à esquerda). Hematócrito, hemoglobina, contagem de plaquetas,\ndosagens de amilase, bilirrubinas e transaminases dentro da normalidade. Foi submetido a ECG\nque evidenciou taquicardia sinusal. A radiografia de tórax evidenciou derrame pleural associado a\npequeno pneumotórax à esquerda e pneumomediastino. Sobre o caso acima, assinale a alternativa\nCORRETA:","options":{"A":"O próximo passo para o diagnóstico deste paciente é a tomografia de tórax com contraste oral\niodado.","B":"O esofagograma contrastado com bário é o estudo radiográfico mais eficaz e menos mórbido\nindicado para o caso.","C":"Os dados acima nos permitem afirmar que a melhor opção de tratamento deste paciente é a\ndrenagem fechada de tórax à esquerda, manutenção de dieta oral sem gorduras, antibioticoterapia\ne inibidores de bomba de prótons.","D":"Os dados acima nos permitem afirmar que a endoscopia digestiva alta é contraindicada para\neste paciente por aumentar significativamente o índice de mortalidade."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-286721","number":"286721","sourceNumber":"286721","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, industriário, 54 anos, é conduzido por familiares ao pronto\natendimento devido a ?desmaio no banheiro? pela manhã. É admitido algo sonolento, anictérico,\nhipocorado +++/4, taquicárdico, discretamente dispneico e hipotenso. Seu exame cardiopulmonar\nnão tem alterações e seu abdome é atípico, sem circulação colateral, plano, flácido, indolor, sem\nmassas palpáveis. Realizou um hemograma de urgência que evidenciou 7.500 leucócitos,\nhemoglobina 6,3 g/dl, hematócrito 18,7% e plaquetas 350.000. Após ressuscitação volêmica com\nRinger lactato, seu status hemodinâmico e o nível de consciência normalizaram. Então o paciente\nreferiu que vinha apresentando abundantes fezes escuras ?como açaí? há 1 semana. Nega\nvômitos, disfagia, perda de peso e demais sintomas. Refere epigastralgia crônica, tratando-a por\nconta própria com antiácidos. Assinale a alternativa CORRETA:","options":{"A":"Caso a endoscopia digestiva alta evidencie lesão gástrica ulcerosa classe IIC de Forrest, o\npróximo passo é laparotomia urgente para controle do foco de sangramento.","B":"A evolução subaguda do caso associada a suspeita de hemorragia digestiva alta sugere\nprovável síndrome de Mallory-Weiss.","C":"O tratamento deste paciente provavelmente envolverá inibidores de bomba de prótons.","D":"O uso do balão de Sengstaken-Blakemore é essencial na abordagem terapêutica inicial deste\npaciente."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-256575","number":"256575","sourceNumber":"256575","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A hemorragia digestiva é uma ocorrência frequente nos atendimentos das emergências\nhospitalares. Trata-se de uma manifestação particularmente grave associada à mortalidade de 15 a\n20% dos pacientes. A fonte da maioria das hemorragias digestivas pode ser suspeitada pelos\nsintomas clínicos e exame físico e confirmadas pela endoscopia digestiva alta (EDA) e/ou\ncolonoscopia. Assinale a alternativa INCORRETA:","options":{"A":"A primeira conduta em pacientes com suspeita de hemorragia digestiva deve ser encaminha-los\nimediatamente para realização de endoscopia digestiva alta. Caso não seja evidenciado\nsangramento, deve-se iniciar o preparo expresso para realização de colonoscopia.","B":"A avaliação rápida e a ressuscitação devem preceder os procedimentos diagnósticos em\npacientes instáveis com hemorragia aguda grave.","C":"Na hemorragia digestiva alta a proteção das vias aéreas é importante, pela possibilidade de\naspiração do sangue vomitado ou regurgitado, o que está associado a significativas morbidade e\nmortalidade.","D":"A história clínica deve ser bem-feita, às vezes com a ajuda de familiares ou acompanhantes."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-252239","number":"252239","sourceNumber":"252239","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma doença que afeta 2% da população, localizada a 2 pés da válvula ileocecal e que\nnos pacientes sintomáticos esta abaixo de 2\nanos de idade:","options":{"A":"Ileite congênita.","B":"Divertículo falso de Meckel.","C":"Intussuscepção.","D":"Divertículo verdadeiro de Meckel."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-208311","number":"208311","sourceNumber":"208311","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Malformação congênita, localizada na borda antimesentérica do íleo terminal refere-se\na:","options":{"A":"Bandas de Ladd.","B":"Divertículo de Meckel.","C":"Onfalocele.","D":"Cisto mesentérico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-208335","number":"208335","sourceNumber":"208335","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente alcoólatra, com vários episódios eméticos prévios, apresenta hematêmese. Na\nEndoscopia Digestiva Alta evidencia-se lacerações tipo fissuras na mucosa e submucosa do\nesôfago, próximo a junção gástrica. Corresponde a qual patologia?","options":{"A":"Úlcera de Marjolin","B":"Síndrome de Mallory Weiss","C":"Esofago de Barret","D":"Lesão de Dieulafoy"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-208419","number":"208419","sourceNumber":"208419","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 70 anos, hipertenso e cardiopata, dá entrada no serviço\nde pronto atendimento com quadro de\nhematoquezia e evoluiu com vários episódios de\nenterorragia, há 24 horas. O paciente se encontra hipocorado ++/4, FC: 100 bpm, FR: 26 irpm, PA:\n110 x60 mmHg. Seu exame físico do abdome não revelou alterações. Realizou um hemograma que\ndemonstrou hematócrito de 27% e hemoglobina 9 g/dL. Assinale a alternativa INCORRETA:","options":{"A":"Uma vez que o paciente apresenta instabilidade hemodinâmica, a abordagem mais efetiva para\no caso é a laparotomia urgente para a\ndefinição do foco do sangramento e sua resolução.","B":"Há uma incidência crescente das hemorragias digestivas baixas no mundo devido ao aumento\nda idade da população associado ao uso crônico\nde anticoagulantes.","C":"A principal hipótese etiológica para o caso é o sangramento de divertículo no cólon direito,\nporém a angiodisplasia e a neoplasia de cólon são diagnósticos diferenciais.","D":"A endoscopia digestiva alta e a tomografia com contraste venoso podem fazer parte do\norganograma de investigação deste paciente."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-176098","number":"176098","sourceNumber":"176098","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 38 anos, vem ao pronto-socorro apresentando dor\nabdominal severa associada a dor\nretroesternal. O quadro iniciou há 12h, após o paciente retornar\nde uma festa onde ingeriu grande quantidade de álcool, que ocasionou desconforto abdominal,\nnáuseas e vários episódios de vômitos vigorosos, evoluindo com o quadro doloroso. Nega\nhematêmese. O paciente encontra-se bastante ansioso, com fácies de dor, desidratado e febril\n(38,8°C), FC = 120 bpm, P.A = 100 x 70 mmHg; FR = 30 irpm. A ausculta pulmonar evidenciou\ndiminuição do murmúrio vesicular em base esquerda. Ausculta cardíaca normal. A palpação do\nepigástrio é dolorosa, com defesa voluntária. Leucograma = 26.000; hematócrito = 37% e\nhemoglobina = 11 g/dl. Amilase e enzimas hepáticas normais. ECG normal, exceto pela taquicardia.\nRadiografia de tórax evidencia discreta efusão pleural e pneumotórax à esquerda, além de\npneumomediastino. Sobre a avaliação e conduta deste paciente, assinale a alternativa CORRETA:","options":{"A":"O próximo passo na avaliação deste paciente é a endoscopia digestiva alta pelo provável\ndiagnóstico de síndrome de Mallory-Weiss.","B":"A história de ingesta alcoólica sugere lesão aguda da mucosa gástrica e esofagite de refluxo,\nestando indicado o tratamento clínico com bloqueadores de bomba de prótons.","C":"Tomografia computadorizada de tórax com contraste oral e toracotomia precoce provavelmente\nserão decisivos no prognóstico deste paciente.","D":"O esofagograma baritado é o exame mais indicado para o diagnóstico do caso neste momento."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-151990","number":"151990","sourceNumber":"151990","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Excelente combustível para os colonócitos:","options":{"A":"Lisina.","B":"Arginina.","C":"Glutamina.","D":"Ácidos graxos de cadeia curta (butirato)."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-103824","number":"103824","sourceNumber":"103824","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 30 anos queixa-se de dor anal há 7 dias durante e após as evacuações. Às\nvezes, apresenta sangramento vivo ao redor das fezes. O diagnóstico mais provável e conduta a\nser seguida são:","options":{"A":"Hemorroidas grau II - tratamento clínico.","B":"Fissura anal - tratamento cirúrgico.","C":"Fissura anal - tratamento clínico.","D":"Hemorroidas grau III - tratamento cirúrgico."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-82000","number":"82000","sourceNumber":"82000","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual a causa mais comum de hemorragia digestiva alta no mundo?","options":{"A":"Hipertensão portal.","B":"Gastrite erosiva.","C":"Úlcera péptica.","D":"Anti-inflamatórios não hormonais.","E":"Gastrite aguda por álcool."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-81994","number":"81994","sourceNumber":"81994","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Hemorragia Digestiva Alta ocasionada por malformação vascular ao longo da curvatura\nmenor do estômago, localizado na submucosa,\né denominada:","options":{"A":"Úlcera de Curling.","B":"Hemangioma.","C":"Extasia vascular do antro gástrico.","D":"Lesão de Dieulafoy.","E":"Gastrite por estresse."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-81955","number":"81955","sourceNumber":"81955","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Vaso comprometido na úlcera duodenal sangrante.","options":{"A":"Artéria pancreatoduodenal.","B":"Artéria pancreática.","C":"Artéria gastroduodenal.","D":"Artéria gástrica esquerda.","E":"Artéria pilórica."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-60870","number":"60870","sourceNumber":"60870","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre a doença ulcerosa péptica complicada com hemorragia digestiva, é CORRETO\nafirmar que:","options":{"A":"A endoscopia digestiva alta não é o melhor método para controlar o sangramento","B":"Pode-se estimar a perda volêmica pelo exame físico num sangramento agudo","C":"O tratamento para Helicobacter pylori não diminuiu significativamente no número de cirurgias","D":"Pacientes em uso de anti-inflamatórios não hormonais por via oral devem mudar para via\nparenteral","E":"Os antagonistas de receptores H2 (histamina) são tão efetivos quanto os inibidores de bomba de\nprótons no tratamento e prevenção de recidiva"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-49802","number":"49802","sourceNumber":"49802","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A Síndrome de Mallory-Weis geralmente é associada a:","options":{"A":"Doença ulcerosa péptica;","B":"Alcoolismo;","C":"Carcinoma;","D":"Hérnia hiatal;","E":"Monilíase."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-46696","number":"46696","sourceNumber":"46696","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma mulher de 50 anos, procedente de Manaus, chega ao Pronto-Socorro relatando\nhematêmese e melena, iniciada 1 hora antes da admissão. No exame físico realizado em decúbito\ndorsal, não se verifica sinais de hepatopatia crônica, mas se encontra hipocorada, orientada e\ndiscretamente pálida FC 110 bpm PA 110 x 70 mmHg. Sobre o caso, marque a alternativa\nverdadeira:","options":{"A":"A principal hipótese diagnóstica etiológica seria neoplasia gástrica, já que é a causa mais\ncomum no mundo.","B":"Os sinais vitais da paciente são os melhores parâmetros para se estimar a gravidade da perda\nvolêmica.","C":"Deve ser pesquisado algum sintoma sugestivo de infecção pelo Helicobacter pylori por ser a\nprincipal causa de úlcera péptica.","D":"A reposição volêmica deve ser feita preferencialmente após o resultado da endoscopia digestiva\nalta.","E":"Deve ser feita colonoscopia antes da endoscopia pelo risco elevado de neoplasia de cólon."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-34130","number":"34130","sourceNumber":"34130","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A anomalia congênita mais encontrada em intestino delgado:","options":{"A":"Tumor carcinoide.","B":"Ileite regional.","C":"Divertículo de Meckel.","D":"Hamartomas.","E":"Pneumatose."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-26498","number":"26498","sourceNumber":"26498","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual é a anomalia congênita mais frequente do trato gastrointestinal:","options":{"A":"Estenose Hipertrófica de Piloro","B":"Polipose familiar","C":"Anus imperfurado","D":"Divertículo de Meckel","E":"Pâncreas anular"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-26687","number":"26687","sourceNumber":"26687","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem de 50 anos de idade, com história de lombalgia crônica usuário de diclofenaco\ndá entrada no Pronto-Socorro com quadro de\nHematêmese e melena. Ao exame clínico de\nadmissão apresenta-se descolorado com FC=120bpm e PA= 90x60 mmHg. Considerando o\ntratamento inicial e a avaliação diagnóstica realizados neste caso é correto afirmar que:","options":{"A":"Deve-se realizar a endoscopia digestiva alta mesmo com instabilidade hemodinâmica na\ntentativa do controle hemostáticos do foco hemorrágico","B":"Deve-se realizar a endoscopia digestiva alta após radiografia de abdome para descartar\nabdome agudo perfurado","C":"A avaliação clínica permite excluir sangramento ativo, e o doente deve ser mantido em\nobservação, com prescrição de omeprazol endovenoso e pedido de endoscopia eletiva","D":"A endoscopia digestiva alta deve ser realizada somente após a reposição volêmica e\nestabilização hemodinâmica","E":"A avaliação clínica permite excluir sangramento ativo e o paciente pode receber alta com\npresecrição de omeprazol"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-26690","number":"26690","sourceNumber":"26690","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre divertículo de Meckel, qual a alternativa que está errada:","options":{"A":"É considerado divertículo verdadeiro","B":"Representa uma obliteração incompleta de ducto vitelino ou onfalomesentérico","C":"Surge na borda mesentérica pelo íleo terminal","D":"Está presente em 1 a 2% da população","E":"Ocasionalmente, tecido ectópico é encontrado no divertículo"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-10021","number":"10021","sourceNumber":"10021","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente dá entrada no pronto-socorro com hematêmese e melena. Qual é a alternativa\ncorreta?","options":{"A":"A principal causa de hemorragia digestiva alta é a úlcera gástrica pelo Helicobacter pylori.","B":"A endoscopia digestiva é procedimento inicial para estabilização do paciente em hemorragia\nvolumosa.","C":"A transfusão sanguínea nestes pacientes depende essencialmente da hemoglobina e do\nhematócrito.","D":"Todo paciente cirrótico deve fazer profilaxia com antibioticoterapia quando ocorrer hemorragia\ndigestiva.","E":"A cirurgia ainda é principal tratamento no sangramento por úlcera péptica."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-249714","number":"249714","sourceNumber":"249714","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A causa mais frequente de hemorragia digestiva baixa em pacientes na sexta e sétima\ndécadas de vida é:","options":{"A":"neoplasia.","B":"angiodisplasia.","C":"polipose colônica.","D":"doença hemorroidária.","E":"doença diverticular do cólon."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-249993","number":"249993","sourceNumber":"249993","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Jovem de 19 anos após abuso de cocaína dá entrada em sala de emergência trazido\npelo serviço de resgate apresentando hematêmese\nfranca, em grande volume, de início há 10\nminutos. Na admissão em sala de emergência apresenta-se em mal estado geral, descorado,\npálido, comatoso, apresentando vários episódios de vômitos em grande quantidade. Pressão\narterial: 80x40mmHg, Frequência cardíaca: 145bpm, Frequência respiratória: 31irpm, Saturação de\noxigênio periférica: 89%. A conduta mais adequada neste momento, respectivamente por ordem de\nprioridade é:","options":{"A":"1- Endoscopia digestiva alta para diagnóstico e tratamento da lesão; 2- intubação orotraqueal; 3-\nreposição volêmica.","B":"1- Endoscopia digestiva alta para diagnóstico e tratamento da lesão; 2- reposição volêmica; 3-\nintubação orotraqueal.","C":"1- Intubação orotraqueal; 2-endoscopia digestiva alta para tratamento da lesão; 3- reposição\nvolêmica.","D":"1-Intubação orotraqueal e reanimação volêmica; 2- endoscopia digestiva alta para diagnóstico e\ntratamento."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-134745","number":"134745","sourceNumber":"134745","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à úlcera péptica hemorrágica, é CORRETO afirmar que:","options":{"A":"É uma das causas mais frequentes de internação hospitalar.","B":"A úlcera duodenal é responsável por 25 a 30% das hemorragias digestivas altas.","C":"A úlcera gástrica é responsável por cerca de 20% das hemorragias digestivas altas.","D":"Todas anteriores estão corretas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-134770","number":"134770","sourceNumber":"134770","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual é a maneira CORRETA da utilização do balão de Sangstaken Blakemore?","options":{"A":"200 ml no Estômago e 40 mmHg no Esôfago.","B":"400 ml no Estômago e 40 mmHg no Esôfago.","C":"150 ml no Estômago e 30 mmHg no Esôfago.","D":"200 ml no Estômago e 20 mmHg no Esôfago."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-111867","number":"111867","sourceNumber":"111867","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 45 anos, sexo masculino, é atendido no pronto-socorro referindo quadro de\ndor surda de hipocôndrio direito de moderada intensidade. Sendo que o mesmo refere que ficou\ninternado, em outro serviço, há 15 dias, onde sofreu acidente de trânsito, que durante o exame, só\nfoi diagnosticado fraturas de 3 arcos costais inferiores direitos, recebendo alta após 48 horas de\ninternação. Durante o seu presente exame clínico, paciente encontra-se BEG, estável\nhemodinamicamente, hipocorado, ++/4 ictérico ++/4, toque retal apresenta melena, abdome flácido\nsem sinais de peritonite, leve dor à palpação de hipocôndrio direito. Com relação a esse caso, qual\né o PRINCIPAL diagnóstico?","options":{"A":"Abdome agudo traumático necessita de cirurgia de urgência.","B":"Hemobilia.","C":"Cirrose hepática descompensada + varizes de esôfago sangrante.","D":"Úlcera perfurada."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-292804","number":"292804","sourceNumber":"292804","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente cirrótico de 56 anos é admitido na emergência com hematêmese\nimportante. Os exames detectaram uma queda\nde hemoglobina de 14 g/dl (referência de exame\nrealizado 1 mês atrás) para 6 g/dl. Inicialmente, foi realizada a reposição volêmica e medicado com\ninibidor de bomba de prótons, vasopressina e vitamina K. Aparentemente, apresenta uma remissão\ndo sangramento e uma endoscopia foi solicitada. Qual das seguintes fontes de sangramento\napresenta maior risco de recorrência da hemorragia para esse paciente?","options":{"A":"Laceração de Mallory-Weiss.","B":"Varizes gastroesofágicas.","C":"Gastropatia hipertensiva.","D":"Úlcera Forrest IIb."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-350865","number":"350865","sourceNumber":"350865","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher de 54 anos hipertensa e diabética, em uso habitual de suas medicações, é\nsubmetida a drenagem percutânea de abscesso hepático em segmento VIII, um dreno do tipo \"pig\ntail\" é deixado. A drenagem foi eficaz e inicialmente correspondeu a 360ml de aspecto\nachocolatado. Dois dias depois do procedimento, a paciente refere fezes pretas e mal cheirosas,\ncerca de 5 episódios, drenagem sanguinolenta pelo dreno e vômitos com sangue. Ao exame está\npálida, tendo sido iniciado reposição volêmica e de hemoderivados. Sua hemoglobina estava\n7,5g/dl antes da transfusão. Coagulograma normal. Apesar das medidas, o aspecto da fezes e do\ndreno continua inalterado. Qual medida deve ser submetida essa paciente nesse momento?","options":{"A":"Retirada do dreno \"pig tail\" e observação.","B":"Embolização hepática por cateterização arterial.","C":"Seguestrectomia hepática ou destelhamento do abscesso.","D":"Colangiografia endoscópica retrógrada e passagem de stent."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-259707","number":"259707","sourceNumber":"259707","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Criança, sexo masculino, 4 anos, acompanhado da mãe que relata sangramento retal\nmaciço há 3 horas associado à taquicardia e sonolência. Nega dor abdominal. Ao toque retal, sem\nsangue em dedo de luva. Após reposição volêmica e estabilidade hemodinâmica, foi realizada\nendoscopia digestiva alta que foi normal. Qual o diagnóstico mais provável?","options":{"A":"Trombose de veia porta.","B":"Divertículo de Meckel.","C":"Enterocolite necrotizante.","D":"Intussussepção ileo-cólica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-172988","number":"172988","sourceNumber":"172988","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher de 22 anos procura atendimento em unidade de pronto atendimento por queixa\nde dor anal que a incomoda há cerca de um\nmês. Na anamnese, a queixa se revelou como uma\ndor intensa às evacuações, persistindo a sensação de ardor por algumas horas após o episódio\nevacuatório. A paciente também refere a presença de nodulação perianal anterior de consistência\ncarnosa, sangramento anorretal intermitente em pequena quantidade (no papel) durante os\nesforços evacuatórios e dificuldade de evacuação devido a fezes endurecidas, desde o início da\nvida adulta. Toma menos de um litro de água por dia e consome frutas, verduras e legumes de\nmaneira irregular. Ao exame proctológico, a paciente apresenta dor, porém permite a inspeção\nanal. Não permite o toque retal nem a anuscopia, devido à dor. Com base no exposto acima, qual a\nconduta mais CORRETA a ser tomada?","options":{"A":"Realizar exame sob sedação para elucidar o quadro e definir a necessidade de cirurgia\nposteriormente.","B":"Solicitar avaliação cirúrgica de urgência para tratamento da trombose hemorroidária interna\nprolapsada.","C":"Indicar a drenagem do abscesso com prescrição de antibióticos, analgésicos e tratamento\nposterior da fístula.","D":"Recomendar anti-inflamatórios, banho de assento, aumento da ingesta de água e fibras, além de\nacompanhamento."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":["question_bank/media/medcurso/med-cirurgia-med-cir-03/172988.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-150842","number":"150842","sourceNumber":"150842","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Menina de 2 anos é atendida no ambulatório de Pediatria, com história de ter\napresentado dois episódios de evacuações com\nsangue vermelho vivo profuso, nos últimos 3\nmeses. Nega história de dor abdominal e febre, mesmo durante os eventos acima. Nega ainda\nalterações outras do hábito intestinal no período intercrise. Criança eutrófica com exame físico\nnormal, exceto por palidez cutâneo-mucosa. Toque retal com fezes normais na ampola. Genitores\ntrazem consigo hemograma realizado no dia anterior à consulta que revela hemoglobina de 7 g/dL.\nConsiderando a hipótese diagnóstica mais provável, qual dos seguintes exames melhor definirá a\nfonte de sangramento?","options":{"A":"Enema opaco.","B":"Colonoscopia.","C":"Ultrassonografia de abdome.","D":"Cintilografia com 99mTc-pertecnetato."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-37398","number":"37398","sourceNumber":"37398","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A.F.C., masculino, 84 anos, foi admitido em hospital secundário com quadro de\nenterorragia de grande volume. Foi tratado\ncom jejum, hidratação com 3 litros de cristaloide e 2\nunid. de concentrado de hemácias. Após estabilização hemodinâmica, o paciente foi transferido\npara uma unidade terciária de referência. Ao ser admitido, apresentava sudorese e palidez\ncutaneomucosa. PA = 90 x 60, e FC = 108 bpm. Durante o exame, apresentou novo episódio de\nsangramento vermelho-vivo de grande monta. Assinale a opção que melhor corresponde à conduta\ndiagnóstica e/ou terapêutica para esse paciente.","options":{"A":"O paciente deve ser encaminhado para a realização de enema opaco que pode ser diagnóstico\ne terapêutico.","B":"O ressangramento indica tratamento cirúrgico imediato.","C":"O exame de escolha, nesse momento, é a colonoscopia diagnóstica e terapêutica.","D":"A cintilografia com hemácias marcadas é uma ótima opção de exame diagnóstico.","E":"A arteriografia seletiva é o exame de escolha nessa situação, podendo ser terapêutica inclusive."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-30929","number":"30929","sourceNumber":"30929","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente admitido em emergência hospitalar com quadro de hemorragia digestiva baixa\nintensa e incoercível. Realizada angiografia diagnóstica, mas o sítio de origem de sangramento não\nfoi identificado. Após reposição sanguínea e instituição de medidas clínicas habituais, a melhora\nnão foi satisfatória. Diante do risco de posterior deterioração hemodinâmica do paciente, qual a\nmedida emergencial que se impõe?","options":{"A":"Laparoscopia de urgência e procura do foco primário de sangramento.","B":"Laparotomia exploradora e colectomia total.","C":"Lavagem retal contínua por sonda retal.","D":"Clister evacuativo.","E":"Laparotomia exploradora e colostomia descompressiva em nível do ângulo esplênico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-27760","number":"27760","sourceNumber":"27760","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre as hemorragias digestivas baixas (HDB), assinale o item ERRADO.","options":{"A":"A doença diverticular é a causa mais comum de HDB, ocorrendo em 3 a 5% dos pacientes com\nesta patologia. Sua causa é a ruptura de ramos intramurais do divertículo.","B":"A angiodisplasia ou malformação arteriovenosa acomete o cólon direito em mais de 50% dos\ncasos, sendo responsável por até 20% das causas de HDB.","C":"Os tumores do cólon esquerdo costumam apresentar quadro de sangramento mais frequentes\nque os tumores do cólon direito.","D":"Deve-se realizar a investigação com endoscopia baixa em pacientes portadores de doença\nhemorroidária com um quadro de sangramento volumoso.","E":"Causas incomuns de HDB incluem patologias vasculares como poliarterite nodosa,\ngranulomatose de Wegener e isquêmicas como\ncolite isquêmica e isquemia mesentérica aguda."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-9041","number":"9041","sourceNumber":"9041","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 45 anos, portador de cirrose hepática compensada ( Child A), foi\natendido em um serviço de emergência com hemorragia aguda por varizes de esôfago. Após\nestabilização hemodinâmica, a próxima conduta é:","options":{"A":"Escleroterapia endoscópica","B":"Ligadura elástica das varizes por endoscopia","C":"Infusão endovenosa contínua de octreotide","D":"Implantação de um shunt intrahepático transjugular (TIPS)"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-8822","number":"8822","sourceNumber":"8822","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Atendendo uma chamada de urgência na enfermaria clínica, observa-se um paciente\ncom hematêmese franca. Após exame e manuseio\ninicial, com estabilização dos sinais vitais, é\nvisto no prontuário que o mesmo realizou endoscopia digestiva alta pela manhã, tendo sido\nevidenciado úlcera duodenal não sangrante. Enquanto o serviço de endoscopia prepara-se para\nreceber novamente o paciente, alguns procedimentos cabíveis podem ser realizados. Qual dos\nitens abaixo representa terapêutica desnecessária neste paciente?","options":{"A":"Infusão endovenosa de bloqueador de bomba de prótons.","B":"Passagem de sonda nasogástrica.","C":"Infusão endovenosa de octreotide.","D":"Passagem de sonda de Sengstaken-Blakemore.","E":"Infusão endovenosa de solução cristaloide."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337496","number":"337496","sourceNumber":"337496","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma paciente de 48 anos chega ao hospital com relato de vômitos frequentes há 1 dia,\nprogredindo para dor intensa em região subesternal nas últimas horas. Com base no caso clínico e\nnos conhecimentos médicos correlacionados, julgue o item a seguir. Uma das hipóteses\ndiagnósticas para essa paciente é a de ruptura esofágica associada à síndrome de Mallory-Weiss.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337497","number":"337497","sourceNumber":"337497","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma paciente de 48 anos chega ao hospital com relato de vômitos frequentes há 1 dia,\nprogredindo para dor intensa em região subesternal nas últimas horas. Com base no caso clínico e\nnos conhecimentos médicos correlacionados, julgue o item a seguir. O diagnóstico de uma possível\nperfuração esofágica pode ser feito por meio de uma radiografia do tórax, que pode demonstrar um\nhidropneumotórax, ou de uma esofagografia com contraste.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337498","number":"337498","sourceNumber":"337498","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma paciente de 48 anos chega ao hospital com relato de vômitos frequentes há 1 dia,\nprogredindo para dor intensa em região subesternal nas últimas horas. Com base no caso clínico e\nnos conhecimentos médicos correlacionados, julgue o item a seguir. O tratamento cirúrgico não\nestá indicado para todos os pacientes com perfuração do esôfago, pois a conduta depende de\nfatores como a estabilidade do paciente, a extensão da contaminação e a localização da\nperfuração. Caso o paciente esteja instável, necessitará de uma rápida avaliação e tratamento\nimediato.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337505","number":"337505","sourceNumber":"337505","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. Em mais de 95% dos pacientes com sangramento gastrointestinal\nbaixo, a fonte da hemorragia é o cólon, sendo o intestino delgado apenas ocasionalmente\nresponsável.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337506","number":"337506","sourceNumber":"337506","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A cintilografia com tecnécio-99m é o método mais sensível e\npreciso para localizar o sangramento gastrointestinal, tanto no intestino delgado quanto no grosso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337507","number":"337507","sourceNumber":"337507","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A angiografia seletiva pode detectar hemorragia na faixa de 0,5\na\n1,0 mL/min e geralmente é usada para o diagnóstico de hemorragia contínua, apresentando\ncapacidade terapêutica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337508","number":"337508","sourceNumber":"337508","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. O carcinoma colorretal é uma das causas de hemorragia digestiva\nbaixa, porém é uma causa incomum de sangramento significativo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337509","number":"337509","sourceNumber":"337509","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 68 anos apresentou sangramento via retal recente, cessando\nespontaneamente. Em seguida, procurou o\natendimento médico ambulatorial para iniciar a\ninvestigação da causa desse episódio. Com base no caso descrito e nos conhecimentos médicos\ncorrelatos, julgue o item a seguir. A angiodisplasia também pode ser uma causa de sangramento\ndigestivo baixo, suas lesões são consideradas degenerativas adquiridas e são usualmente\nassociadas à estenose da artéria aorta e à insuficiência renal, especialmente em pacientes idosos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-239254","number":"239254","sourceNumber":"239254","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 52 anos de idade, hipertenso e diabético, vai ao consultório do\ncirurgião com queixa de emagrecimento e\nsangramento vivo pelo ânus há seis meses. Nega\nalterações de diurese ou hábito intestinal. Ao exame físico, o abdome estava pouco distendido, sem\nmassas palpáveis. Realizou-se toque retal, observando-se esfíncter normotônico, sem lesões\npalpáveis, sem hemorroidas, com sangue vivo em dedo de luva. O paciente apresenta exames\nlaboratoriais realizados na UBS que identificam Hb = 9,3, leucócitos = 11.000, plaquetas = 340.000,\nNa = 138, K = 4,2, U = 77 e Cr = 1,94. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. A colonoscopia com biópsia será de\ngrande valia na investigação diagnóstica desse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-239255","number":"239255","sourceNumber":"239255","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 52 anos de idade, hipertenso e diabético, vai ao consultório do\ncirurgião com queixa de emagrecimento e\nsangramento vivo pelo ânus há seis meses. Nega\nalterações de diurese ou hábito intestinal. Ao exame físico, o abdome estava pouco distendido, sem\nmassas palpáveis. Realizou-se toque retal, observando-se esfíncter normotônico, sem lesões\npalpáveis, sem hemorroidas, com sangue vivo em dedo de luva. O paciente apresenta exames\nlaboratoriais realizados na UBS que identificam Hb = 9,3, leucócitos = 11.000, plaquetas = 340.000,\nNa = 138, K = 4,2, U = 77 e Cr = 1,94. Quanto ao caso clínico apresentado e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. A ausência de lesões identificadas pelo\ntoque retal diminui a probabilidade de que a queixa do paciente se deva a uma neoplasia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-177554","number":"177554","sourceNumber":"177554","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 17 anos de idade, procura atendimento na emergência\ndevido ao primeiro episódio de intensa dor,\nedema e calor no sulco interglúteo. No exame físico,\napresenta área de flutuação a cerca de 5 cm do ânus. Não apresenta febre. Considerando o caso\nclínico apresentado e os conhecimentos médicos acerca de cisto sacrococcígeo, julgue o item a\nseguir. Esse cisto é caracterizado pela presença de uma cavidade subcutânea na região\nsacrococcígea com eventual drenagem de secreção por um ou mais orifícios.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-177559","number":"177559","sourceNumber":"177559","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 17 anos de idade, procura atendimento na emergência\ndevido ao primeiro episódio de intensa dor,\nedema e calor no sulco interglúteo. No exame físico,\napresenta área de flutuação a cerca de 5 cm do ânus. Não apresenta febre. Considerando o caso\nclínico apresentado e os conhecimentos médicos acerca de cisto sacrococcígeo, julgue o item a\nseguir. O cisto sacrococcígeo raramente apresenta o trajeto fistuloso na direção cranial.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-177564","number":"177564","sourceNumber":"177564","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 17 anos de idade, procura atendimento na emergência\ndevido ao primeiro episódio de intensa dor,\nedema e calor no sulco interglúteo. No exame físico,\napresenta área de flutuação a cerca de 5 cm do ânus. Não apresenta febre. Considerando o caso\nclínico apresentado e os conhecimentos médicos acerca de cisto sacrococcígeo, julgue o item a\nseguir. São alguns fatores relacionados à infecção do cisto sacrococcígeo: sudorese, higiene\nprecária e obesidade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-177567","number":"177567","sourceNumber":"177567","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 17 anos de idade, procura atendimento na emergência\ndevido ao primeiro episódio de intensa dor,\nedema e calor no sulco interglúteo. No exame físico,\napresenta área de flutuação a cerca de 5 cm do ânus. Não apresenta febre. Considerando o caso\nclínico apresentado e os conhecimentos médicos acerca de cisto sacrococcígeo, julgue o item a\nseguir. Alguns diagnósticos diferenciais desse cisto são: fístula anal, granuloma sifilítico e\nosteomielite sacral.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-177570","number":"177570","sourceNumber":"177570","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 17 anos de idade, procura atendimento na emergência\ndevido ao primeiro episódio de intensa dor,\nedema e calor no sulco interglúteo. No exame físico,\napresenta área de flutuação a cerca de 5 cm do ânus. Não apresenta febre. Considerando o caso\nclínico apresentado e os conhecimentos médicos acerca de cisto sacrococcígeo, julgue o item a\nseguir. Para o tratamento definitivo dessa patologia, a abordagem mais comum é a excisão total do\ncisto e a ferida deixada aberta para fechamento por segunda intenção, podendo levar, em média,\n21 semanas para total cicatrização.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-177594","number":"177594","sourceNumber":"177594","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 17 anos de idade, procura atendimento na emergência\ndevido ao primeiro episódio de intensa dor,\nedema e calor no sulco interglúteo. No exame físico,\napresenta área de flutuação a cerca de 5 cm do ânus. Não apresenta febre. Considerando o caso\nclínico apresentado e os conhecimentos médicos acerca de cisto sacrococcígeo, julgue o item a\nseguir. A curetagem para remoção dos pelos, tecidos de granulação e debris não altera a\ncicatrização da ferida.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-64313","number":"64313","sourceNumber":"64313","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Acerca das afecções infecciosas que podem acometer a região anorretal, julgue o item\nsubsequente. Os abscessos são causados, geralmente, pelo acúmulo de pus em uma cavidade\nnos tecidos orgânicos ou em órgão cavitário, em consequência de inflamação. A maior parte dos\nabscessos anorretais está associada com a doença de Crohn ou com a tuberculose perianal.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-64316","number":"64316","sourceNumber":"64316","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Acerca das afecções infecciosas que podem acometer a região anorretal, julgue o item\nsubsequente. A antibioticoterapia de amplo espectro deve sempre ser administrada aos pacientes\nsubmetidos à drenagem de abscesso perianal, por esta ser uma operação infectada.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-45743","number":"45743","sourceNumber":"45743","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A hemorragia digestiva ocorre em aproximadamente um sexto dos pacientes com\ndoença ulcerosa péptica em atividade. A etiologia\nmais frequente das úlceras nesses casos é:","options":{"A":"Anti-inflamatórios não hormonais.","B":"Helicobacter pylori.","C":"Doença de Crohn.","D":"Adenocarcinoma.","E":"Síndrome de Zollinger-Ellison."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-49146","number":"49146","sourceNumber":"49146","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A respeito de afecções que podem acometer a região anorretal, julgue o item seguinte.\nUm paciente com hemorroidas internas de\nsegundo grau apresenta, caracteristicamente,\nhematoquezia e prolapso dos mamilos hemorroidários durante a evacuação, os quais necessitam\nde manobras digitais para a sua redução.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-7572","number":"7572","sourceNumber":"7572","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, de 48 anos de idade, proveniente da Bahia, é admitido em um\nhospital geral do Distrito Federal, com\nhematêmese. Sua pressão arterial é de 90/60 mmHg. O\nexame físico apresenta esplenomegalia e ascite, e o hematócrito inicial é de 26%. Nega o uso de\nálcool, porém, refere banhos em lagoa na adolescência e de conhecer o caramujo. A sucção por\nsonda nasogástrica resultou em 300 ml de sangue fresco. Após as reposições iniciais, esse homem\ndeveria ser submetido a:","options":{"A":"Tamponamento esofágico com balão.","B":"Endoscopia digestiva alta.","C":"Esofagograma baritado.","D":"Angiografia seletiva.","E":"Laparotomia exploradora."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-7541","number":"7541","sourceNumber":"7541","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher de 73 anos de idade procura seu consultório com história clínica de\nsangramento digestivo baixo. Relata que há três\nmeses vem apresentando sangramento às\nevacuações. Nega alteração no hábito intestinal. Qual a sequência preferencial na investigação\ndiagnóstica?","options":{"A":"Retossigmoidoscopia, enema opaco e ultrassonografia intrarretal.","B":"Pesquisa de sangue oculto, toque retal e enema opaco.","C":"Dosagem de CEA, retossigmoidoscopia e ultrassonografia intrarretal.","D":"Dosagem de CEA, toque retal e trânsito intestinal.","E":"Toque retal, retossigmoidoscopia e colonoscopia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-366231","number":"366231","sourceNumber":"366231","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma mulher de 42 anos de idade apresenta queixa de \"\"anemia de longa data\"\". À\nrevisão de sistemas, relata episódios\nrecorrentes de epistaxe espontâneas desde a infância, com\nmúltiplas idas ao Pronto Atendimento, especialmente em dias de clima seco. A paciente informa ter\ntratado a anemia anteriormente com diferentes reposições de sulfato ferroso, mas sem alcançar a\ncura. Destaca que considera isso normal, pois seu pai, irmãos e sobrinha enfrentam quadros\nsemelhantes. Quanto aos antecedentes, não apresenta comorbidades prévias. No exame físico,\nobserva-se palidez cutaneomucosa e a presença de várias telangiectasias cutâneas, algumas\nlocalizadas nas palmas das mãos e plantas dos pés, além de afetar a mucosa oral conforme\nimagem acima. Considerando o quadro clínico apresentado, bem como os assuntos correlatos,\nJulgue o item a seguir. A principal hipótese a ser aventada para quadro clínico exposto é Síndrome\nde Osler-Weber-Rendu.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-343398","number":"343398","sourceNumber":"343398","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Acerca das hemorragias digestivas, é INCORRETO afirmar:","options":{"A":"De acordo com a intensidade de sangue perdido, a hemorragia digestiva baixa pode ser\nclassificada em sangramento líquido, acelerado e oculto.","B":"As Úlceras Pépticas são as causas mais frequentes de hemorragia digestiva alta, considerando\nlesões gástricas e duodenais.","C":"Nos pacientes com hemorragia digestiva alta persistente com causa não esclarecida ou em\ncasos com evidências de sangramento\nincontrolável, é realizada a Arteriografia do tronco celíaco e\nda artéria mesentérica superior.","D":"A doença diverticular é a principal causa de hemorragia digestiva baixa devido à sua alta\nprevalência, mesmo com apenas 3% dos pacientes complicando para o sangramento."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-343438","number":"343438","sourceNumber":"343438","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A Hemorragia Digestiva Alta (HDA) é definida como sangramento do trato\ngastrointestinal que ocorre acima do ligamento de\nTreitz ? que se localiza entre o Duodeno e o\nJejuno. Acerca da HDA, é CORRETO afirmar:","options":{"A":"A causa mais comum da hemorragia digestiva alta é a úlcera intestinal, a qual ocorre entre 50%\na 60% dos casos.","B":"As hemorragias classificadas como crônicas são, em sua maioria, sintomáticas e a perda crônica\nde sangue oculto se manifesta com anemia\nbreve.","C":"O manejo do sangramento agudo inclui estabilização hemodinâmica e realização de endoscopia\napós as primeiras 24 horas.","D":"Inquirir sobre história de dispepsia ou uso de anti-inflamatórios não esteroides e ácido\nacetilsalicílico ajuda na investigação\netiológica, especialmente na hipótese de úlcera péptica ativa."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-266413","number":"266413","sourceNumber":"266413","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma paciente do sexo feminino, com 51 anos de idade, procurou uma Unidade Básica\nde Saúde (UBS) com queixas de hematoquezia,\nastenia e dor abdominal leve. Negou alterações de\nritmo intestinal, alteração na característica das fezes e perda de peso. Relatou que tinha sido\nsubmetida a cirurgia para tratamento de hemorroidas havia 5 anos. No exame físico da paciente, o\nmédico constatou, de relevante, somente mucosas moderadamente hipocoradas. Considerando\nesse caso clínico hipotético, julgue o item a seguir. No momento, bastam o tratamento da anemia e\no acompanhamento dos sintomas.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-266414","number":"266414","sourceNumber":"266414","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma paciente do sexo feminino, com 51 anos de idade, procurou uma unidade básica\nde saúde (UBS) com queixas de hematoquezia,\nastenia e dor abdominal leve. Negou alterações de\nritmo intestinal, alteração na característica das fezes e perda de peso. Relatou que tinha sido\nsubmetida a cirurgia para tratamento de hemorroidas havia 5 anos. No exame físico da paciente, o\nmédico constatou, de relevante, somente mucosas moderadamente hipocoradas. Considerando\nesse caso clínico hipotético, julgue o item a seguir. O médico da UBS deve solicitar colonoscopia\npara investigação da hematoquezia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-266415","number":"266415","sourceNumber":"266415","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma paciente do sexo feminino, com 51 anos de idade, procurou uma unidade básica\nde saúde (UBS) com queixas de hematoquezia,\nastenia e dor abdominal leve. Negou alterações de\nritmo intestinal, alteração na característica das fezes e perda de peso. Relatou que tinha sido\nsubmetida a cirurgia para tratamento de hemorroidas havia 5 anos. No exame físico da paciente, o\nmédico constatou, de relevante, somente mucosas moderadamente hipocoradas. Considerando\nesse caso clínico hipotético, julgue o item a seguir. A paciente não deve preocupar-se com a\nhematoquezia, pois tem antecedentes de doença hemorroidária, e essa deve ser a causa do\nsangramento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-159571","number":"159571","sourceNumber":"159571","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo feminino, de cinquenta e três anos de idade, com quadro de anemia\ncrônica por deficiência de ferro, compareceu a serviço médico, apresentando pesquisa de sangue\noculto nas fezes com resultado positivo e os resultados de três videoendoscopias digestivas altas e\nduas colonoscopias, que indicaram boas condições de preparo, sem evidências de fonte de\nsangramento visível. Os exames foram realizados em um centro de referência para hemorragia\ndigestiva. A paciente negou ocorrência anterior de sangramento digestivo visível. Considerando\nesse caso clínico, julgue o seguinte item. Em relação à abordagem clínica dessa paciente, o exame\nmais adequado para se estabeler o diagnóstico inicial seria a enteroscopia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-158078","number":"158078","sourceNumber":"158078","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 86 anos de idade está realizando investigação de quadro de anemia\nmicrocítica e hipocrômica com hemoglobina de\n6 mg/dl, ferro sérico diminuído e ferritina diminuída.\nRDW aumentado e reticulócitos normais. Já realizou múltiplos tratamentos com ferro IV, com\nmelhora parcial do quadro, mas com queda da hemoglobina sempre que suspende a medicação.\nEla refere alguma perda de peso nos últimos anos, mas o atribui ao fato de estar comendo menos\npor não se adaptar à nova prótese dentária. A endoscopia digestiva alta indicou apenas gastrite\natrófica. A colonoscopia foi normal. A pesquisa de sangue oculto nas fezes foi positiva. Exceto pela\npalidez cutânea, o exame físico está normal. A única medicação que a paciente utiliza é o AAS, há\nmuitos anos, sem saber exatamente o motivo. No que tange ao caso clínico exposto, assinale a\nalternativa CORRETA:","options":{"A":"O tratamento deve ser realizado com vitamina B12 intramuscular por toda a vida.","B":"O uso de cápsula endoscópica deve ser considerado.","C":"A presença de sangue oculto positivo em usuários de AAS é comum, não exigindo maiores\ninvestigações nesse caso.","D":"O diagnóstico final dessa paciente é de síndrome de fragilidade do idoso.","E":"A presença de corpúsculos de Pappenheimer é esperada na hematoscopia."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-97844","number":"97844","sourceNumber":"97844","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma paciente com 32 anos de idade comparece à consulta na unidade básica de\nsaúde com queixa de secreção de odor fétido e\naspecto purulento em região perianal. Relata que,\nhá cerca de 20 dias, apresentou quadro de dor intensa na mesma região por cerca de cinco dias,\ncom melhora imediata após a saída de pus em grande quantidade. Refere ter realizado tratamento\npara fissura anal há cerca de dois anos. Ao exame proctológico, apresentava orifício posterior a\ncerca de 1 cm da borda anal, com saída de secreção à expressão, palpação retal sem alterações,\nanuscopia sem alterações. Qual o diagnóstico e conduta CORRETOS?","options":{"A":"Fissura anal; iniciar tratamento clínico com agentes formadores de bolo fecal e nitratos\ntópicos.","B":"Fístula anorretal; orientar quanto à higiene e sintomatologia e referenciar ao\ncoloproctologista.","C":"Fissura anal; iniciar tratamento clínico com analgésicos e referenciar ao coloproctologista.","D":"Fístula anorretal; referenciar ao pronto-socorro com indicação de cirurgia de urgência."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-97759","number":"97759","sourceNumber":"97759","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem com 36 anos de idade é admitido na emergência apresentando vômitos\ncom sangue vivo em grande quantidade e\ninformando ter apresentado três episódios semelhantes\nnas últimas duas horas. Ao exame, encontra-se em mau estado geral; com palidez\n\ncutâneo-mucosa; taquicárdico; pressão arterial = 80 x 50 mmHg; fígado não palpável; baço\npalpável a 3 cm do rebordo costal esquerdo.\nTem antecedentes de etilismo, ingerindo um litro de\nbebida destilada por dia, nos últimos oito anos. A causa da hemorragia digestiva e o manejo inicial\nCORRETO desse paciente são:","options":{"A":"Gastrite erosiva, devendo-se primeiramente realizar a endoscopia digestiva para caracterizar e\ninterromper os pontos de sangramento.","B":"Esofagite, sendo fundamental a reposição volêmica imediata com sangue total e plasma fresco,\ncom vistas a manter a hemoglobina acima de 11\ng/dl.","C":"Hipertensão portal, recomendando-se a reposição volêmica, inicialmente com cristaloides e\nendoscopia digestiva alta entre 2 e 24 horas do atendimento.","D":"Síndrome de Mallory-Weiss, devendo-se fazer a reposição volêmica imediata com coloide,\nsendo a endoscopia digestiva alta contraindicada nessa fase."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-75518","number":"75518","sourceNumber":"75518","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher com 57 anos de idade deu entrada na Emergência apresentando, há um dia,\ncinco episódios de evacuações com sangue\nvermelho-vivo e em grande quantidade. Na admissão\napresenta pressão arterial = 70 x 50 mmHg, frequência cardíaca = 164 bpm, sudorese profusa e\nintensa palidez cutaneomucosa. O exame do abdome é normal e no exame proctológico são vistas\nhemorroidas Grau II. Foi administrado O2 nasal, hidratação com 2 litros de Ringer Lactato em\nacesso venoso periférico e a paciente encontra-se estável hemodinamicamente após seis horas da\nadmissão. Com base no quadro clínico descrito, entre as opções abaixo, a próxima conduta\ndiagnóstica e/ou terapêutica é:","options":{"A":"angiografia e possível embolização para diagnóstico e terapêutica.","B":"vasopressina EV para diminuir o sangramento e sua recorrência.","C":"enema opaco para diagnóstico e hemostasia.","D":"tomografia com contraste para diagnóstico.","E":"colonoscopia após preparo intestinal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-75479","number":"75479","sourceNumber":"75479","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher com 41 anos de idade procurou a Unidade de Pronto Atendimento com relato de\ndor anal há três dias e, há cerca de seis horas, notou sangramento anal vermelho-vivo entremeado\ncom coágulos. Nega alteração de hábito intestinal e história familiar de neoplasia colorretal. Ao\nexame observa-se uma nodulação perianal com cerca de 1 cm de diâmetro, arroxeada e com\nlaceração central por onde se extrui um coágulo sanguíneo. O toque retal foi muito doloroso e não\nevidenciou tumores ou presença de sangue nas fezes. Com base nessas informações, a conduta\ncorreta é:","options":{"A":"fazer a esclerose do vaso sangrante.","B":"encaminhar para cirurgia de urgência.","C":"realizar a trombectomia no momento do exame.","D":"fazer ligadura elástica para hemostasia do vaso\nsangrante.","E":"prescrever anti-inflamatório não esteroidal e observar o sangramento."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-137591","number":"137591","sourceNumber":"137591","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem de 46 anos de idade comparece à Unidade Básica de Saúde (UBS)\nqueixando-se de episódio de vômito em grande quantidade, com sangue vivo, há um dia,\napós libação alcoólica. Nega episódio similar anterior , mas já foi internado para \"tratar\ndoença no fígado\" (sic). Hoje apresentou fezes diarreicas em grande volume, fétidas e\nenegrecidas. Sente-se fraco e a \"vista escurece\" sempre que se levanta. Ainda não urinou\nhoje. Ao\n\nexame físico: regular estado geral, emagrecido, palidez cutâneo-mucosa (++/4+), desidratado\n(+++/4+), anictérico, descamação superficial da\npele em extremidades, P A = 90 x 60 mmHg, pulso\n\n= 110 bpm, abdome globoso, presença de ascite, aranhas vasculares e circulação colateral\nperiumbilical. O paciente foi transferido\npara uma Unidade de Emergência, onde se firmou o seu\ndiagnóstico e foram tomadas as medidas emergenciais adequadas ao caso. Qual o diagnóstico\nmais provável e que medidas emergenciais devem ter sido adotadas?","options":{"A":"Trata-se da síndrome de Mallory Weiss. As medidas emergenciais incluem lavagem\ngástrica com solução salina gelada, reposição\nvolêmica e inibidores de bomba de prótons.","B":"Trata-se da síndrome de Mallory Weiss. As medidas emergenciais incluem reposição\nvolêmica e endoscopia para cauterização dos pontos de sangramento.","C":"Trata-se da síndrome de Mallory Weiss. As medidas emergenciais incluem lavagem\ngástrica com solução salina gelada, cauterização\ndos pontos de sangramento e inibidores\nde bomba de prótons.","D":"Trata-se de rotura de varizes esofágicas. As medidas emergenciais incluem reposição\nvolêmica e endoscopia para ligadura endoscópica das varizes esofágicas.","E":"Trata-se de rotura de varizes esofágicas. As medidas emergenciais incluem reposição\nvolêmica e passagem de balão de Sengstaken-Blakemore."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-30959","number":"30959","sourceNumber":"30959","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem de 75 anos de idade foi atendido em serviço de emergência com relato de\nenterorragia há cerca de 3 horas. No momento do atendimento, apresentava frequência de pulso\nde 120 batimentos por minuto e pressão arterial de 100 mmHg x 60 mmHg. Tendo como referência\nesse quadro clínico, julgue o item: O exame com radionuclídeos, usando-se eritrócitos marcados\ncom tecnécio 99 m, é um método que apresenta elevada sensibilidade, porém é pouco preciso para\na localização do ponto de sangramento.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-30964","number":"30964","sourceNumber":"30964","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem de 75 anos de idade foi atendido em serviço de emergência com relato de\nenterorragia há cerca de 3 horas. No momento do atendimento, apresentava frequência de pulso\nde 120 batimentos por minuto e pressão arterial de 100 mmHg x 60 mmHg. Tendo como referência\nesse quadro clínico, julgue o item: A maioria dos pacientes que apresenta o quadro clínico relatado\nnecessita de tratamento operatório de urgência.","options":{"A":"Certo.","B":"Errado."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-138596","number":"138596","sourceNumber":"138596","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, com 55 anos de idade, alcoólatra, em acompanhamento ambulatorial devido a\ncirrose hepática, comparece ao Pronto-Socorro com hematêmese. Clinicamente se apresenta\ntaquipneico, descorado, pulso fi no, pressão arterial de 90 x 60 mmHg. Foi submetido a endoscopia\ndigestiva alta que mostrou varizes esofágicas, com sangramento ativo. A próxima conduta para\nesse paciente deve ser","options":{"A":"iniciar antibioticoterapia profi lática.","B":"iniciar somatostatina.","C":"iniciar reposição volêmica.","D":"passar balão de Sengsaken-Blakemore.","E":"realizar escleroterapia endoscópica."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-138729","number":"138729","sourceNumber":"138729","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente, com 55 anos de idade, etilista crônico, procurou um pronto-atendimento\ncom hematêmese e alteração do nível de consciência.\nAo exame físico, observou-se indivíduo\nemagrecido, agitado, com pressão arterial de 80 x 50 mmHg, pálido, taquipneico, com moderada\nascite. Após internação, os exames laboratoriais revelaram dosagem de albumina de 2,6 g/dL,\nbilirrubina de 3,5 mg/dL, INR (International Normalized Ratio) = 2,0 e sorologia positiva para vírus\nda hepatite C. As enzimas hepáticas encontravam-se elevadas e a razão entre AST/ALT duas\nvezes maior que o normal. A dosagem de GGT estava elevada. Qual a causa principal de\ndescompensação clínica deste paciente?","options":{"A":"Baixo débito cardíaco.","B":"Ingestão elevada de álcool.","C":"Hipoalbuminemia.","D":"Intoxicação medicamentosa.","E":"Reativação da hepatite crônica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-22144","number":"22144","sourceNumber":"22144","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Considerando que um homem de 60 anos de idade chegue a um ambulatório com\nqueixa de hematoquezia e tenesmo,\napresentando, ainda, alteração do ritmo intestinal com\nmucorreia eventual, julgue o item que se segue. Caso sejam encontrados, na anuscopia, mamilos\nhemorroidários de terceiro grau, não haverá necessidade de realização de colonoscopia.","options":{"A":"certo","B":"errado"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-8648","number":"8648","sourceNumber":"8648","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As doenças do aparelho digestório e do fígado representam causas frequentes de\ninternação hospitalar em unidades do Sistema Único de Saúde (SUS). Julgue o item, acerca\ndessas afecções. O uso imediato de medicamentos que induzem vasoconstrição esplâncnica\n(terlipressina e octreotídeo, por exemplo) é recomendado em pacientes com hemorragia digestiva\nalta secundária à hipertensão portal, especialmente em casos em que o exame endoscópico tiver\nsua realização retardada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-368199","number":"368199","sourceNumber":"368199","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um senhor de 72 anos de idade, portador de doença arterial coronariana, em uso de\nantiagregação plaquetária, foi admitido no hospital com relato de ter apresentado vários episódios\nde perda de sangue vivo retal nos últimos dois dias. Ao exame, apresentava-se alerta, descorado,\ncom enchimento capilar normal; FC = 105 bpm; PA = 120x70 mmHg e T = 36,5 °C. Nesse caso, o\nexame que deve ser solicitado para identificação do sítio de sangramento desse paciente é","options":{"A":"cintilografia com hemácias marcadas.","B":"enema com bário.","C":"arteriografia.","D":"colonoscopia."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-352198","number":"352198","sourceNumber":"352198","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"S.A.P., 57 anos, feminina, hipertensa controlada (com uso de atenolol, losartana e\nhidroclorotiazida), procura atendimento médico com queixa de dor abdominal em fossa ilíaca\nesquerda de início há 4 dias, associada, náuseas, febre e calafrios. Frequência cardíaca: 98bpm,\npressão arterial: 110/70mmHg, abdome doloroso difusamente à palpação, com defesa em\nquadrante inferior esquerdo, sem sinais de irritação peritoneal. Hemoglobina: 13,1mg/dL,\nLeucócitos: 17.200/mm³, Proteína C Reativa (PCR): 54mg/dL. Tomografia de abdome mostra\ndivertículos em sigmoide, associado a espessamento parietal deste segmento e densificação dos\nplanos adiposos pericólicos, abscesso pericólico de 3 cm, com focos gasosos adjacentes. Assinale\na alternativa com a conduta terapêutica imediata mais apropriada para o caso:","options":{"A":"Drenagem percutânea.","B":"Colonoscopia.","C":"Antibioticoterapia endovenosa.","D":"Cirurgia de Hartmann."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-351589","number":"351589","sourceNumber":"351589","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Dentre as alternativas a seguir, assinale a patologia MAIS encontrada com a\nenteroscopia intraoperatória nos sangramentos do intestino delgado.","options":{"A":"Tumor.","B":"Pólipo.","C":"Ectasia vascular.","D":"Divertículo de jejuno."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-354093","number":"354093","sourceNumber":"354093","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 70 anos, sexo masculino, admitido no PS com quadro de Hemorragia\nDigestiva Baixa (HDB). Relata dois episódios de\nsangramento, hoje não associados a evacuação.\nNo momento paciente estável, lúcido e orientado, acianótico e normocorado. Pressão arterial\n120x70mmHg e frequência cardíaca de 80 bpm. Frente ao caso em questão, assinale a alternativa\ncorreta:","options":{"A":"A maioria cessa espontaneamente e a colonoscopia é o exame padrão-ouro.","B":"A avaliação inicial compreende o exame proctológico e a pesquisa de sangue oculto fecal.","C":"A abordagem cirúrgica está indicada no 3° episódio de hemorragia digestiva baixa quando a\ndoença diverticular for a causa.","D":"A forma hipertônica da doença diverticular é causa de sangramento maciço e está indicada a\narteriografia.","E":"A neoplasia colorretal é a principal causa de HDB nessa faixa etária e está indicada\ncolonoscopia, tomografia e solicitação de marcadores tumorais."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-321153","number":"321153","sourceNumber":"321153","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à hemobilia, assinale a alternativa CORRETA:","options":{"A":"A colelitíase é a causa mais importante de hemobilia.","B":"O hepatoblastoma é o tumor associado mais comum.","C":"A angioembolização é o tratamento inicial definitivo de escolha.","D":"A cintilografia com hemácias marcadas é a modalidade diagnóstica de escolha."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-314020","number":"314020","sourceNumber":"314020","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"O sangramento gastrointestinal (GI) alto refere-se a sangramentos que se originam do\ntrato GI proximal ao ligamento de Treitz, sendo responsável por quase 80% das hemorragias GI\nsignificativas. Com relação a esses sangramentos, assinalar a alternativa CORRETA:","options":{"A":"As causas de sangramento GI alto são melhor categorizadas em não varicosas ou\nsangramentos relacionados com hipertensão portal.","B":"As causas não varicosas, responsáveis por cerca de 80%, apresentam as lacerações de\nMallory-Weiss como a mais comum.","C":"Quando há confirmação de um sangramento de úlcera péptica, a utilização de IBPs (inibidores\nde bomba de prótons) é indicada, porém não tem\nmostrado a capacidade de reduzir o risco de\nressangramento e a necessidade de intervenção cirúrgica.","D":"A maioria das lacerações de Mallory-Weiss ocorre ao longo da curvatura maior e, menos\ncomumente, na curvatura menor.","E":"O esôfago é frequentemente um local de hemorragia significativa, como resultado de esofagite."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-306706","number":"306706","sourceNumber":"306706","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"L.P.A, 38 anos, sem comorbidades prévias, foi trazida ao hospital após ter apresentado\nepisódio de hematêmese em domicílio. Nega\nalergias. Relata estar em uso de ibuprofeno por conta\nde lombalgia após esforço físico há 15 dias. Foi submetida a endoscopia digestiva alta que\ndemonstrou úlcera gástrica com sangramento ativo difuso. Com relação ao quadro apresentado,\nqual é a classificação de Forrest da úlcera apresentada pela paciente e o risco de ressangramento,\nrespectivamente?","options":{"A":"Forrest IA ? Alto risco de ressangramento","B":"Forrest IB ? Alto risco de ressangramento","C":"Forrest IB ? Baixo risco de ressangramento","D":"Forrest IA ? Baixo risco de ressangramento"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-305003","number":"305003","sourceNumber":"305003","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A respeito do exame físico nos pacientes com hemorragia digestiva baixa (HDB),\nanalise as afirmativas a seguir. I. O exame\nfísico frequentemente é bastante elucidativo em relação\nà etiologia da HDB, além de ser útil na avaliação da extensão do sangramento. II. A presença de\nhipotensão ortostática e choque é menor na HDB do que na hemorragia digestiva alta, o que requer\nmenos transfusão de sangue. III. Pacientes com sangramento de cólon têm uma necessidade\nmenor de transfusão de sangue do que aqueles em que a causa da hemorragia encontra-se no\nintestino delgado. Está(ão) correta(s) a(s) afirmativa(s)","options":{"A":"I, apenas.","B":"I e II, apenas.","C":"III, apenas.","D":"II e III, apenas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-291947","number":"291947","sourceNumber":"291947","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente admitido com hematêmese no Pronto Socorro onde você trabalha. No exame\nfísico paciente se encontra agitado, sudorético, taquipneico, afebril, descorado. Pulsos finos de\n120bpm, PA: 90X50mmHG, ascite e baço palpável. Considerando o caso descrito, é CORRETO\nafirmar que:","options":{"A":"O paciente está em choque hipovolêmico grau 2 necessita de acesso venoso periférico com\njelco calibroso e ressuscitação volêmica com solução hidroeletrolítica.","B":"A hemorragia significativa e pela epidemiologia da hemorragia digestiva alta, no Brasil, a causa\ndeve ser uma úlcera péptica.","C":"O paciente após ressuscitação volêmica adequada deve iniciar análogo da somatostatina e\nendoscopia realizada em até 12 horas.","D":"A escolha de tratamento inicial seria a opção cirúrgica se analisamos a gravidade do caso."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-283888","number":"283888","sourceNumber":"283888","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à hemorragia digestiva baixa, assinale a alternativa correta.","options":{"A":"Acima dos 50 anos, a causa mais frequente é a neoplasia intestinal.","B":"Abaixo dos 50 anos, a causa mais frequente é a angiodisplasia.","C":"O sangramento diverticular raramente cessa espontaneamente.","D":"95% dos casos originam-se do cólon.","E":"Angiodisplasia não é causa de sangramento digestivo baixo, somente de sangramento digestivo\nalto."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-260706","number":"260706","sourceNumber":"260706","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, 65 anos, portador de lesão de Dieulafoy em fundo gástrico\nidentificada em endoscopia digestiva alta com\nsangramento ativo e submetido a duas tentativas de\nterapia endoscópica sem sucesso com evidências de ressangramento e apresentando sinais de\ninstabilidade hemodinâmica. Qual a conduta terapêutica indicada, dentre as abaixo?","options":{"A":"Gastrectomia total.","B":"Esofagogastrectomia com reconstrução em Y de Roux.","C":"Ressecção gástrica proximal.","D":"Gastrectomia subtotal com construção a BII.","E":"Cirurgia de Heller-Pinotti."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-246374","number":"246374","sourceNumber":"246374","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher de 54 anos, apresentando 3 episódios de hematoquezia há 2 horas, chegou ao\npronto-socorro com quadro de hipotensão, taquicardia e sudorese. No exame físico: PA= 90x60\nmmHg, FC=110 bpm e palidez cutânea. Realizada passagem de sonda nasogástrica com saída de\nbile. Visando uma abordagem bem definida e lógica para essa paciente com hemorragia\ngastrointestinal aguda, qual a próxima conduta?","options":{"A":"Endoscopia digestiva alta","B":"Colonoscopia","C":"Endoscopia por cápsula","D":"Colectomia subtotal"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-212937","number":"212937","sourceNumber":"212937","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"No tocante às hemorragias digestivas altas, assinale a INCORRETA:","options":{"A":"A doença ulcerosa péptica é a maior causa de hemorragia digestiva alta.","B":"O H. pylori é associado com recorrência de sangramento em pacientes com úlcera duodenal.","C":"A passagem de sonda nasogástrica é recomendada na maioria dos casos.","D":"A profilaxia de peritonite bacteriana espontânea é recomendada em todos os pacientes com\nhemorragias digestivas altas varicosas.","E":"A eficácia da ligadura é maior que a escleroterapia para pacientes com hemorragia varicosa\naguda."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-220325","number":"220325","sourceNumber":"220325","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente, sexo masculino, 50 anos, assintomático apresentou sangue oculto nas\nfezes como positivo. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"Um paciente normal pode perder até 2,5 ml sangue por dia nas fezes.","B":"O exame deve ser repetido e, se positivo, deve-se investigar com endoscopia digestiva alta e\ncolonoscopia.","C":"A melena pode ser produzida por quantidade acima de 200 ml no estômago.","D":"São causas de hemorragia digestiva alta, as úlceras gastroduodenais, a síndrome de\nMallory-Weis e, de hemorragia digestiva baixa, a doença diverticular dos cólons e a hemobilia."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-199615","number":"199615","sourceNumber":"199615","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente gestante, no primeiro trimestre da gestação, após episódios de vômitos\npersistentes devido à hiperêmese gravídica, deu\nentrada no pronto-socorro apresentando\nhematêmese associada a sinais de choque grau I. Após estabilização do quadro hemodinâmico,\napresentou remissão dos sintomas. Feito a hipótese diagnóstica de síndrome de Mallory-Weiss.\nOptado pela realização de endoscopia. Qual o provável achado no exame endoscópico que\ncomprova o diagnóstico?","options":{"A":"Úlceras em corpo e antro gástrico.","B":"Laceração da mucosa em região de transição esofagogástrica.","C":"Lesão gástrica de provável etiologia neoplástica.","D":"Erosão de mucosa gástrica associado a malformação vascular em pequena curvatura."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-172539","number":"172539","sourceNumber":"172539","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente sexo masculino, previamente hígido, 32 anos inicia quadro súbito de volumosa\nhematêmese, procurando atendimento em hospital de interior onde é inicialmente internado.\n\nRecebe além de cristalóides, omeprazol e sintomáticos, 2 concentrados de hemácias ainda no PS e\nsegue em observação até realizar\nendocospia (EDA) no final da tarde. Durante a observação não\napresenta novos episódios hematêmese. No final da tarde hemoglobina (Hb) 6g/dl e realiza EDA\nque não evidencia sangramento ativo. Permanece internado, apresentando melena volumosa e\nqueda seriada de Hb, recebendo um total de mais de 10 unidades de concentrados de hemácias,\nquando então é transferido ao HECI após cerca de 72 horas do início do quadro. Na admissão ao\nHECI palidez cutânea intensa, torporoso, pele fria, RCR 2t FC 145bpm, 90x60mmHg. Realizada\npassagem de sonda nasogástrica com drenagem de enorme quantidade de sangue vivo. Qual das\nabaixo é a melhor lista de opções iniciais?","options":{"A":"Punção de veia em antebraço com jelco 18, 1000ml de cristalóides, tipagem sanguínea,\nhemograma e coagulograma.","B":"Punção de jugular interna ou femural com cateter de 12fr (tipo hemodiálise), imediata transfusão\ncom O negativo, plasma, plaquetas e\ncristalóides, tipagem sangúinea e exames laboratoriais.","C":"Punção de jugular interna ou subclávia com cateter venoso central, imediata transfusão com O\nnegativo, plasma, plaquetas e cristalóides, tipagem sangúinea e exames laboratoriais.","D":"Punção de duas veias, uma em cada antebraço com jelco 18, 1000ml de cristalóides, tipagem\nsanguínea, hemograma e coagulograma e realização imediata de EDA,","E":"Punção de duas veias, uma em cada antebraço com jelco 18, 1000ml de cristalóides, tipagem\nsanguínea, hemograma e coagulograma."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-172554","number":"172554","sourceNumber":"172554","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente sexo masculino, previamente hígido, 32 anos inicia quadro súbito de volumosa\nhematêmese, procurando atendimento em hospital de interior onde é inicialmente internado.\n\nRecebe além de cristalóides, omeprazol e sintomáticos, 2 concentrados de hemácias ainda no PS e\nsegue em observação até realizar\nendocospia (EDA) no final da tarde. Durante a observação não\napresenta novos episódios hematêmese. No final da tarde hemoglobina (Hb) 6g/dl e realiza EDA\nque não evidencia sangramento ativo. Permanece internado, apresentando melena volumosa e\nqueda seriada de Hb, recebendo um total de mais de 10 unidades de concentrados de hemácias,\nquando então é transferido ao HECI após cerca de 72 horas do início do quadro. Na admissão ao\nHECI palidez cutânea intensa, torporoso, pele fria, RCR 2t FC 145bpm, 90x60mmHg. Realizada\npassagem de sonda nasogástrica com drenagem de enorme quantidade de sangue vivo. Esse\nmesmo paciente após a adoção das medidas que o emergencista julgou apropriada na questão\nanterior, ao ser realizada a EDA o endoscopista refere notar sangramento de aspecto arterial\nproveniente do duodeno distal, sem identificação exata do ponto do sangramento. Assim, além das\nmedidas de suporte apropriadas, qual dessas abaixo é a intervenção seqüencial mais adequada?","options":{"A":"Passagem imediata de balão de Sangstein-Blackmore.","B":"Esclerose com adrenalina nas proximidades do possível local do sangramento.","C":"Realizar colonoscopia imediatamente.","D":"Realizar cintilografia imediatamente para identificar local do sangramento.","E":"Realizar cirurgia de emergência para exploração do duodeno, identificação local sangrante e\ncontrole cirúrgico do sangramento."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-174354","number":"174354","sourceNumber":"174354","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com história de hemorragia digestiva alta de grande volume é submetido à\nendoscopia digestiva alta, em que se evidencia úlcera com sangramento ativo e não pulsátil. Qual a\nclassificação de Forrest?","options":{"A":"Grau Ia.","B":"Grau Ib.","C":"Grau IIa.","D":"Grau IIb.","E":"Grau III."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-174379","number":"174379","sourceNumber":"174379","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sabemos que em mais de 95% dos pacientes com hemorragia digestiva baixa a origem\ndo sangramento encontra-se no cólon. Sendo assim,\nassinale a principal causa de hemorragia\ndigestiva baixa em crianças e adultos, respectivamente:","options":{"A":"Angiodisplasia e doença diverticular.","B":"Divertículo de Meckel e angiodisplasia.","C":"Intussuscepção e doença diverticular.","D":"Intussuscepção e Colite isquêmica.","E":"Divertículo de Meckel e doença diverticular."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-172772","number":"172772","sourceNumber":"172772","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre as hemorragias digestivas baixas, assinale a alternativa incorreta.","options":{"A":"Hemorragia digestiva baixa é definida como um sangramento originário distalmente à válvula\nileocecal.","B":"A taxa de ressangramento após o primeiro episódio de hemorragia por doença diverticular é de\naproximadamente 25%.","C":"Endoclipes podem ser utilizados no tratamento endoscópico do sangramento por divertículo do\ncólon sigmóide.","D":"Embolização superseletiva ocorre ao nível dos vasa recta ou da artéria marginal."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-148531","number":"148531","sourceNumber":"148531","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 78 anos, sexo feminino, é internada com quadro de enterorragia volumosa,\nque cursou com queda de hemoglobina e\ninstabilidade hemodinâmica. Dentre as causas de\nsangramento colorretal, assinale a causa mais comum de sangramento grave:","options":{"A":"Angiodisplasia colônica.","B":"Hemorroida interna.","C":"Colite isquêmica.","D":"Diverticulose.","E":"Úlceras retais."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-127151","number":"127151","sourceNumber":"127151","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em indivíduos adultos, portadores de divertículo de Meckel, o quadro clínico mais\ncomum é:","options":{"A":"Hemorragia.","B":"Perfuração.","C":"Diverticulite.","D":"Hérnia de Littre.","E":"Obstrução intestinal."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-111599","number":"111599","sourceNumber":"111599","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 66 anos apresenta cansaço a médios esforços há 3 meses. Nega dor\nabdominal, melena ou enterorragia. A hemoglobina é 6,1 g/dL, há microcitose e o perfil de ferro é\ncompatível com ferropenia. Neste caso, é correto:","options":{"A":"investigar tubo digestivo apenas se a pesquisa de sangue oculto nas fezes for positiva.","B":"iniciar reposição de ferro até normalização da hemoglobina e investigar tubo digestivo se anemia\nrecidivar.","C":"iniciar investigação endoscópica de lesões no tubo digestivo.","D":"transfundir concentrado de hemácias até atingir hemoglobina de 11 g/dL.","E":"transfundir sangue total até atingir hemoglobina de 11 g/dL."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-101001","number":"101001","sourceNumber":"101001","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Quanto à anatomia do esôfago, marque a alternativa errada.","options":{"A":"O esôfago cervical recebe grande parte de sua irrigação das artérias tireóideas inferiores.","B":"O terço médio do esôfago é suprido por artérias esofágicas vindas diretamente da aorta.","C":"O esôfago abdominal recebe irrigação da artéria gástrica esquerda.","D":"O terço superior é suprido por artérias esofágicas vindas diretamente da aorta.","E":"O terço médio do esôfago recebe irrigação de ramos das artérias brônquicas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-100984","number":"100984","sourceNumber":"100984","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"São fatores de risco para mortalidade na hemorragia gastrointestinal aguda, exceto:","options":{"A":"Idade > 50 anos.","B":"Doença renal.","C":"Pressão arterial sistêmica < 100 mmHg na apresentação.","D":"Necessidade de transfusão.","E":"Hemorragia recorrente."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-59060","number":"59060","sourceNumber":"59060","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Quanto à doença diverticular no idoso, assinale a alternativa correta:","options":{"A":"O termo diverticulose ou doença diverticular é empregado para definir inflamação do divertículo.","B":"A hemorragia por divertículos é a maior causa de hemorragia digestiva baixa no idoso.","C":"O sangramento por doença diverticular no idoso raramente ocorre no paciente com doença\nassintomática não diagnosticada.","D":"A prevalência da doença diverticular é alta a partir dos 40 anos e diminui com o avançar da\nidade.","E":"A diverticulite colônica é mais comum no colo direito."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-59092","number":"59092","sourceNumber":"59092","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A principal complicação do tratameno das fistulas anais é:","options":{"A":"Estenose anal.","B":"Diarreia.","C":"Infecção.","D":"Dor crônica.","E":"Incontinência anal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-43943","number":"43943","sourceNumber":"43943","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Quanto as doenças diverticulares, assinale a alternativa correta:","options":{"A":"O termo diverticulose é empregado para definir a presença do divertículo inflamado.","B":"O termo doença diverticular é empregado para definir a presença do divertículo inflamado.","C":"A hemorragia por divertículo é a maior causa de hemorragia digestiva baixa no idoso e ocorre\nem 3 a 5% dos idosos portadores de doença\ndiverticular.","D":"O sangramento por doença diverticular no paciente idoso raramente ocorre em indivíduos com\ndoença assintomática ou não diagnosticada.","E":"A prevalência da diverticulose colônica diminui com a idade."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-43946","number":"43946","sourceNumber":"43946","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual fármaco utilizado na hemorragia digestiva alta por varizes de esôfago que mostrou\ndiminuição da mortalidade?","options":{"A":"Vasopressina.","B":"Somatostatina.","C":"Terlipressina.","D":"Octreotide.","E":"Todas as alternativas acima."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-23080","number":"23080","sourceNumber":"23080","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A principal característica de uma hemorragia digestiva produzida pela doença\ndiverticular do cólon é:","options":{"A":"estar associada a dor abdominal de forte intensidade.","B":"ocorrer em 65% dos pacientes com doença diverticular do cólon.","C":"cólon direito ser o segmento mais frequente do sangramento.","D":"perda de grande quantidade de sangue nas fezes.","E":"presença de sangue coagulado nas fezes."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-27359","number":"27359","sourceNumber":"27359","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Os divertículos adquiridos e Congênitos mais comuns do Intestino delgado, ocorrem\nrespectivamente com maior freqüência em quais segmentos:","options":{"A":"Ìleo e Jejuno","B":"Jejuno e Ileo","C":"Ileo e Duodeno","D":"Duodeno e Íleo","E":"Duodeno e Jejuno"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-8074","number":"8074","sourceNumber":"8074","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem de 48 anos, transferido do pronto-atendimento com história de hematêmese e\nmelena, de inicio há 12 horas. Já fez consulta há 6 meses com hepatologista por ter sido detectado\nproblema numa doação de sangue. Nega antecedentes de alcoolismo, sabe ser hipertenso e não\nse trata, relatando acidente automobilístico com transfusão sanguinea na adolescência. Exame\nfísico: PA = 100/60 mmHg, FC = 140bpm, com respiração ofegante e agitação psicomotora. Está\ncom veia de grosso calibre puncionada. Hemoglobina = 7,5g/dl. Qual a conduta imediata ?","options":{"A":"Promover expansão volêmica e solicitar endoscopia digestiva alta após estabilização dos sinais\nvitais.","B":"Realizar lavagem gástrica com solução salina gelada e providenciar infusão venosa de\nbloqueador de bomba.","C":"Transfusão de concentrado de hemácias e colher sorologias para hepatites B e C, e exames\nbioquímicos necessários.","D":"Passar balão de Sengstaken-Blackemore e transferir para CTI.","E":"Solicitar endoscopia digestiva alta e colher amostra de sangue para exames de hepatite e\nbioquímicos."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-9415","number":"9415","sourceNumber":"9415","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à hemorragia digestiva por ruptura de varizes de esôfago, assinale a\nalternativa INCORRETA:","options":{"A":"a primeira conduta na suspeita de hemorragia varicosa, é a estabilização da pressão arterial do\npaciente.","B":"em cerca de 2/3 dos pacientes com hemorragia varicosa o sangramento cessa\nespontaneamente.","C":"nos pacientes com suspeita de hemorragia aguda por ruptura de varizes de esôfago, a terapia\nfarmacológica, com somatostatina, octreotide ou terlipressina, deve ser iniciada o mais\nprecocemente possível, antes mesmo da realização da endoscopia digestiva alta.","D":"o ressangramento, embora infrequente, pode ocorrer após controle do sangramento inicial.","E":"a ligadura elástica e a escleroterapia das varizes de esôfago, são métodos igualmente eficazes\nem controlar a hemorragia ativa por ruptura de\nvarizes de esôfago."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-9389","number":"9389","sourceNumber":"9389","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 25 anos, caminhoneiro, relata diarreia e hematoquezia há 6 meses. Obteve\nmelhora inicial com tratamento clínico que não sabe informar. Porém, atualmente queixa-se de\neliminação de sangue e muco pelas fezes. No exame físico observa-se hipertermia e\nemagrecimento. O diagnóstico menos provável dessa condição é:","options":{"A":"Retocolite ulcerativa.","B":"Câncer de cólon.","C":"Colite por medicamentos não-esteroides.","D":"Colite cística profunda.","E":"Doença de Crohn."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-353837","number":"353837","sourceNumber":"353837","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente, 55 anos, chega ao pronto-socorro com queixas de fezes avermelhadas\nbrilhantes e relato de mal-estar súbito.\nExames preliminares sugerem hemorragia gastrointestinal. A\nsituação clínica mais provável que explicaria a presença de sangue vivo nas fezes do paciente é:","options":{"A":"Gastrite crônica com sangramento lento.","B":"Pequenas fissuras anais.","C":"Diverticulite com microhemorragias.","D":"Hemorragias maciças no trato gastrointestinal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-355632","number":"355632","sourceNumber":"355632","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre as hemorragias gastrointestinais está correto afirmar que:","options":{"A":"Os achados do tipo II da classificação de Forrest são correspondentes a hemorragia ativa que\nnecessitam de tratamento endoscópico e, na eventual falha deste, de tratamento cirúrgico.","B":"A cintigrafia com hemácias quando factível, além de ser altamente sensível, consegue definir\ncom detalhe o local do sangramento, orientando,\nassim, quanto ao segmento a ser ressecado na\ndoença diverticular dos cólons.","C":"Comparativamente ao sangramento diverticular, os episódios de hemorragia na ectasia vascular\ncostumam ser menos intensos e têm uma tendência um pouco maior a recidivarem.","D":"Por razões desconhecidas, a maioria dos pacientes com divertículo de Meckel com mucosa\ngástrica ectópica apresenta sangramento entre 35 e 45 anos.","E":"A terapia endoscópica por sangramento devido ectasia vascular do antro gástrico é\n\nbem-sucedida em apenas 10% dos casos, sendo frequente a necessidade de antrectomia para\ncontrole da hemorragia"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-330060","number":"330060","sourceNumber":"330060","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Entre os fatores utilizados para determinar o prognóstico, morbiletalidade e risco de\nrecidiva da hemorragia, NÃO se destacam:","options":{"A":"Persistência no sangramento.","B":"Hematêmese e/ou choque inicial.","C":"Idade avançada (maior de 40 anos).","D":"Aspecto endoscópico da lesão."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-321541","number":"321541","sourceNumber":"321541","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual é a indicação de cirurgia na hemorragia gastrointestinal alta não varicosa?","options":{"A":"Instabilidade hemodinâmica a despeito da reanimação vigorosa.","B":"Falha da primeira técnica endoscópica com associação de dois métodos para controlar a\nhemorragia.","C":"Sangramento lento, porém, contínuo, com necessidade de transfusão maior que 1U a cada 3\ndias.","D":"Presença úlceras maiores que 2 cm."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-342609","number":"342609","sourceNumber":"342609","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre a hemorragia digestiva alta por varizes esofágicas, pode-se afirmar que:","options":{"A":"shunt intra-hepático transjugular portossistêmico (TIPS) está associado a taxas de\nressangramento de até 80% no 1º mês","B":"o balão de Sengstaken-Blakemore deve ser utilizado na admissão enquanto se aguarda a\nrealização de endoscopia digestiva alta","C":"vasopressina deve ser utilizada para iniciar a vasodilatação esplâncnica","D":"o tratamento endoscópico é capaz de controlar a hemorragia em até 90% dos pacientes"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-339776","number":"339776","sourceNumber":"339776","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 70 anos. Diabético descompensado. Há um dia, apresentou dor, edema e\nhiperemia em bolsa escrotal. Nas últimas 6h apresentou choque séptico e foi submetido a\ndesbridamento radical da região escrotal e períneo. Qual antibiótico abaixo deve estar prescrito no\npós-operatório?","options":{"A":"Polimítica B","B":"Azitromicina","C":"Oxicíclina","D":"Eritromicina","E":"Clindamicina"},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337421","number":"337421","sourceNumber":"337421","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Na lesão de Dieulafoy, espera-se encontrar na descrição do exame endoscópico:","options":{"A":"Sangramento arterial com mucosa adjacente íntegra.","B":"Sangramento arterial com úlcera gastroduodenal.","C":"Venoso com cotos varicosos.","D":"Venoso com mucosa adjacente atrófica."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337422","number":"337422","sourceNumber":"337422","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 19 anos de idade é internado para investigação e enterorragia esporádica,\ncom o primeiro episódio há 9 meses. Durante\neste período apresentou necessidade de transfusão\nde hemoderivados algumas vezes. Tem endoscopia e colonoscopia normais. Na última internação\napresentou instabilidade hemodinâmica, refratária a ressuscitação volêmica. Pela indisponibilidade\nde arteriografia e cintilografia, foi submetido à laparotomia. No intraoperatório foi evidenciado\nanomalia de intestino delgado, distando 90 centímetros da válvula ileocecal, na borda\nantimesentérica. Realizada enterectomia e enviado material para exame histopatológico. Assinale a\nalternativa com a principal hipótese diagnóstica.","options":{"A":"Divertículo de Zencker.","B":"Gastrosquise.","C":"Divertículo de Meckel.","D":"Mixoma apendicular."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-337423","number":"337423","sourceNumber":"337423","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 85 anos é internado devido a enterorragia associada à instabilidade\nhemodinâmica. É atendido em sala de emergência,\nrealizada expansão volêmica, transfusão de\nhemoderivados e realizado endoscopia digestiva alta que não evidenciou a fonte do sangramento.\nMantém-se estável, mas ainda apresenta queda de níveis hematimétricos. O próximo passo na\ninvestigação das hemorragias digestivas é:","options":{"A":"Colonoscopia.","B":"Cápsula endoscópica.","C":"Cintilografia com hemácias marcadas.","D":"Arteriografia."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-339791","number":"339791","sourceNumber":"339791","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual é a indicação de cirurgia na hemorragia gastrointestinal alta não varicosa?","options":{"A":"Instabilidade hemodinâmica a despeito da reanimação vigorosa.","B":"Falha da primeira técnica endoscópica com associação de dois métodos para controlar a\nhemorragia.","C":"Sangramento lento, porém, contínuo, com necessidade de transfusão maior que 1U a cada 3\ndias.","D":"Presença úlceras maiores que 2 cm."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-330101","number":"330101","sourceNumber":"330101","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A hemorragia digestiva alta é um problema que vem aumentando por uma série de\nfatores, como excesso no consumo de bebidas\nalcoólicas, hábitos alimentares ruins, presença de\ntumores, e outros. Sobre a hemorragia digestiva alta, é INCORRETO afirmar:","options":{"A":"Idade abaixo de quarenta anos e dispepsia funcional associada são fatores preditivos de\nhemorragia digestiva alta recorrente ou mais grave.","B":"A ocorrência da úlcera duodenal pode causar sangramento digestivo alto devido à ruptura de um\ngrande vaso, como a artéria gastroduodenal.","C":"O tratamento deve incluir, sempre, inibidores da secreção cloridropéptica, evitando-se\nadministrar antiácidos ou sucralfato, que geralmente aderem à parede gástrica.","D":"A principal causa da hemorragia digestiva alta é a falta de equilíbrio nas mucosas dos órgãos do\nsistema digestivo, causando sangramentos."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-346453","number":"346453","sourceNumber":"346453","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre a síndrome de Mallory-Weiss, assinale a correta.","options":{"A":"É uma síndrome hereditária familiar;","B":"É considerada um fator de risco para o adenocarcinoma esofágico;","C":"Necessita de tratamento cirúrgico na maioria dos casos;","D":"É responsável por cerca de 10% dos casos de hemorragia digestiva alta."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-311888","number":"311888","sourceNumber":"311888","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 65 anos dá entrada na emergência com hematoquezia de grande volume\ncom episódios prévios de melena. Apresenta\nfrequência cardíaca de 120bpm e pressão arterial de\n80x50mmHg. Tem passado de doença ulcerosa péptica e é etilista inveterado de longa data. Em\nrelação a este caso clínico, qual a conduta a ser adotada?","options":{"A":"Realizar como conduta inicial endoscopia digestiva alta para conter o sangramento.","B":"Realizar como conduta inicial a colonoscopia para definição da origem do sangramento.","C":"Realizar como conduta inicial a avaliação da via aérea e a respiração do paciente.","D":"Devido ao baixo risco de mortalidade, o paciente pode ser encaminhado à enfermaria."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-295337","number":"295337","sourceNumber":"295337","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A fasciíte necrotizante é um quadro de extrema gravidade, cujo desfecho depende da\nrapidez ou lentidão no seu reconhecimento. Seguindo o Indicador de Risco Laboratorial para\nFasciíte Necrotizante, um paciente que apresenta proteína C reativa = 130; contagem de leucócitos\n\n= 20.000/mm e glicose sérica = 150 mg/dl tem risco de estar com a doença considerado","options":{"A":"baixo.","B":"intermediário.","C":"alto.","D":"muito alto."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-317143","number":"317143","sourceNumber":"317143","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação a Hemorragia Digestiva Alta são afirmativas incorretas, exceto:","options":{"A":"No paciente com hemorragia digestiva, independente da origem, deve-se usar inibidor da bomba\nde prótons em dose plena endovenosa.","B":"Os inibidores da bomba de prótons são mais eficientes na prevenção da hemorragia digestiva\nque os bloqueadores H2 em paciente\nhospitalizados.","C":"O uso de ácido tranexâmico melhora o prognóstico e promove o controle da hemorragia\ndigestiva alta de origem péptica.","D":"A terlipressina tem menor eficácia no controle de hemorragia por origem péptica em comparação\ncom hemorragia varicosa por hipertensão portal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-317144","number":"317144","sourceNumber":"317144","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 30 anos, teve um acidente de moto com grave trauma\nortopédico. Está internado aos cuidados da\nortopedia há 35 dias e já fez 5 cirurgias e vários\ncurativos sob anestesia. Há 30 minutos apresentou mal-estar seguido por hematêmese franca,\nsudorese fria e rebaixamento nível consciência. O Ortopedista solicitou avaliação do plantão da\nClínica Médica de urgência. Das assertivas abaixo é correto afirmar: I ? A hipótese diagnóstica mais\nprovável é de úlcera gástrica devido ao stress metabólico e ao uso de anti-inflamatórios. II ? O uso\nde inibidores da bomba de prótons aumenta o risco de pneumonia hospitalar. III ? A paciente deve\nser submetida a uma endoscopia terapêutica imediatamente.","options":{"A":"Apenas a assertiva I está correta.","B":"Apenas a assertiva II está correta.","C":"As assertivas I e II estão corretas.","D":"As assertivas I e III estão corretas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-294251","number":"294251","sourceNumber":"294251","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem obeso e diabético, de 54 anos, com quadro de dor na região anal há quatro\ndias, sem melhora e surgimento de abaulamento\nhá um dia. Queixa calafrio. A inspeção da região\nanal demonstra abaulamento perianal á esquerda, com hiperemia. Sem flutuação à palpação, com\naumento de calor local. Toque não realizado devido à dor intensa. Nesse caso, qual é a melhor\nconduta?","options":{"A":"Incisão local ampla e drenagem cirúrgica de urgência.","B":"Punção do abscesso com jelco calibroso.","C":"Antibioticoterapia e exame físico seriado para posterior drenagem quando ocorrer flutuação.","D":"Fistulotomia programada."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-316301","number":"316301","sourceNumber":"316301","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As infecções necrotizantes causadas pelos abscessos anorretais podem levar a sepse\nseguida de morte do paciente. Isso se deve a causas multifatoriais como diabetes, doenças\nvasculares, câncer, atraso no tratamento, além de outros fatores. Sobre esse assunto, assinale a\nalternativa incorreta:","options":{"A":"A infecção necrotizante, que se dissemina pelas fáscias musculares, pode atingir os espaços\nprofundos pré-peritoneal e retroperitonial.","B":"O cirurgião deve ser o mais conservador possível no debridamento da ferida, evitando assim\ngrandes lesões com posterior necessidade de enxerto.","C":"A oxigenioterapia tem uma ótima indicação nos processos infecciosos necrotizantes perirretais.","D":"A terapêutica empírica com antibioticoterapia de amplo espectro deve ser iniciada\nindependentemente dos resultados de cultura e coloração pelo Gram."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-302839","number":"302839","sourceNumber":"302839","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 27 anos, pro cura o ambulatório de proctologia com queixa de secreção\nanorretal. Ao exame, com o paciente em\nposição de litotomia, observamos orifício fistuloso próximo\nà bolsa scrotal, a 2 cm da margem anal. De acordo com a regra de Godsall, o que podemos afir\nmar sobre o trajeto fistuloso?","options":{"A":"A fístula tem um trajeto linear e retílineo em direção ao ânus.","B":"A físula tem um trajeto curvo e normalmente atravessa a linha média, formando uma ferradura.","C":"Essa fístula deve envolver o músculo puborretal.","D":"A fístula tem um trajeto curvo, mas sem ultrapassar a linha média.","E":"O oríficio interno deve se localizar na linha média posterior."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-311901","number":"311901","sourceNumber":"311901","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A classificação das hemorroidas internas considera a extensão do prolapso e pode\ninfluenciar nas opções de tratamento. Como se classificam as hemorroidas internas que\napresentam um prolapso com redução espontânea?","options":{"A":"Terceiro grau.","B":"Primeiro grau.","C":"Quarto grau.","D":"Segundo grau."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-315787","number":"315787","sourceNumber":"315787","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Durante a etapa inicial do tratamento do sangramento agudo gastrointestinal, o que é\nrecomendado para os níveis de hemoglobina?","options":{"A":"Manater abaixo de 5-6g/dL.","B":"Sempre usar hemácias como expansor.","C":"Manter acima de 7-8g/dL.","D":"Sempre usar concentrado de hemácias como constritor."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-315797","number":"315797","sourceNumber":"315797","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Pela classificação endoscópica de hemorragias digestivas ativas, é esperado encontrar\nno tipo IA de Forrest:","options":{"A":"Sangramento em jato.","B":"Vaso visível com sangramento recente.","C":"Úlcera ativa com fundo de hematina.","D":"Úlcera cicatrizada com vaso visível."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-295429","number":"295429","sourceNumber":"295429","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma doença congênita que pode causar obstrução intestinal, hemorragia digestiva,\nabdome agudo inflamatório ou perfurativo na criança é:","options":{"A":"linfoma de Burkitt.","B":"divertículo de Meckel.","C":"cloaca.","D":"onfalocele."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-281807","number":"281807","sourceNumber":"281807","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A causa mais comum para os abscessos anorretais está relacionada","options":{"A":"à doença de Crohn.","B":"à hidradenite supurativa.","C":"à criptite.","D":"ao coito retal."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-258165","number":"258165","sourceNumber":"258165","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Analise o esquema a seguir. As fístulas anorretais, representadas no esquema, são\nclassificadas respectivamente, como:","options":{"A":"interesfincteriana, transesfincteriana, supraesfincteriana e extraesfincteriana.","B":"interesfincteriana, supraesfincteriana, transesfincteriana e extraesfincteriana.","C":"extraesfincteriana, transesfincteriana, supraesfincteriana e interesfincteriana.","D":"extraesfincteriana, supraesfincteriana, interesfincteriana, transesfincteriana."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":["question_bank/media/medcurso/med-cirurgia-med-cir-03/258165.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-281280","number":"281280","sourceNumber":"281280","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A endoscopia digestiva alta realizada em um paciente com hemorragia em que se\nencontra sangramento recente, não mais ativo, com\ncoto vascular visível, é classificada por Forrest\nem:","options":{"A":"IA","B":"IB","C":"IIA","D":"III"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-273174","number":"273174","sourceNumber":"273174","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher, 83 anos, com úlcera péptica gastroduodenal e insuficiência renal crônica,\napresenta na endoscopia úlceras com coágulo\nrecente, pulso > 100 bpm e pressão arterial sistólica\n\n< 100 mmHg. A estratificação do risco de ressangramento e morte, segundo o escore de Rockall,\nserá:","options":{"A":"Risco alto para ressangramento e alto para mortalidade.","B":"Risco alto para ressangramento e médio para mortalidade.","C":"Risco médio para ressangramento e médio para mortalidade.","D":"Risco baixo para ressangramento e alto para mortalidade."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-273177","number":"273177","sourceNumber":"273177","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A(s) causa(s) mais frequente(s) de hemorragia digestiva baixa em crianças é/são:","options":{"A":"Doenças inflamatórias intestinais.","B":"Colite por citomegalovírus.","C":"Ectasias vasculares.","D":"Divertículo de Meckel."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-257791","number":"257791","sourceNumber":"257791","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Menina de um ano e dez meses é levada ao pronto-socorro com história de cólica\nabdominal leve e progressiva e, presença de sangramento vivo nas fezes. É então avaliada pelo\npediatra e, posteriormente pelo cirurgião pediátrico, que fazem hipótese diagnóstica que indica\nprocedimento cirúrgico imediato. Durante o procedimento, o cirurgião faz outro diagnóstico, que é:","options":{"A":"torção de ovário.","B":"divertículo de Meckel.","C":"hérnia encarcerada.","D":"apendicite aguda."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-246525","number":"246525","sourceNumber":"246525","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 45 anos, estilista, evoluiu com 3 episódios de hematêmese volumosa, trazido\npor familiares ao serviço de emergência. Na\nadmissão encontra-se com sudorese fria, palidez\ncutâneo-mucosa, PA = 80x60, FC = 143, FR = 23, perfusão capilar menor que 3 segundos. Qual a\nconduta inicial mais adequada?","options":{"A":"Investigar a etiologia da hemorragia digestiva.","B":"Solicitar exames laboratoriais para dosagem de hemoglobina e hematócrito.","C":"Colocar balão de Sengstaken-Blakemore.","D":"Proceder à reposição volêmica com cristaloide.","E":"Fazer transfusão sanguínea."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-247398","number":"247398","sourceNumber":"247398","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As fístulas anorretais, em geral, recaem em uma das quatro principais categorias\nanatômicas descritas por Parks e colaboradores\n(col), em 1976. A fístula anorretal que conecta o\nplano interesfincteriano com a fossa isquiorretal, perfurando o esfíncter externo, sem formar uma\nalça sobre esse esfíncter é classificada de acordo com Parks e col (1976) como:","options":{"A":"extraesfincteriana.","B":"transesfincteriana.","C":"supraesfincteriana.","D":"interesfincteriana."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-232221","number":"232221","sourceNumber":"232221","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em uma consulta no ambulatório de coloproctologia foi indicado hemorroidectomia para\ntratar um paciente que se queixava há anos de crises de doença hemorroidária. Durante os\nesclarecimentos sobre a cirurgia a ser realizada, o médico explica adequadamente que:","options":{"A":"a técnica de Milligan e Morgan apresenta resultados clínicos superiores aos da técnica de\nFerguson, que leva a ânus úmido no pós-operatório tardio.","B":"a técnica de Whitehead oferece resultados funcionais superiores aos da técnica de Obando, que\npromove muita estenose.","C":"a técnica de ligadura elástica, devido à presença de mamilos hemorroidarios externos grandes e\nsintomáticos, não deve ser adotada.","D":"a anopexia mecânica é satisfatória para tratar os mamilos externos."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-234329","number":"234329","sourceNumber":"234329","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, de 22 anos, após vários episódios repetidos de vômitos,\nnas últimas seis horas, inicialmente com\nconteúdo claro, com sabor ácido, apresentou episódio de\nhematêmese. Neste caso, o diagnóstico mais provável é:","options":{"A":"Síndrome de Budd-Chiari.","B":"Síndrome de Mallory-Weiss.","C":"Úlcera duodenal.","D":"Varizes esofagianas."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-229540","number":"229540","sourceNumber":"229540","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente após quadro de trauma abdominal fechado há 5 dias, apresentando\nhematêmese, dor em flanco direito e icterícia. O PROVÁVEL diagnóstico é:","options":{"A":"lesão de Dieulafoy.","B":"rotura de antro gástrico.","C":"hemobilia.","D":"lesão esôfago distal."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-210569","number":"210569","sourceNumber":"210569","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Considere: uma paciente de 67 anos, admitida no Pronto-Atendimento com episódio de\nhematêmese, estável hemodinamicamente. A respeito do manejo clínico, assinale a alternativa\ncorreta.","options":{"A":"O início do inibidor de bomba de prótons antes da endoscopia é mandatório.","B":"Análogos da somatostatina podem ser utilizados rotineiramente.","C":"O achado endoscópico de uma úlcera de base limpa é indicação de terapia hemostática eletiva.","D":"Presença de vaso visível em leito ulceroso é indicação para terapia hemostática imediata.","E":"No caso de ressangramento após tratamento endoscópico, repetir o exame é facultativo."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-201925","number":"201925","sourceNumber":"201925","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 47 anos foi vítima de acidente automobilístico frontal 4 dias atrás.\nRelata estar apresentando dor no hipocôndrio\ndireito e hematêmese. Ao exame físico, foi detectada\nicterícia. Essa tríade é característica de:","options":{"A":"síndrome de Mallory-Weiss","B":"síndrome de Zollinger-Ellison","C":"lesão de Dieulafoy","D":"hemobilia","E":"gastrinoma"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-216473","number":"216473","sourceNumber":"216473","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 38 anos, arquiteto, DM 2, relata dor anal de evolução de 8 horas, com\nmal-estar e febre baixa. Ao exame, nota-se em região perianal, induração, dor, calor e rubor, sem\nsinais de flutuação. A conduta adequada será:","options":{"A":"Administrar antibiótico e calor local para regressão do processo.","B":"Colocação de calor local e banhos de assento até que ocorra flutuação.","C":"Punção para identificação da loja seguida de drenagem.","D":"Solicitar hemograma, glicemia e USG perianal para reavaliação após 12 horas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-201675","number":"201675","sourceNumber":"201675","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Tendo em vista as fístulas anorretais de etiologia criptoglandular:","options":{"A":"A regra de Goodsall deve ser desconsiderada devido à melhora tecnológica dos exames\ncomplementares.","B":"A fistulectomia é a técnica de escolha, independente do envolvimento esfincteriano.","C":"A apresentação em ferradura oferece melhor prognóstico de tratamento.","D":"O trajeto interesfincteriano é o tipo mais comum de apresentação."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-215461","number":"215461","sourceNumber":"215461","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação aos sangramentos gastrointestinais na\ninfância.","options":{"A":"Hematêmese é vômito em sangue vivo, indicando lesão de sangramento intenso.","B":"Ventilação pulmonar mecânica, CIVD, choque, sepse, trauma e uso de medicamentos fazem\nparte do conjunto de fatores de risco para hemorragias intestinais em pacientes criticamente\nenfermos.","C":"A divisão das hemorragias gastrointestinais em categorias, hemorragia digestiva alta (HDA) e\nhemorragia digestiva baixa (HDB), se dão por sua origem acima ou abaixo do ligamento de Treiz.","D":"Os sangramentos gastrointestinais são eventos comuns em crianças."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-215459","number":"215459","sourceNumber":"215459","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação a exames radiológicos e endoscópicos na presença de hemorragia\ndigestiva, assinale a alternativa CORRETA.","options":{"A":"Os exames radiológicos são os mais indicados para determinar o local exato do sangramento.","B":"As guidelines específicas para a indicação precoce de endoscopia em pacientes pediátricos\napontam que intervenções precoces diminuem a necessidade de transfusões.","C":"Os métodos endoscópicos não permitem determinar o local exato do sangramento.","D":"As cintilografias são úteis no diagnóstico de divertículo de Meckel, o qual pode se manifestar\ncomo causa de hemorragia digestiva baixa"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-205614","number":"205614","sourceNumber":"205614","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"O divertículo de Meckel é a anomalia congênita mais encontrada no intestino delgado.\nEm relação a isso, assinale a alternativa\nINCORRETA:","options":{"A":"Pode existir em diferentes formas, variando de pequeno abaulamento até uma projeção longa\nque se comunica com umbigo por um cordão fibroso persistente.","B":"O tecido heterotópico dentro do divertículo de Meckel mais comum é a mucosa gástrica.","C":"A apresentação clínica mais comum é o sangramento gastrointestinal.","D":"A tomografia computadorizada de abdome com contraste oral é bastante sensível e específica."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-215378","number":"215378","sourceNumber":"215378","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"O divertículo de Meckel é a mais comum anomalia congênita do intestino delgado,\nsendo o resultado da incompleta obliteração\ndo ducto onfalomesentérico. Assinale a alternativa\nINCORRETA.","options":{"A":"A hemorragia é uma complicação frequente em crianças sendo geralmente aguda, intensa,\npodendo haver repercussão hemodinâmica.","B":"O íleo terminal deve sempre ser explorado à procura de divertículo de Meckel, durante o ato\ncirúrgico por apendicite, quando o apêndice é normal.","C":"O divertículo de Meckel localiza-se na borda mesenterial do íleo, a cerca de 20 cm da válvula\nileocecal.","D":"O tratamento do divertículo de Meckel complicado é cirúrgico visando à ressecção do divertículo."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-214108","number":"214108","sourceNumber":"214108","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A causa mais provável para um abscesso perianal é:","options":{"A":"O parto normal.","B":"A fissura anal.","C":"A fissura perianal.","D":"A infecção criptoglandular."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-174122","number":"174122","sourceNumber":"174122","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"O tamponamento com balão é medida terapêutica salvadora na hemorragia digestiva\nalta por varizes de esôfago. Neste contexto, a\ninsuflação correta do balão de\n\nSengstaken-Blakemore é feita com","options":{"A":"água, sendo 300 ml no balão esofágico e 30 mmHg no gástrico.","B":"ar, sendo 30 mmHg no balão esofágico e 300 ml no gástrico.","C":"água, sendo 30 mmHg no balão esofágico e 300 ml no gástrico.","D":"ar, sendo 300 ml no balão esofágico e 30 mmHg no gástrico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-173508","number":"173508","sourceNumber":"173508","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A fístula anorretal associada ao maior risco de incontinência anal após o tratamento\ncirúrgico é a","options":{"A":"interesfincteriana.","B":"transesfincteriana.","C":"submucosa.","D":"supraelevadora."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-186477","number":"186477","sourceNumber":"186477","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente gestante, primigesta, 34 semanas, vem ao pronto-atendimento com queixa de\nsangramento, de pequena monta, durante as evacuações, sem queixa algica associada. Refere\nque vem apresentando certa dificuldade para evacuar após o segundo trimestre da gestação. Ao\nexame físico: toque retal com pequena quantidade de sangue em dedo de luva e presença de\nmamilo hemorroidário, sem prolapso e sem trombose. Qual a melhor conduta?","options":{"A":"Hemorroidectomia de urgência.","B":"Fistulectomia.","C":"Modificações dietéticas, higiene local e uso de fibras suplementares.","D":"Internação, antibioticoterapia e indução de parto prematuro."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-175392","number":"175392","sourceNumber":"175392","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"São fatores de risco para mortalidade na hemorragia gastrintestinal aguda, exceto:","options":{"A":"idade >50 anos","B":"doença renal","C":"pressão arterial sistêmica <100mmHg na apresentação","D":"necessidade de transfusão","E":"hemorragia recorrente"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-178807","number":"178807","sourceNumber":"178807","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinale a alternativa correta quanto à doença hemorroidária interna.","options":{"A":"Dor é a queixa mais comum.","B":"Hemorroidectomia de Milligan e Morgan é a técnica mais utilizada quando a cirurgia aberta é\nindicada.","C":"Mamilos internos de 2º e 3º graus não respondem ao tratamento com ligadura elástica.","D":"Hemorroídas internas grau 2 são aquelas que apresentam prolapso com necessidade de\nredução manual.","E":"Hemorroídas internas grau 3 são aquelas que possuem prolapso com necessidade de redução\ncirúrgica."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-174472","number":"174472","sourceNumber":"174472","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Hemorróida prolapsada, que necessita de redução digital é classificada como:","options":{"A":"Primeiro Grau.","B":"Segundo grau.","C":"Terceiro grau.","D":"Quarto grau."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-160471","number":"160471","sourceNumber":"160471","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente chega ao consultório queixando-se de proctalgia, hematoquezia e\nprolapso hemorroidário com redução apenas digital. Neste caso, qual o grau da doença\nhemorroidária e a conduta indicada?","options":{"A":"Terceiro grau; realizar hemorroidectomia cirúrgica.","B":"Segundo grau; orientar dieta laxativa.","C":"Segundo grau; orientar dieta laxativa e ligadura elástica.","D":"Terceiro grau; realizar hemorroidopexia."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-149196","number":"149196","sourceNumber":"149196","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem de 43 anos, na sala de urgência com dor abdominal intensa e dor torácica\nsubesternal há 12 horas (após ingestão de\ngrande quantidade de álcool em uma festa). Antes do\ninício da dor, teve vários episódios de vômito. História prévia não é digna de nota e não usa\nmedicamentos. Ao exame clínico, encontra-se desconfortável e ansioso, temperatura de 38,8°C,\nfrequência cardíaca de 120/min, pressão arterial de 120/80 mmHg e frequência respiratória de\n32/min. Pulmões limpos bilateralmente, porém com diminuição dos murmúrios à esquerda. Exame\ncardíaco revela taquicardia sem outros comemorativos. Abdome sensível à palpação epigástrica.\nTem leucocitose de 26 mil/mm3, ECG de 12 derivações normais, RX de tórax com derrame pleural\nmoderado à esquerda, pneumotórax e pneumomediastino à esquerda. Em se tratando de uma\nruptura esofágica espontânea (Síndrome de Boerhaave), aponte a alternativa contendo o próximo\npasso para esse caso.","options":{"A":"Manejo das vias aéreas, respiração e circulação (ABC).","B":"Drenagem torácica à esquerda.","C":"Administração de fluidos e antibióticos de amplo espectro.","D":"Todas as alternativas anteriores estão corretas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-149201","number":"149201","sourceNumber":"149201","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente pós-operatório de hemorroidectomia pode ter complicações precoces, com\nEXCEÇÃO de:","options":{"A":"Dor.","B":"Retenção urinária.","C":"Sangramento.","D":"Estenose."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-150261","number":"150261","sourceNumber":"150261","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A apresentação clínica mais comum do divertículo de Meckel no adulto é:","options":{"A":"Obstrução intestinal.","B":"Perfuração intestinal.","C":"Hemorragia digestiva.","D":"Diarreia."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-160493","number":"160493","sourceNumber":"160493","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Chegou na emergência um homem de 35 anos, com epigastralgia importante e relato\nde melena nas últimas 24h, hemodinamicamente\nestável. Submetido à endoscopia digestiva alta, o\nlaudo confirmou tratar-se de uma úlcera péptica com a classificação de Forrest IIb. Logo, ele\napresentava ao exame:","options":{"A":"Vaso visível não sangrante.","B":"Úlcera com pontilhado preto.","C":"Sangramento ativo e não pulsátil.","D":"Coágulo aderente."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-157450","number":"157450","sourceNumber":"157450","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As alternativas abaixo são indicações para cirurgia na hemorragia gastrointestinal, com\nEXCEÇÃO de uma delas. Assinale-a:","options":{"A":"Instabilidade hemodinâmica apesar de ressuscitação rigorosa.","B":"Falha de técnica endoscópica.","C":"Hemorragia no segundo episódio.","D":"Sangramento lento com necessidade de transfusão de mais de 3 concentrados de hemácias por\ndia."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-157276","number":"157276","sourceNumber":"157276","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"São causas mais comuns de Hemorragia Digestiva Alta todas as listadas a seguir,\nEXCETO uma. Qual?","options":{"A":"Úlcera gástrica.","B":"Laceração de Mallory-Weiss.","C":"Úlcera duodenal.","D":"Duodenite erosiva.","E":"Varizes esofágicas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-150703","number":"150703","sourceNumber":"150703","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Para o tratamento cirúrgico do cisto pilonidal sacrococcígeo, a posição indicada é a de:","options":{"A":"Litotomia.","B":"Trendelemburg.","C":"Lloyd-Davies.","D":"Jackknife."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-157298","number":"157298","sourceNumber":"157298","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à diverticulite de Meckel, assinale a alternativa INCORRETA.","options":{"A":"A principal complicação em crianças é o sangramento.","B":"É um resquício embriológico do ducto onfalomesentérico.","C":"A principal complicação em adultos é a obstrução intestinal.","D":"É a anormalidade congênita do intestino delgado mais comum.","E":"É considerado um falso divertículo, uma vez que não contém todas as camadas da parede\nintestinal."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-158480","number":"158480","sourceNumber":"158480","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A hemorragia digestiva é a complicação mais comum da doença ulcerosa péptica e\nrequer reconhecimento precoce e terapêutica\neficaz. Sobre essas entidades nosológicas assinale a\nalternativa correta:","options":{"A":"A realização de endoscopia digestiva alta é imperiosa e conduta inicial no tratamento.","B":"As úlceras localizadas na pequena curvatura gástrica são as que respondem pela maior parte\ndos casos.","C":"As lesões classificadas como Forrest IIa apresentam coágulo aderido e alta taxa de\nressangramento após tratamento endoscópico.","D":"O tratamento cirúrgico pode ser indicado em casos com sangramento contínuo necessitando de\nmais de 3 concentrados de hemácias por dia."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-156468","number":"156468","sourceNumber":"156468","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual, dentre os fatores abaixo, é o mais importante no desenvolvimento da doença\nhemorroidária?","options":{"A":"Hereditariedade.","B":"Constipação intestinal.","C":"Aumento da pressão intra-abdominal.","D":"Diminuição da fixação anatômica do canal anal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-156489","number":"156489","sourceNumber":"156489","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à doença ulcerosa péptica sangrante, assinale a alternativa correta:","options":{"A":"As úlceras são causa de sangramento em cerca de metade dos pacientes com varizes de\nesôfago.","B":"Doentes em estado grave e sem dieta enteral estão sob maior risco.","C":"Por tratar-se de hemorragia alta, os pacientes com úlcera péptica não apresentam\nhematoquezia.","D":"Os inibidores da bomba de prótons não surtem efeito no sangramento agudo, mas reduzem as\ntaxas de ressangramento."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-136848","number":"136848","sourceNumber":"136848","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 48 anos, tabagista, hipertenso, usuário crônico de AINES, é admitido na\nemergência com quadro de melena e hematêmese, com início há quatro horas. Após estabilização\nclínica, paciente foi encaminhado ao serviço de endoscopia. No exame, foi evidenciada uma lesão\nulcerada com sangramento ativo em \"babação\" (gotejamento) em região pré-pilórica. Como se\nclassifica essa lesão com relação à classificação de Forrest e à classificação de Jonhson?","options":{"A":"Ia, III","B":"Ib, I","C":"Ib, III","D":"Ia, II"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-140614","number":"140614","sourceNumber":"140614","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sr. Antônio, 65 anos, chega ao pronto-socorro trazido por familiares, com história de\nevacuação com sangue há 3 dias e perda de\npeso há 3 meses. O mesmo é portador de\ninsuficiência cardíaca e, no momento da avaliação, apresenta pressão sistólica de 110 mmHg.\nPaciente apresenta-se lúcido e com frequência cardíaca normal. Não apresenta sintomas\nrespiratórios. Abdomen indolor à palpação. Comparando as hemorragias baixas em relação às\nhemorragias altas, tem-se o seguinte:","options":{"A":"a primeira é mais grave e mais intermitente que a segunda.","B":"a primeira é menos grave e mais frequente que a segunda.","C":"a primeira é mais grave e mais frequente que a segunda.","D":"a primeira é menos grave e mais intermitente que a segunda."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-127095","number":"127095","sourceNumber":"127095","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem de 20 anos apresenta quadro de melena e hematêmese com 6 horas de\nevolução. Previamente hígido, apresentou vários episódios de vômitos após episódio de\ngastroenterite. Encontra-se estável hemodinamicamente. O achado esperado na endoscopia\ndigestiva alta é:","options":{"A":"Hiperemia e erosões da mucosa do corpo gástrico.","B":"Lesão elevada e vegetante do antro gástrico.","C":"Laceração da transição esofagogástrica.","D":"Lesão ulcerada de 1ª porção duodenal.","E":"Coleção de vênulas dilatadas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-127667","number":"127667","sourceNumber":"127667","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A esfincterotomia química utilizada no tratamento da fissura anal crônica, que promove\nmaior redução das pressões de repouso do canal anal e, consequentemente, maior risco de\nincontinência anal temporária, é aquela realizada com:","options":{"A":"Nitratos.","B":"Bloqueadores de canal de cálcio.","C":"Antagonistas de receptores muscarínicos.","D":"Toxina botulínica."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-129876","number":"129876","sourceNumber":"129876","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 29 anos, do sexo feminino, com história de drenagem de abscesso na\nregião perianal há três meses. Persiste até\nhoje com orifício de drenagem purulenta em quadrante\nposterolateral esquerdo, às 4h (posição de litotomia), cerca de 3 cm da margem anal. O orifício\ninterno deste trajeto fistuloso está mais provavelmente localizado na:","options":{"A":"Linha média posterior.","B":"Cripta anal correspondente às 4h do canal anal.","C":"Glândula de Bartholin ipsilateral.","D":"Primeira válvula de Houston."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-127970","number":"127970","sourceNumber":"127970","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à Hemorragia Digestiva Alta (HDA) ou Baixa (HDB), assinale a alternativa\nincorreta.","options":{"A":"Um ph maior que 6 é necessário para uma boa agregação plaquetária, o que justifica o uso de\nbloqueador de bomba na HDA de origem gástrica.","B":"Em toda suspeita de HDB, uma EDA tem indicação obrigatória antes da colonoscopia, a menos\nque uma retoscopia identifique a causa do\nsangramento.","C":"Se na HDB de um idoso, após a colonoscopia, uma arteriografia for indicada, ela deverá\ncomeçar pela artéria mesentérica inferior.","D":"Em comparação com a HDB, a HDA é mais comum, menos provável de cessar\nespontaneamente e com maior morbimortalidade."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-89972","number":"89972","sourceNumber":"89972","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Na suspeita de síndrome de Mallory-Weiss, devemos solicitar qual exame\ncomplementar para confirmação diagnóstica?","options":{"A":"Cintilografia.","B":"Endoscopia digestiva alta.","C":"Endoscopia digestiva baixa.","D":"Tomografia computadorizada de abdome.","E":"Ultrassonografia de abdome superior."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-84644","number":"84644","sourceNumber":"84644","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre o Hamartoma das Glândulas de Brünner (HGB) é incorreto afirmar:","options":{"A":"Trata-se de uma lesão benigna proliferativa das glândulas de Brünner (Brunneroma).","B":"São comuns e representam cerca de 70% dos tumores benignos duodenais.","C":"Os pacientes geralmente são assintomáticos.","D":"Sangramentos e/ou obstruções do trato digestivo são raras no HGB.","E":"A enteroscopia deve ser lembrada como exame eficaz no diagnóstico e tratamento de lesões\ninacessíveis por EDA e colonoscopia."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-83804","number":"83804","sourceNumber":"83804","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual é o exame mais indicado para avaliação emergencial de hemorragia digestiva\nalta?","options":{"A":"Cintilografia seletiva.","B":"Endoscopia digestiva alta.","C":"Seriografia esofagogastroduodenal.","D":"Tomografia de abdome total.","E":"Ultrassom de abdome total."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-83667","number":"83667","sourceNumber":"83667","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Na hipertensão portal com varizes e sangramento após estabilização hemodinâmica do\npaciente, qual a conduta de menor morbimortalidade e boa resolutividade?","options":{"A":"Cirurgia de Warren.","B":"Derivação esplenorrenal proximal.","C":"Derivação porto-cava.","D":"Desconexão ázifo-portal + esplenectomia.","E":"Ligadura elástica por endoscopia."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-83831","number":"83831","sourceNumber":"83831","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Senhora de 62 anos chega ao pronto-socorro com volumosa hemorragia digestiva\nbaixa. A principal causa, no trato\ndigestório, deste sangramento é?","options":{"A":"Angiodisplasia.","B":"Colite ulcerativa.","C":"Doença diverticular.","D":"Doença hemorroidária.","E":"Síndrome de Mallory-Weiss."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-85351","number":"85351","sourceNumber":"85351","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual é o primeiro passo na investigação etiológica da hemorragia digestiva baixa?","options":{"A":"Colonoscopia.","B":"Toque retal.","C":"Clister opaco.","D":"Raio X de abdome em pé e deitado."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-61750","number":"61750","sourceNumber":"61750","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"O tratamento ideal para um paciente com hemobilia é:","options":{"A":"Punção com drenagem guiada por US.","B":"Apenas punção com esvaziamento.","C":"Arteriografia com embolização.","D":"Papilotomia com descompressão da via biliar.","E":"Segmentectomia hepática."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-62777","number":"62777","sourceNumber":"62777","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A síndrome de Heide caracteriza-se pela presença de:","options":{"A":"estenose mitral, fibrilação atrial e trombo no átrio esquerdo.","B":"estenose tricúspide, hepatomegalia e ascite.","C":"estenose aórtica e hemorragia digestiva.","D":"estenose pulmonar e fístulas arteriovenosas pulmonares."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-61726","number":"61726","sourceNumber":"61726","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente apresenta-se na emergência com melena. Nega hematêmese e\nhematoquezia. A origem mais provável desse sangramento é:","options":{"A":"Duodeno.","B":"Jejuno.","C":"Íleo.","D":"Cólon ascendente.","E":"Cólon descendente."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-61776","number":"61776","sourceNumber":"61776","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, 35 anos, procura atendimento de emergência, relatando ser\nportador de úlcera péptica, sem tratamento\nadequado e referindo que está eliminando fezes\nenegrecidas, aderidas ao vaso sanitário, com odor muito fétido há cerca de 2 dias. O paciente é\navaliado pelo médico plantonista e feita então a lavagem gástrica, não havendo retorno de sangue,\napenas de restos alimentares. Marque a opção CORRETA.","options":{"A":"A sondagem nasogástrica não tem qualquer utilidade na avaliação de uma possível Hemorragia\nDigestiva Alta (HDA).","B":"Não está excluída Hemorragia Digestiva Alta (HDA), podendo tratar-se de sangramento\nduodenal com manutenção do piloro fechado.","C":"O procedimento exclui hemorragia digestiva alta, podendo o paciente receber alta sem\nnecessidade de acompanhamento específico.","D":"Está excluída Hemorragia Digestiva Alta (HDA).","E":"A presença de melena com lavagem gástrica negativa para sangue indica que o sangramento é\nde estômago."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-35827","number":"35827","sourceNumber":"35827","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Na hemorragia digestiva alta, o controle clínico inicial a melhor conduta é:","options":{"A":"Acesso venoso central, hemotransfusão, UTI.","B":"Acesso venoso central, hidratação, drogas vasoativas.","C":"Acesso venoso periférico, jejum, SF 0,9%, Inibidor de bomba H+.","D":"Acesso venoso periférico, conc. Hemácias, inibidor de bomba.","E":"Nenhuma das anteriores."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-35844","number":"35844","sourceNumber":"35844","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação ao tratamento da doença hemorroidária pode-se afirmar que:","options":{"A":"As hemorroidas de primeiro grau respondem bem ao uso de fibras alimentares e orientações\nhigienodietéticas.","B":"As hemorroidas de quarto grau são bem tratadas com crioterapia ou grampeamento com PPH.","C":"A técnica de Whitehead é a mais aceita pela comunidade científica devido aos bons resultados.","D":"A técnica aberta foi descrita por Ferguson com o intuito de reduzir a dor excessiva provocada\npelas outras técnicas conhecidas até então.","E":"A trombose hemorroidária externa deve ser alvo de indicação cirúrgica na época do diagnóstico."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-33997","number":"33997","sourceNumber":"33997","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Nos casos de hemorragia digestiva por úlcera péptica, o risco de mortalidade é\naumentado em:","options":{"A":"Pacientes com comorbidade.","B":"Pacientes com infecção pelo Helicobacter pylori.","C":"Pacientes tabagistas.","D":"Pacientes usuários de anti-inflamatórios não hormonais."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-35624","number":"35624","sourceNumber":"35624","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 48 anos é levado ao pronto-socorro pela esposa, que diz que ele\ncomeçou a vomitar sangue há cerca de 4\nhoras. Teve vários episódios de vômitos com sangue vivo\ne coágulos. Está bastante descorado e um pouco torporoso. Pulso: 130 batimentos por minuto,\nrítmico, mas fraco; pressão arterial: 100 x 80 mmHg; frequência respiratória: 32 ventilações por\nminuto. Além de acesso venoso e reposição de volume com solução cristaloide, o tratamento deste\npaciente deve incluir:","options":{"A":"Lavagem gástrica, de preferência com soro fisiológico frio, para diminuir o sangramento e\npermitir que a endoscopia digestiva alta seja efetiva.","B":"Transfusão de sangue tipo específico ou o Rh negativo, enquanto se aguarda a tipagem\nsanguínea com prova cruzada.","C":"Endoscopia digestiva alta, quando estiver estável hemodinamicamente.","D":"Intubação traqueal e ventilação mecânica, visto que está torporoso e taquipneico.","E":"Endoscopia digestiva alta de urgência, ao mesmo tempo em que é feita a reanimação volêmica."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-26981","number":"26981","sourceNumber":"26981","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual a causa mais comum de hemorragia digestiva baixa de grande volume em idosos?","options":{"A":"retocolite ulcerativa","B":"doença diverticular de cólon","C":"hemorroidas","D":"câncer de cólon","E":"câncer anal"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-11046","number":"11046","sourceNumber":"11046","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à doença hemorroidária, pode-se afirmar que:","options":{"A":"Trombose hemorroidária é considerada indicação exclusiva de cirurgia","B":"O sangramento deve receber atenção pelo risco de sepse","C":"A febre é o principal sinal de trombose","D":"A técnica de Ferguson está abolida","E":"A doença hemorroidária interna geralmente não acarreta dor"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-10650","number":"10650","sourceNumber":"10650","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A Síndrome de Mallory-Weis geralmente é associada a:","options":{"A":"Carcinoma.","B":"Monilíase.","C":"Doença ulcerosa péptica.","D":"Hérnia hiatal.","E":"Alcoolismo."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-8942","number":"8942","sourceNumber":"8942","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A anemia por perda maciça de sangue ocorre quando em 24 horas perde-se\naproximadamente uma volemia; em 3 horas, 50% da volemia ou 150ml de sangue por minuto.\nNesta situação, o planejamento terapêutico deve levar em consideração que:","options":{"A":"as medidas do hematócrito e da hemoglobina refletem seguramente a real anemia do paciente","B":"a prioridade é restaurar a volemia do paciente, para manter a perfusão","C":"o estudo da hemostasia não tem valor neste momento","D":"por se tratar de urgência extrema, não se conhecendo o tipo sanguíneo do paciente, pode-se\nutilizar sangue de doador de qualquer grupo sanguíneo"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-11108","number":"11108","sourceNumber":"11108","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem de 50 anos é internado com quadro de hemorragia digestiva baixa de\ngrande volume. A causa mais provável é:","options":{"A":"Diverticulite","B":"Angiodisplasia","C":"Hemorróidites","D":"Diarreia infecciosa","E":"Colite"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-8970","number":"8970","sourceNumber":"8970","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"O abscesso anorretal é desencadeado por:","options":{"A":"infecção em trombos hemorroidários","B":"fissuras anais infectadas","C":"doença de Crohn","D":"infecção com origem na criptas anais"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-263718","number":"263718","sourceNumber":"263718","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com história de vômitos seguidos de hematêmese. Realizada endoscopia\ndigestiva alta, que mostrou lacerações na mucosa e submucosa próximas à junção\nesofagogástrica. Essas lesões são conhecidas como lacerações de:","options":{"A":"Mannkopf.","B":"Cullen.","C":"Carnett.","D":"Cruveilhier.","E":"Mallory-Weiss."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-62638","number":"62638","sourceNumber":"62638","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 45 anos chega ao pronto-socorro com hematêmese e melena com 4 horas\nde duração. Apresenta diagnóstico de cirrose\npor vírus C com uso regular de espironolactona e\nfurosemida. Na admissão, PA 90 x 60 mmHg, FC 88 bpm, FR 22 ipm. Em relação ao caso, é\ncorreto afirmar:","options":{"A":"O tratamento com bloqueador de bomba de prótons reduz a chance de ressangramento de\nvarizes esofágicas.","B":"O uso de propranolol auxilia na parada do sangramento agudo.","C":"Octreotide não é tão eficaz no controle do sangramento quanto o balão de\nSengstaken-Blakemore","D":"A hemostasia do balão de Sengstaken-Blakemore não apresenta risco de ressangramento.","E":"Em pacientes cirróticos com sangramento por varizes, a incidência de peritonite bacteriana\nespontânea aumenta, indicando profilaxia antibiótica."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-35721","number":"35721","sourceNumber":"35721","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A causa mais frequente de sangramento no território do tubo digestório acima do\nângulo de Treitz é:","options":{"A":"Varizes por hipertensão portal.","B":"Erosões gástricas.","C":"Síndrome de Mallory-Weiss.","D":"Úlcera duodenal.","E":"Malformações arteriovenosas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-35727","number":"35727","sourceNumber":"35727","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A hemorragia digestiva por hipertensão portal pode ocorrer em todo tubo digestório,\ndesde o esôfago até o reto. Onde é mais\nfrequente?","options":{"A":"Esôfago distal.","B":"Plexo hemorroidário.","C":"Sigmoide.","D":"Intestino delgado.","E":"Parede posterior do duodeno."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-35785","number":"35785","sourceNumber":"35785","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Lactente de 14 meses é trazida ao posto de saúde porque sua mãe observou, nos\núltimos dois dias, a presença de sangue em\npequena quantidade na fralda da criança, sobre as\nfezes emitidas. Não há relato de outras alterações clínicas. A hipótese diagnóstica mais provável\né:","options":{"A":"Divertículo de Meckel.","B":"Parasitose intestinal.","C":"Retocolite ulcerativa.","D":"Doença de Crohn.","E":"Fissura anal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-28194","number":"28194","sourceNumber":"28194","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual o exame mais sensível para detectar hemorragia digestiva?","options":{"A":"Endoscopia digestiva","B":"Cintilografia com Enxofre coloidal - 99 mTc","C":"Arteriografia","D":"Seriografia","E":"Pesquisa de sangue nas fezes"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-342396","number":"342396","sourceNumber":"342396","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente idoso internado para tratamento de broncopneumonia evolui com\nhemorragia gastrointestinal alta. A causa mais comum de hemorragia gastrointestinal alta não\nvaricosa é:","options":{"A":"laceração de Mallory-Weiss","B":"gastrite","C":"malformação arteriovenosa","D":"tumor","E":"úlcera"},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-308633","number":"308633","sourceNumber":"308633","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinale a opção que reúne duas das principais causas de hemorragia digestiva baixa\nem indivíduos com mais de 60anos.","options":{"A":"Doença diverticular dos cólons e angiodisplasia.","B":"Diverticulo de Meckel e pólipo.","C":"Diverticulo de Meckel e doença inflamatória intestinal.","D":"Doença diverticular dos cólons e pólipos.","E":"Doença inflamatória intestinal e neoplasias."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-311505","number":"311505","sourceNumber":"311505","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual a conduta mais apropriada para um paciente com divertículo duodenal\nassintomático de 3 cm?","options":{"A":"Ablação endoscópica da mucosa diverticular.","B":"Diverticulotomia.","C":"Apenas observação.","D":"Duodenotomia segmentar.","E":"By-pass gástrico."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-175008","number":"175008","sourceNumber":"175008","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, 65 anos, etilista, admitido no pronto atendimento com história de\nhematêmese há algumas horas. Antecedentes Mórbidos Pessoais: vômitos com sangue anterior.\nAo exame: pa 90x50 pulso:110. Emagrecido, palidez cutâneo-mucosa +++/4. Sudorese fria.\n\nAranhas vasculares no tórax e abdômen. Ginecomastia. Piparote ++. Nesse caso, qual a conduta\ninicial mais adequada?","options":{"A":"Endoscopia Digestiva de urgência para diagnóstico e ligadura elástica das varizes para\ntratamento do sangramento agudo.","B":"Balão de Sengstaken-Blakemore como primeira alternativa para o tratamento.","C":"Tratamento clínico com Inibidor da Bomba de Próton em altas doses, betabloqueadores e\nanálogo da Somatostatina como a Terlipressina.","D":"TIPS, Shunts cirúrgicos ou Transplante hepático.","E":"Iniciar reposição rápida de Solução salina isotônica por acesso venoso calibroso. Podem- se\nutilizar expansores de plasma para estabilidade hemodinâmica."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-175012","number":"175012","sourceNumber":"175012","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à hemorragia digestiva baixa, é CORRETO afirmar que:","options":{"A":"Devido à baixa resolução espontânea das hemorragias digestivas baixas, a abordagem inicial\ndeve ser agressiva e o tratamento cirúrgico indicado de forma rotineira.","B":"Em casos de dificuldade diagnóstica por meio da colonoscopia, a angiografia possui uma\nsensibilidade maior que a cintilografia.","C":"Doença diverticular colônica é a principal causa de sangramento.","D":"O débito acima de 0,1 ml/min é suficiente para o diagnóstico angiográfico e posterior\nembolização.","E":"A realização de colonoscopia de urgência na vigência de sangramento não é possível, pois o\npaciente não está com o cólon preparado."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-160379","number":"160379","sourceNumber":"160379","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As angiodisplasias e colite isquêmica, ocorrem, mais frequentemente no cólon:","options":{"A":"Ascendente e ângulo esplênico.","B":"Transverso e descendente.","C":"Transverso e sigmoide.","D":"Descendente e sigmoide.","E":"Ascendente e sigmoide."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-160411","number":"160411","sourceNumber":"160411","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente 12 anos, masculino, dá entrada no setor de emergência com quadro de dor\nabdominal compatível com apendicite aguda. Levado ao centro cirúrgico, para laparotomia, o\ninventário revelou apêndice normal, e a diverticulite de Merckel, sem sinais de perfuração. A melhor\nconduta é:","options":{"A":"Ileotiflectomia.","B":"Antibioticoterapia com ciprofloxacina e metronidazol apenas.","C":"Apendiectomia profilática com antibioticoterapia.","D":"Ressecção segmentar do íleo, incluindo a lesão.","E":"Marsupialização do divertículo."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-160417","number":"160417","sourceNumber":"160417","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A lesão de Dieulafoy é geralmente bem conduzida através de:","options":{"A":"Drogas vasoativas (vasopressina).","B":"Tratamento cirúrgico.","C":"Endoscopia digestiva com terapia esclerosante.","D":"Arteriografia seletiva com embolização.","E":"Reposição volêmica e observação clínica."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-154451","number":"154451","sourceNumber":"154451","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 46 anos, faz uso de anti-inflamatório não hormonal há seis meses devido a\nlesão no menisco do joelho direito. Há um\nmês, começou a apresentar dor epigástrica tipo fome nos\nintervalos das refeições, que melhorava com uso de pastilhas antiácidas ou ingestão de leite.\n\nProcurou o PS por queixa de tontura. Refere episódios de fezes escurecidas malcheirosas nos\núltimos 3 dias. Assinale a alternativa CORRETA sobre o procedimento adequado nesse caso:","options":{"A":"A hidratação com solução salina pode aumentar o sangramento e deverá ser evitada.","B":"O diagnóstico mais provável é neoplasia maligna colo-retal.","C":"Deve-se realizar teste de sangue oculto nas fezes para confirmar quadro de melena.","D":"Podem ser utilizados inibidores da bomba de prótons nesta fase da doença.","E":"Antibióticos para Helicobacter pylori devem ser prontamente instituídos."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-140028","number":"140028","sourceNumber":"140028","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"No consultório: paciente de 55 anos, obeso, abdome globoso, refere vários vômitos há\ndois dias e alguns deles com sangue vivo e outros com coágulos de moderada quantidade, sem\ndesmaio ou taquicardia, que ele atribui a uma história anterior de gastrite não tratada. Defecou\nfezes escuras em moderada quantidade. Frequente ingesta de álcool. Assinale a conduta mais\nacertada neste paciente:","options":{"A":"Internar + colonoscopia.","B":"Internar + tomografia de abdome total.","C":"Internar + US de abdome total.","D":"Internar + endoscopia digestiva alta.","E":"Internar + pesquisa de sangue oculto."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-139962","number":"139962","sourceNumber":"139962","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher de 45 anos, da entrada no pronto socorro com relato de vômito com sangue vivo\ne coágulos, sudorese, taquicardia e hipotensão, qual seria o momento certo da execução de\nendoscopia digestiva alta?","options":{"A":"12 a 24 horas após a internação.","B":"Aguardar uma resposta a reanimação volêmica e indicar a endoscopia.","C":"Quando completar 8 horas de jejum.","D":"Imediatamente ou até 6 horas após a internação.","E":"Confirmar sangramento com a passagem de sonda nasogástrica para depois indicar a\nendoscopia."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-139975","number":"139975","sourceNumber":"139975","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Na identificação de varizes esofagogástricas com alto risco de sangramento por\nendoscopia digestiva alta com diagnostico de hipertensão portal por cirrose hepática, assinale a\nmedida preventiva mais correta.","options":{"A":"Esplenectomia.","B":"Betabloqueadores + Endoscopia digestiva alta para ligadura das varizes.","C":"Endoscopia digestiva alta com escleroterapia.","D":"Betabloqueadores.","E":"Desconexão ázigo portal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-132754","number":"132754","sourceNumber":"132754","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 46 anos, portadora de constipação crônica, queixa-se de dor intensa ao\ndefecar, com sangramento esporádico no papel ao se limpar. Refere ainda ardor anal que chega a\nse estender por mais de duas horas, após a defecação. Isto vem ocorrendo há mais de um mês.\n\nAssinale a alternativa que contenha a hipótese diagnóstica MAIS provável:","options":{"A":"Condiloma anal.","B":"Fissura anal.","C":"Abscesso perianal.","D":"Prolapso retal.","E":"Hemorroidas."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-108014","number":"108014","sourceNumber":"108014","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Quais as lesões mais frequentemente encontradas como causas de sangramento\ndigestivo baixo em pacientes acima de 60 anos?","options":{"A":"Neoplasias.","B":"Colites infecciosas.","C":"Moléstia diverticular dos cólons.","D":"Angiodisplasias.","E":"C e D estão corretas."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-65575","number":"65575","sourceNumber":"65575","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A fístula anorretal mais comum é:","options":{"A":"Transesfincteriana;","B":"Interesfincteriana;","C":"Em ferradura;","D":"Extraesfincterianas;","E":"Nenhuma das anteriores."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-52532","number":"52532","sourceNumber":"52532","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, 58 anos, etilista, admitido com relato de hematêmese há algumas\nhoras. Há história prévia de vômitos com sangue. Ao exame, revela-se emagrecido, com palidez\ncutâneo-mucosa (+++/4+), taquicárdico, sudorese fria. Apresenta ainda aranhas vasculares no\ntórax e abdômen e ascite. Quanto o caso acima, assinale a correta:","options":{"A":"A administração de terlipressina nessa situação não aumenta a sobrevida.","B":"A hematêmese é, sem dúvida, de origem varicosa, assim a passagem do Balão de Sengstaken-\nBlakemore é a primeira alternativa para o tratamento.","C":"O tratamento endoscópico deve ser imediato, com escleroterapia das varizes, já que esse\nprocedimento tem menos complicações que a ligadura elástica.","D":"O manejo deve iniciar com reposição rápida de Solução salina isotônica por acesso venoso\ncalibroso, além de incluir medidas de prevenção e tratamento de encefalopatia, vitamina K\nparenteral e antibioticoterapia endovenosa.","E":"O tratamento de derivação portal (TIPS ou Shunts cirúrgicos) está indicado após o primeiro\nepisódio\n\nde sangramento."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-52534","number":"52534","sourceNumber":"52534","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente, 60 anos, com queixa de boca seca, sensação de desconforto abdominal\npós-prandial, associado a plenitude precoce, eructações e náuseas. Relata ainda episódios de\nvômitos pós-prandiais de comida não digerida. Paciente tem passado de vagotomia troncular e\npiloroplastia por úlcera péptica há vários anos. Paciente portador de Diabetes mellitus tipo II, em\ntratamento irregular há cinco anos. O diagnóstico mais adequado é:","options":{"A":"Recidiva da úlcera péptica.","B":"Gastrite alcalina.","C":"Neoplasia gástrica.","D":"Gastroparesia.","E":"Colelitíase."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-52455","number":"52455","sourceNumber":"52455","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A doença hemorroidária é uma das afecções anorretais mais comuns no mundo, com\ntratamento cirúrgico necessário em cerca de 20% dos pacientes sintomáticos. Quanto à doença\nhemorroidária e seu tratamento, assinale a alternativa ERRADA:","options":{"A":"O tratamento cirúrgico tem sido indicado a pacientes portadores de hemorroidas internas grau III\ne IV.","B":"As complicações agudas da hemorroidectomia mais comuns retenção urinária e estenose anal.","C":"O princípio fundamental de qualquer técnica de hemorroidectomia convencional é a manutenção\nde pontes de pele e mucosa entre as incisões.","D":"A técnica de Milligan- Morgan, também chamada de hemorroidectomia aberta, é a mais\ncomumente realizada por ser rápida, fácil e com excelentes resultados.","E":"A técnica de Whitehead é raramente aplicada atualmente pela incidência de complicações, em\ntorno de 10%, como o ectóprio."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-247649","number":"247649","sourceNumber":"247649","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 63 anos, do sexo masculino, procura o pronto atendimento de um\nhospital com queixa de sangramento vermelho\nvivo via anal. Refere que há alguns meses notara\npresença de sangue junto às evacuações esporadicamente e acreditou que era hemorroida, porém\nhouve aumento da frequência até que hoje se desesperou porque passou a apresentar\nsangramento em grande quantidade, com saída de coágulos, e se sentiu mais fraco, tendo\ninclusive caído ao se levantar para ir ao banheiro. Pediu aos vizinhos que o ajudassem porque\nmora sozinho. De comorbidades, tem diagnóstico de hipertensão arterial sistêmica em uso de\nlosartana. Nega outras doenças, uso de outras medicações e cirurgias prévias. Ao exame físico,\nestá em regular estado geral, sudoreico, hipocorado, com frequência cardíaca de 122 bpm, PA: 100\nx 60 mmHg, afebril. É digna de nota ainda a presença de dor à palpação de fossa ilíaca esquerda e\nhipogástrio, sem massas palpáveis ou sinais de irritação peritoneal. À inspeção anal, há presença\nde sangue e dois botões hemorroidários exteriorizados, não redutíveis, sem sinais de trombose e,\nao toque, o esfíncter anal é hipotônico, a mucosa retal é lisa e há presença de sangue em luva.\n\nConsiderando exclusivamente as informações apresentadas, assinale a afirmativa CORRETA.","options":{"A":"A provável causa do sangramento é câncer colorretal e as medidas terapêuticas iniciais devem\nincluir expansão volêmica com cristaloides e hemoderivados com monitorização intensiva e\nprogramação de endoscopia digestiva alta e colonoscopia nas próximas 24 horas a depender da\nestabilização hemodinâmica e possibilidade de preparo do cólon.","B":"A provável causa do sangramento é câncer colorretal e as medidas terapêuticas iniciais devem\nincluir expansão volêmica com cristaloides e hemoderivados seguida de colonoscopia imediata\npara controle do sangramento.","C":"A provável causa do sangramento é doença diverticular do cólon e as medidas terapêuticas\niniciais devem incluir expansão volêmica com\ncristaloides e hemoderivados seguida de\ncolonoscopia imediata para controle do sangramento.","D":"A provável causa do sangramento é doença diverticular do cólon e as medidas terapêuticas\niniciais devem incluir expansão volêmica com\ncristaloides e hemoderivados com monitorização\n\nintensiva e programação de endoscopia digestiva alta e colonoscopia nas próximas 24 horas a\ndepender da estabilização hemodinâmica e possibilidade de preparo do cólon."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-247654","number":"247654","sourceNumber":"247654","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Durante um plantão em uma unidade de pronto atendimento de um hospital particular, o\nmédico atende um paciente de 56 anos, sexo masculino, trazido por familiares com história de\nhematêmese iniciada há aproximadamente 1 hora, sem melhora espontânea. A filha informa que\nele já apresentou episódios semelhantes, porém com melhora espontânea e não procurou\natendimento médico anteriormente. Família tem dificuldade de cuidados, porque ele é etilista diário\ncom consumo de grande quantidade de pinga. O paciente está sonolento, pouco responsivo, e\napresenta, durante a avaliação, vômito com coloração vermelho escuro com coágulos. Ao exame\nfísico, paciente emagrecido, pouco responsivo, desidratado, sudoreico, mucosas hipocoradas, FC\n125 bpm, PA 80 x 50 mmHg, 10 pontos na escala de coma de Glasgow, abdome escavado com\npresença de circulação colateral venosa. Com base nesses dados, qual a conduta mais adequada?","options":{"A":"Deve-se iniciar ressuscitação volêmica imediata com concentrado de hemácias e plasma fresco\ncongelado, administração de inibidor de bomba de prótons, terlipressina, antibiótico, procinéticos e\nprogramação de realização de endoscopia digestiva alta nas próximas 24 horas.","B":"Deve-se iniciar ressuscitação volêmica imediata com concentrado de hemácias, administração\nde inibidor de bomba de prótons, passagem de\nsonda nasogástrica para drenagem do conteúdo\ngástrico e regulação imediata para realização de endoscopia digestiva alta.","C":"Deve-se iniciar ressuscitação volêmica imediata com cristaloides, administração de inibidor de\nbomba de prótons, propanolol e\nantifibrinolíticos, passagem de sonda nasogástrica para drenagem\ndo conteúdo gástrico e solicitação imediata de endoscopia digestiva alta.","D":"Deve-se iniciar ressuscitação volêmica imediata com cristaloides, administração de concentrado\nde hemácias, inibidor de bomba de prótons,\nterlipressina, antibiótico, procinéticos e programação\nde endoscopia digestiva alta nas próximas 24 horas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-362876","number":"362876","sourceNumber":"362876","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre a classificação das hemorroidas internas é correto afirmar que:","options":{"A":"as hemorroidas grau IV prolapsam mas não são redutíveis.","B":"as hemorroidas grau II não prolapsam;","C":"as hemorroidas grau I prolapsam espontaneamente e requerem dedução manual;","D":"a hemorroida grau III prolapsam com esforço ou defecação e reduzem espontaneamente."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-362825","number":"362825","sourceNumber":"362825","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 63 anos, com diagnóstico prévio de cirrose hepática secundária ao vírus da\nhepatite B, com endoscopia prévia que evidenciava varizes esofageanas, deu entrada no pronto\natendimento com quadro de hematêmese. Ao exame encontra-se em regular estado geral, ictérico\n\n+/4+. hipocorado +/4+, afebril, taquicardico (FC 110 bpm) e com PA de 100 x 60 mmHg. Ausculta\ncardíaca e respiratórias normais. Abdome\nascítico. Além das medidas de estabilização clínica,\nquais fármacos são melhor recomendados enquanto aguarda a realização de endoscopia digestiva\nalta?","options":{"A":"Octreotide e propranolol","B":"Vasopressina e albumina","C":"Noradrenalina e lactulose","D":"Terlipressina e ceftriaxone"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-327322","number":"327322","sourceNumber":"327322","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As hemorroidas são estruturas vasculares normais no canal anal. Aproximadamente 5%\nda população geral é afetada por sintomas\nrelacionados à doença hemorroidária. Em relação à\nanatomia, características clínicas e fisiopatologia das hemorroidas, é correto afirmar:","options":{"A":"A artéria retal inferior é ramo direto da artéria ilíaca interna e principal responsável pelo\nsuprimento arterial para as hemorroidas internas.","B":"A doença hemorroidária é caracterizada por dilatação anormal das veias do plexo hemorroidário\ninterno, distensão das anastomoses arteriovenosas,\nprolapso dos coxins anais e destruição do\ntecido conectivo de ancoragem.","C":"O principal referencial anatômico para classificação das hemorroidas é a borda anal. As\nhemorroidas internas estão acima e as externas abaixo da borda anal.","D":"A hemorroida de terceiro grau permanece sempre exteriorizada e irredutível, com ou sem\nsangramento, podendo evoluir para isquemia, trombose ou gangrena."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-330869","number":"330869","sourceNumber":"330869","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, 45 anos, tabagista e etilista, dá entrada em sala de emergência\ndevido o quadro de hematêmese. Foi realizado\nmanejo inicial, e solicitada endoscopia digestiva\nalta, a qual evidenciou úlcera em fundo gástrico com vaso visível sem sangramento ativo. De\nacordo com os dados da endoscopia, qual a classificação de Forrest?","options":{"A":"IIA","B":"IIB","C":"IIC","D":"IA"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-313331","number":"313331","sourceNumber":"313331","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação as hemorroidas internas podemos afirmar:","options":{"A":"As de primeiro grau podem ser tratadas apenas com modificações dietéticas que incluem um\naumento de consumo de fibras, farelo, psyllium e água;","B":"As de segundo grau são definidas como aquelas que necessitam de redução digital;","C":"A ligadura com elástico está especialmente indicada nos pacientes imunodeficientes;","D":"As de quarto grau são satisfatoriamente tratadas com ligadura com elástico com baixa taxa de\nrecorrência."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-316001","number":"316001","sourceNumber":"316001","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 36 anos queixa-se de dor no ânus há 3 anos e, por vezes, refere notar\na presença de secreção esbranquiçada e com odor\nfétido em sua roupa íntima. O diagnóstico mais\nprovável e a melhor conduta são, respectivamente:","options":{"A":"Neoplasia de canal anal; tratamento cirúrgico","B":"Fístula perianal por infecção criptoglandular; tratamento cirúrgico","C":"Fissura anal crônica; tratamento cirúrgico","D":"Hidradenite supurativa; tratamento clínico","E":"Nenhuma das alternativas anteriores"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-258900","number":"258900","sourceNumber":"258900","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 35 anos, queixa-se de dor intensa à evacuação associada a discreto\nsangramento retal. Ao exame físico, observa-se\nfissura anal de cerca de 5 mm com fundo fibrinoso,\nbrancacento, hipertrofia de papila e plicoma anal. Após a confirmação de diagnóstico de hipertonia\nesfincteriana, o tratamento cirúrgico indicado é:","options":{"A":"Esfincterotomia lateral interna.","B":"Esfincteroplastia medial externa.","C":"Fistulectomia com seton.","D":"Fistulotomia simples."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-274102","number":"274102","sourceNumber":"274102","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"V.H.M., 48 anos, dá entrada em unidade hospitalar com dor abdominal, náuseas,\nvômitos e hiporexia há 1 dia. Ao exame\nfísico, apresenta dor à palpação abdominal em quadrante\ninferior direito com sinal de Bloomberg positivo. O paciente é encaminhado ao centro cirúrgico com\na hipótese diagnóstica de abdome agudo inflamatório. Durante a cirurgia você observa apêndice\nvermiforme sem alterações e divertículo em delgado perfurado localizado a 50 cm antes da válvula\nileocecal. A que corresponde tal achado e qual a conduta cirúrgica?","options":{"A":"Divertículo falso; realizar antibioticoterapia.","B":"Divertículo verdadeiro; realizar sua ressecção.","C":"Divertículo verdadeiro; realizar a sua rafia.","D":"Divertículo falso; realizar hemicolectomia direita."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-267313","number":"267313","sourceNumber":"267313","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 26 anos, gestante de 34 semanas, em consulta no ambulatório de cirurgia\ngeral, refere episódios de hematoquezia há\naproximadamente 2 meses e há 3 semanas percebeu\n\"caroço perto do ânus quando vai evacuar, mas que depois desaparece\". Diante do quadro\ndescrito, qual o diagnóstico?","options":{"A":"Hemorroida interna de primeiro grau","B":"Hemorroida externa trombosada","C":"Hemorroida interna de segundo grau","D":"Abscesso perianal"},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-214059","number":"214059","sourceNumber":"214059","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação aos abscessos cutâneos assinale a alternativa verdadeira:","options":{"A":"Abscessos cutâneos devem ser sempre tratados com antibioticoterapia e drenagem.","B":"Quando localizados em região perianal devem ser imediatamente drenados.","C":"O agente etiológico mais envolvido é o Streptococcus beta-hemolítico do grupo A.","D":"O exame bacteriológico e o antibiograma da secreção devem ser sempre solicitados."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-214542","number":"214542","sourceNumber":"214542","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente O.A.F., masculino, 67 anos, informa que há 5 meses apresenta constipação\nintestinal, com vários episódios\nintermitentes, de hematoquezia e outros de melena. Procurou\nassistência médica e realizou colonoscopia, cujo laudo foi de ausência de lesões em todo o colo.\nQual é a causa mais comum de hemorragia gastrointestinal originada no intestino delgado?","options":{"A":"Angiodisplasia.","B":"Neoplasia.","C":"Divertículo.","D":"Divertículo de Meckel."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-208576","number":"208576","sourceNumber":"208576","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Onde ocorre, geralmente, o barotrauma do esôfago?","options":{"A":"esôfago proximal à esquerda","B":"esôfago distal à esquerda","C":"esôfago médio","D":"esôfago cervical","E":"esôfago à direita"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-181040","number":"181040","sourceNumber":"181040","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As fissuras anais estão em geral associadas a:","options":{"A":"Hipotonia esfincteriana;","B":"Abcessos e criptites anais;","C":"Hipertonia esfincteriana;","D":"Trombose hemorroidária externa."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-181047","number":"181047","sourceNumber":"181047","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Aos pacientes com complicações do divertículo de Meckel, a apresentação clínica mais\ncomum é:","options":{"A":"Estenose;","B":"Malignização;","C":"Diverticulite;","D":"Hemorragia intestinal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-181576","number":"181576","sourceNumber":"181576","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A hemorragia digestiva (alta e baixa) é importante causa de morbidade e de\natendimentos hospitalares de urgência. A\ncaracterização em hemorragia alta ou baixa se dá por\nsua localização anatômica e de acordo com algumas etiologias. Assinale a alternativa que\ncaracteriza CORRETAMENTE as hemorragias digestivas.","options":{"A":"Hemorragia digestiva baixa se localiza abaixo da válvula ileocecal, podendo ser causada por\nangiodisplasia, doença diverticular, GIST de intestino delgado, colite isquêmica, neoplasia de\ncólon.","B":"Hemorragia digestiva alta se localiza acima do ângulo de Treitz, podendo ser causada por\nvarizes esofágicas, esofagite, neoplasia gástrica, gastropatia da hipertensão portal, lesão de\nDieulafoy.","C":"Hemorragia digestiva baixa se localiza acima da válvula ileocecal, podendo ser causada por\nangiodisplasia, doença diverticular, GIST de intestino delgado, colite isquêmica, neoplasia de\ncólon.","D":"Hemorragia digestiva baixa se localiza distalmente ao ângulo de Treitz, podendo ser causada\npor\n\nangiodisplasia, doença diverticular do cólon, lesão de Dieulafoy, síndrome de Mallory-Weiss."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-185265","number":"185265","sourceNumber":"185265","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 32 anos, portadora de constipação intestinal queixa de dor durante a\nevacuação iniciada há 3 semanas, fezes\nressecadas e endurecidas e raias de sangue visíveis no\npapel higiênico. Sobre o diagnóstico mais provável para este caso, assinale a alternativa\nCORRETA.","options":{"A":"Acomete a linha média anterior do canal anal em mais de 90% dos casos.","B":"O tratamento consiste em incisão da pele sobre a lesão para sua retirada sob anestesia local.","C":"Pomadas de bloqueadores de canais de cálcio são efetivas para o tratamento por melhorarem a\nperfusão sanguínea no local da lesão.","D":"Sua causa decorre do esforço evacuatório repetitivo que determina o ingurgitamento dos plexos\nvasculares do canal anal.","E":"Lesão tem origem criptoglandular e geralmente está associada a febre."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-177338","number":"177338","sourceNumber":"177338","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma mulher de 79 anos foi admitida no pronto-socorro com queixa de eliminação de\nsangue vivo e coágulos pelo reto há 4\nhoras. Refre tontura e fraqueza acompanhando o quadro e\ntem, como antecedente, apenas hipertensão arterial leve. Ao exame clínico, apresentava-se\ncontactuante, descorada (++/4+), com FC = 100bpm, PA = 100x60mmHg e sangue vivo ao toque\nretal, sem outras alterações. Além disso, abdome sem particularidades, extremidades apenas com\nvarizes de membros inferiores e perfusão periférica satisfatória. Exames laboratoriais: Hb =\n7,2mg/dl, glicemia = 110mg/dl e creatinina = 1,2 mg/dl. Com relação ao caso, podemos afirmar que:","options":{"A":"a confirmação da enterorragia pelo médico afasta a necessidade de endoscopia digestiva alta","B":"apesar de o quadro sugerir um sangramento súbito e volumoso, ele tende a ser autolimitado","C":"a colonoscopia está contraindicada na vigência de sangramento pelo risco de perfuração do\ncólon","D":"está indicada a reposição de sangue, para estabilização clínica, seguida do tratamento\noperatório, pois esses sangramentos são recorrentes","E":"considerando a idade da peciente e o quadro clínico, a angiotomografia é superior à\ncolonoscopia para o diagnóstico e o tratamento de enterorragia"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-158109","number":"158109","sourceNumber":"158109","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente dá entrada na emergência com quadro de hematêmese volumosa. Foi\nrealizada endoscopia, que observou uma lesão ulcerada em antro, com vaso visível não\nhemorrágico. Trata-se de lesão:","options":{"A":"Forrest IIa, sendo indicado tratamento endoscópico.","B":"Forret Ib, sendo indicado tratamento endoscópico.","C":"Forrest IIb, não sendo indicado tratamento endoscópico.","D":"Forrest III, não sendo indicado tratamento endoscópico."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-109209","number":"109209","sourceNumber":"109209","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A fissura anal crônica apresentará, obrigatoriamente:","options":{"A":"Plicoma sentinela e papila hipertrófica.","B":"Infecção de criptas e dor fora da evacuação.","C":"Exposição de fibras circulares e hipotonia.","D":"Sangramento frequente e dor intensa."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-109214","number":"109214","sourceNumber":"109214","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 70 anos, apresentando intensa hemorragia digestiva baixa\nno momento. As hipóteses diagnósticas mais prováveis são:","options":{"A":"Pólipo gigante em reto e pólipo gigante em sigmoide.","B":"Colite isquêmica e doença diverticular hipotônica.","C":"Retocolite ulcerativa aguda e ectasia vascular.","D":"Ectasia vascular e doença diverticular hipotônica."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-71059","number":"71059","sourceNumber":"71059","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente de 60 anos é portador de doença ulcerosa péptica gástrica de longa data.\nJá realizou mais de 15 endoscopias nos últimos\n30 anos. Apresentou um episódio de hemorragia\ndigestiva alta por úlcera gástrica há 02 anos. Há 20 dias realizou uma nova endoscopia que\nevidenciou uma nova úlcera pré-pilórica. A biópsia foi negativa para neoplasia e para a coloração\nde giemsa. Sua dosagem sérica de gastrina está normal. O paciente deseja realizar uma cirurgia\ncom menor risco de recidiva. A melhor escolha do seu médico é:","options":{"A":"vagotomia troncular com piloroplastia;","B":"vagotomia troncular com gastroenteroanastomose;","C":"vagotomia troncular com antrectomia;","D":"vagotomia superseletiva;","E":"vagotomia seletiva com piloroplastia."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-71080","number":"71080","sourceNumber":"71080","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à fístula anal é correto afirmar:","options":{"A":"abcesso e fístula anal são estádios diferentes de uma mesma doença, que origina de uma\nglândula anal;","B":"a fístula anal, em virtude de infecção crônica, cursa geralmente com febre vespertina;","C":"a regra de Goodsall não se aplica à fistula anal, somente aos abcessos;","D":"o tratamento da fístula perianal com pequeno trajeto geralmente é feito com cauterização de\norifício externo com nitrato de prata;","E":"somente em torno de 10% das fistulas anais são secundárias a um abcesso perianal."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-71066","number":"71066","sourceNumber":"71066","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Considerando-se sua ocorrência e localização, é INCORRETO afirmar que o divertículo\nde Meckel:","options":{"A":"contém todas as camadas do intestino.","B":"é mais comum em pacientes com doença de Crohn que na população em geral.","C":"ocorre na borda antimesentérica.","D":"ocorre sangramento mais comumente em adultos que em crianças.","E":"infecção do mesmo pode apresentar quadro clínico muito semelhante com apendicite aguda."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-360578","number":"360578","sourceNumber":"360578","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, 28 anos, procura atendimento médico queixando de dor intensa na\nregião do ânus, de início há 1 mês, associada a alguns episódios de hematoquezia. Nega vômitos e\ndiarreia. Nega febre. Nega trauma local. É constipado crônico e faz uso esporádico de laxantes. Ao\nexame físico nota-se úlcera linear posterior situada no canal anal que se estende da linha pectínea\nà margem anal e um plicoma na borda da pele com papila anal hipertrófica. Assinale a principal\nhipótese diagnóstica.","options":{"A":"Abscesso anorretal.","B":"Hemorroida.","C":"Fístula anal.","D":"Fissura anal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-332972","number":"332972","sourceNumber":"332972","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"O divertículo de Meckel está localizado:","options":{"A":"No terço proximal do esôfago.","B":"No terço distal do esôfago.","C":"Na borda antimesentérica do íleo, 45 a 60 cm proximal à válvula ileocecal.","D":"No cólon descendente."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-332974","number":"332974","sourceNumber":"332974","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 65 anos, sexo masculino, admitido no PS com quadro de Hemorragia\nDigestiva Baixa (HDB). Nesse caso, assinale a alternativa que contempla a conduta correta.","options":{"A":"A avaliação inicial compreende o exame proctológico e a pesquisa de sangue oculto fecal.","B":"A abordagem cirúrgica está indicada no 2º episódio de hemorragia digestiva baixa quando a\ndoença diverticular for a causa.","C":"A neoplasia colorretal é a principal causa de HDB nessa faixa etária.","D":"A maioria cessa espontaneamente e a colonoscopia é o exame padrão-ouro."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-330660","number":"330660","sourceNumber":"330660","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, 47 anos de idade, procura atendimento médico queixando-se de\nevacuações com sangue de início há 3 dias.\nRelata eliminação de pequenas quantidades de\nsangue vermelho vivo, que pouco se misturam com a fezes. Nega febre. Nega diarreia. Nega dor\nabdominal. Nega trauma. Fez tratamento para câncer de próstata há 3 anos com radioterapia e\ncirurgia. Ao exame físico: bom estado geral, corado, hidratado. Sem sinais de choque hemorrágico.\nToque retal com esfíncter normotônico, sem tumorações alcançáveis, com sangue vermelho vivo\nem dedo de luva. A principal hipótese diagnóstica é:","options":{"A":"Doença diverticular dos cólons.","B":"Retite actínica.","C":"Diverticulite aguda.","D":"Adenocarcinoma de cólon."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-309795","number":"309795","sourceNumber":"309795","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, 62 anos, obeso é admitido na sala de emergência com sudorese\nfria, confuso, palidez cutâneo mucosa e com as\ncalças sujas de sangue vivo. Ao retirar suas vestes\nobserva-se saída de sangue vivo do ânus. Abdome globoso, sem defesa à palpação, sem massas\npalpáveis. Toque retal apenas com presença de sangue vivo na luva, sem evidencias de nódulos\nou tumorações ao toque. PA: 80/60mmHg, FC 118bpm. Coleta de história complementar com\nacompanhante relata que o paciente é hipertenso, diabético, faz uso de losartana, metformina e\nAAS, sem cirurgias abdominais previas. Relata história de constipação intestinal e antes do quadro\natual queixava-se de dores abdominais leves. Não apresentou vômitos. Diante do quadro exposto,\nassinale a alternativa correta:","options":{"A":"Trata-se de um quadro de hemorragia digestiva cuja origem mais provável encontra-se acima do\nângulo de Treitz.","B":"A doença diverticular do cólon, cuja localização mais frequente é o cólon descendente e\nsigmoide é o que mais se correlaciona com este quadro.","C":"Trata-se de quadro típico de doença hemorroidária grau IV, acima do anel hemorroidário interno\ne abaixo da 2º válvula de Houston.","D":"O caso está correlacionado com a síndrome de Mallory-Weiss, uma laceração do reto provocada\npor esforço evacuatório associado a neuropatia\ndesenvolvida pelo diabetes.","E":"Trata-se de hemorragia digestiva alta por provável síndrome de Zollinger Elisson."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-274841","number":"274841","sourceNumber":"274841","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 65 anos, sexo masculino, admitido no PS com quadro de Hemorragia\nDigestiva Baixa (HDB). Nesse caso, assinale a\nalternativa que contempla a conduta CORRETA.","options":{"A":"A avaliação inicial compreende o exame proctológico e a pesquisa de sangue oculto fecal.","B":"A abordagem cirúrgica está indicada no 2º episódio de hemorragia digestiva baixa quando a\ndoença diverticular for a causa.","C":"A forma hipertônica da doença diverticular é causa de sangramento maciço.","D":"A neoplasia colorretal é a principal causa de HDB nessa faixa etária.","E":"A maioria cessa espontaneamente e a colonoscopia é o exame padrão-ouro."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-286094","number":"286094","sourceNumber":"286094","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino, 62 anos, obeso é admitido na sala de emergência com sudorese\nfria, confuso, palidez cutâneo mucosa e com as\ncalças sujas de sangue vivo. Ao retirar suas vestes\nobserva-se saída de sangue vivo do ânus. Abdome globoso, sem defesa à palpação, sem massas\npalpáveis. Toque retal apenas com presença de sangue vivo na luva, sem evidências de nódulos\nou tumorações ao toque. PA: 80/60mmHg, FC 118bpm. Coleta de história complementar com\nacompanhante relata que o paciente é hipertenso, diabético, faz uso de losartana, metformina e\nAAS, sem cirurgias abdominais previas. Relata história de constipação intestinal e antes do quadro\natual queixava-se de dores abdominais leves. Não apresentou vômitos. Diante do quadro exposto,\nassinale a alternativa correta:","options":{"A":"Trata-se de um quadro de hemorragia digestiva cuja origem mais provável encontra-se acima do\nângulo de Treitz.","B":"A doença diverticular do cólon, cuja localização mais frequente é o cólon descendente e\nsigmoide é o que mais se correlaciona com este quadro.","C":"Trata-se de quadro típico de doença hemorroidária grau IV, acima do anel hemorroidário interno\ne abaixo da 2ª válvula de Houston.","D":"O caso está correlacionado com a síndrome de Mallory-Weiss, uma laceração do reto provocada\npor esforço evacuatório associado a neuropatia\ndesenvolvida pelo diabetes.","E":"Trata-se de hemorragia digestiva alta por provável síndrome de Zollinger Elisson."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-276028","number":"276028","sourceNumber":"276028","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 30 anos, chegou ao serviço de emergência com queixa de\nhematêmese e enterorragia, acompanhado de lipotímia. ao exame apresentava-se sudoreico, com\npalidez cutâneo mucosa acentuada, hipotenso, taquicárdico, com pulso fino e filiforme . sua esposa\nrelatou que o mesmo vinha apresentando dor intensa na região epigástrica, em queimação, que\nmelhorava com leite e com a alimentação; trouxe do upa exame com hg-8,0 g/dl ht- 26 plaquetas\nacima de 120mil. qual deve ser a medida terapêutica inicial neste caso?","options":{"A":"endoscopia digestiva alta","B":"repor líquido e, assim que for possível, repor hemácias.","C":"endoscopia digestiva baixa","D":"jejum oral; dois acessos venos periférico calibrosos e expansão volêmica"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-284175","number":"284175","sourceNumber":"284175","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A mucosa heterotópica mais frequentemente encontrada dentro de um Divertículo de\nMeckel é:","options":{"A":"Pancreática.","B":"Duodenal.","C":"Gástrica.","D":"Colônica."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-274897","number":"274897","sourceNumber":"274897","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 65 anos, sexo feminino, é admitida na emergência de um hospital geral\ncom quadro de hematêmese volumosa, sangramento\noriginado de alguma patologia (doença)\ngástrica ou devido a rompimento de varizes esofagogástricas. O caso apresentado tem relação com\nhemorragia digestiva alta. Sobre essa doença, assinale a alternativa correta.","options":{"A":"Considera-se hemorragia digestiva alta, quando o sangramento tem origem distal ao ligamento\nde Treitz.","B":"A principal causa de hemorragia digestiva alta é neoplasia do trato digestivo superior.","C":"No manejo inicial de um paciente com hemorragia digestiva alta, jejum, monitorização\nhemodinâmica e reposição volêmica criteriosa\nsão fundamentais, independentemente da etiologia\ndo sangramento.","D":"No caso descrito, a paciente deve ser imediatamente transferida para o setor de endoscopia\ndigestiva visando à realização de uma endoscopia digestiva alta na primeira hora.","E":"Na suspeita de hemorragia digestiva alta de origem varicosa, a transfusão de concentrado de\nhemácias deve ser realizada se os níveis de hemoglobina estiverem abaixo de 10 g/dl, devido ao\nmaior risco de instabilidade hemodinâmica nos cirróticos."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-284181","number":"284181","sourceNumber":"284181","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"É uma úlcera linear envolvendo a metade inferior do canal anal, em geral localizada na\ncomissura posterior na linha média. Os achados associados característicos incluem dilatação\nvaricosa-sentinela e um plicoma, externamente e, uma papila anal dilatada, internamente. Pelo fato\nde envolver o epitélio escamoso, altamente sensível, tal doença no ânus com frequência são\ndolorosas.","options":{"A":"Fissura anal.","B":"Hemorroida.","C":"Plicoma.","D":"Pólipo anal."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-247042","number":"247042","sourceNumber":"247042","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação ao tema Hemorragia Digestiva Baixa (HDB), assinale a alternativa\nincorreta.","options":{"A":"Em 85% dos casos, o sangramento cessa espontaneamente.","B":"A doença diverticular do cólon é a principal causa de HDB maciça.","C":"O Divertículo de Meckel é a principal causa de sangramento gastrintestinal significativo em\ncrianças.","D":"O sangramento gastrintestinal de origem obscura caracteriza-se pelo achado de anemia e/ou\nsangue oculto fecal positivo, sem diagnóstico etiológico após realização de endoscopia digestiva\nalta e de colonoscopia.","E":"Todos os pacientes que apresentam hematoquezia, obrigatoriamente, necessitam de avaliação\nproctológica e pesquisa de sangue oculto fecal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-247057","number":"247057","sourceNumber":"247057","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"No que diz respeito às fístulas anorretais, assinale a alternativa incorreta.","options":{"A":"A maioria, cerca de 70%, é decorrente da infecção das glândulas de Chiari localizadas no\nespaço interesfincteriano.","B":"As fístulas interesfincterianas são o tipo mais comum.","C":"A maioria das fístulas anorretais é de causa específica, como doença de Crohn, tuberculose,\nlinfogranuloma venéreo, empalamento e colite ulcerativa.","D":"Nas fístulas em ferradura, observam-se 2 orifícios externos laterais ao orifício anal, e o\norifício\ninterno localiza-se na linha média posterior.","E":"Nos casos em que não se identifica o orifício externo ou interno, essas fístulas são chamadas de\nincompletas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-239643","number":"239643","sourceNumber":"239643","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinale a alternativa incorreta com relação ao diagnóstico do divertículo de Meckel:","options":{"A":"É a anomalia congênita mais comum do trato gastrointestinal e ocorre em aproximadamente 2%\nda população.","B":"Mais de 70% dos pacientes sintomáticos têm mucosa gástrica heterotópica e outros 5%\npossuem tecido pancreático associado.","C":"O tratamento cirúrgico é a terapia definitiva.","D":"\"Em pacientes com divertículo de Meckel sem ulceração ou inflamação envolvendo o íleo na\nbase do divertículo, a ressecção do\n\níleo com anastomose primária termino-terminal é a abordagem cirúrgica preferível.\""},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-239656","number":"239656","sourceNumber":"239656","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação às fístulas anais, assinale a alternativa incorreta:","options":{"A":"Nas fístulas transesfincterianas, o trajeto ultrapassa o esfíncter externo para caminhar através\nda\nfossa isquiorretal e terminar na pele perineal.","B":"As fístulas supraesfincterianas são raras, de difícil tratamento e podem ser problemáticas se\ntratadas por cirurgiões inexperientes.","C":"As fístulas transesfincterianas são as fístulas anais mais comuns e, na maioria dos casos, a\ninfecção se estende caudalmente até a margem anal.","D":"As principais causas de fístula extraesfincteriana são trauma, externo ou interno (p. ex.,\nperfuração pelo osso de um peixe de uma das\nparedes do reto), carcinoma ou doença de Crohn."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-213995","number":"213995","sourceNumber":"213995","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Admitido no PS paciente de 65 anos de idade, sexo masculino que, segundo familiares,\napresentou 4 episódios de Hematêmese volumosa. É hipertenso controlado. Ao exame clínico,\nencontra-se confuso, descorado 3+/4+, PA90/60 mmHg, Fc 125 bpm, e sem alteração nos exames\nclínico abdominal e torácico. Foram tomadas medidas clínicas iniciais de ressucitação volêmica e\ntranfusão sanguínea, porém o paciente se mantém taquicárdico e hipotenso. Ante a esse caso, o\npaciente","options":{"A":"deve ser levado para cirurgia de emergência.","B":"deve ser submetido à Endoscopia Digestiva Alta em até 24 horas.","C":"deve ser encaminhado para UTI e submetido à Endoscopia Digestiva Alta imediatamente.","D":"é considerado de alto risco, assim este deve ser encaminhado à UTI, e ser submetido à\nEndoscopia Digestiva Alta após estabilização clínica.","E":"é considerado de alto risco, então deve ser encaminhado à UTI, devendo-se passar balão\nesofágico tipo Sengstaken-Blakemore, e após 24\nhoras ser submetido à Endoscopia Digestiva Alta."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-216874","number":"216874","sourceNumber":"216874","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação ao tipo de fístulas anorretais observamos a figura e suas letras; assinale a\nopção correta que corresponde a letra b:","options":{"A":"Fístula intraesfincteriana.","B":"Fístula extraesfincteriana.","C":"Fístula superficial.","D":"Fístula interesfincteriana."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":["question_bank/media/medcurso/med-cirurgia-med-cir-03/216874.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-213979","number":"213979","sourceNumber":"213979","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"É uma doença muito comum, devendo ser prontamente reconhecida pelo médico da\nfamília. [...] é uma lesão longitudinal\ndolorosa, localizada no canal anal que se inicia um pouco\nabaixo da linha pectínea até a margem anal. Pode ser resultado direto de trauma direto produzido\npor fezes endurecidas. Apresenta-se por uma inflamação pronunciada na área circundante e está\ndiretamente associada a hipertonia esfincteriana devido a dor no local [...]. Sua localização mais\nfrequente é no polo posterior do ânus (66 a 86% dos casos), sendo que a lesão anterior aparece\nem 8% dos homens e em 25% das mulheres [...]. Caso o toque seja possível, é notável o aumento\nno tônus da musculatura do esfíncter anal, evidenciando um dos achados característicos da\ndoença. A lesão aguda é um solução de continuidade superficial com a mucosa anal. A lesão\ncrônica é uma úlcera bem definida com bordos irregulares, base endurecida e fibrosa. Com base na\ndescrição, o diagnóstico é compatível com (GUSSO, G.; LOPES, J.M.C. Tratado de medicina de\nfamília e comunidade: princípios, formação e prática. Porto Alegre: Artmed, 2012. p. 1386.)","options":{"A":"Sífilis.","B":"HIV.","C":"Doença de Chron.","D":"Colite ulcerativa.","E":"Fissura anal."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-177097","number":"177097","sourceNumber":"177097","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação às hemorragias digestivas baixas é correto afirmar que:","options":{"A":"A hemorragia digestiva baixa (HDB) é caracterizada por todo sangramento proveniente de área\nlocalizada entre o estômago e o ânus, podendo se manifestar como enterorragia, melena ou\nsangramento oculto nas fezes.","B":"podem ser classificadas de acordo com sua localização no trato gastrintestinal, sendo o íleo\nterminal o local de maior ocorrência (74%).","C":"A maior parte dos casos de HDB cessa espontaneamente, porém em pacientes com risco de\ncomplicação grave, a terapia deve ser instituída para evitar recorrências. Os tratamentos mais\nutilizados são procedimentos hemostáticos por colonoscopia e embolização por angiografia\ntransarterial, para sangramento mais intensos.","D":"A principal causa de HDB em adultos e idosos são as úlceras gastroduodenais (38%), seguida\npela angiodisplasia. Já em adolescentes e adultos\njovens (menores que 30 anos de idade), a causa\nmais comum é o divertículo de Meckel."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-177001","number":"177001","sourceNumber":"177001","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre o divertículo de Meckel, assinale a alternativa INCORRETA:","options":{"A":"É a anomalia congênita mais encontrada no intestino delgado","B":"Resulta de um fechamento incompleto do ducto onfalomesentérico.","C":"Comumente é revestido de mucosa gástrica.","D":"Sua principal complicação é a perfuração."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-156181","number":"156181","sourceNumber":"156181","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à Hemorragia Digestiva Alta, assinale a alternativa correta.","options":{"A":"No Forrest lb, tem-se o vaso visível e sem sangramento ativo, devendo ser tratado com\nescleroterapia.","B":"Úlceras da parede anterior na 1ª porção do duodeno apresentam sangramento intenso, sendo\ndifícil controle endoscópico.","C":"Varizes de fundo gástrico são tratadas preferencialmente com cianoacrilato.","D":"No Forrest la, opta-se por cirurgia, já que o sangramento em jato impossibilita a\nescleroterapia.","E":"Varizes de fundo gástrico são tratadas preferencialmente com ligadura elástica."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-151633","number":"151633","sourceNumber":"151633","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher de 34 anos deu entrada no Pronto Socorro com queixa defezes enegrecidas há\numa semana. Há um dia apresentou um episódio\nde vômito com sangue. Refere ter feito uso de\nmedicação para dor nos joelho por 5 dias, mas não lembra o nome. Etilista crônica de meia garrafa\nde pinga por semana. Ao exame físico apresenta palidez muco-cutânea 1+/4+, PA 90x50mmhg,\nfrequência cardíaca de 180bpm, exame cardiopulmonar e do abdome sem alterações.\n\nConsiderando o caso acima a principal hipótese diagnóstica:","options":{"A":"Tumor de cólon.","B":"Varizes esofagogástrica.","C":"Úlcera péptica.","D":"Síndrome de Mallory-Weiss."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-151636","number":"151636","sourceNumber":"151636","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Dentre os exames de imagem abaixo qual deve ser solicitado nesse momento:","options":{"A":"Ultranossografia endoscópica.","B":"Endoscopia digestiva alta.","C":"Colonoscopia.","D":"Cintilografia abdominal."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-151594","number":"151594","sourceNumber":"151594","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com dor anal intensa durante o dia apresentando intenso desconforto ao\nsentar-se, acompanhado de sangramento ao evacuar. A dor piora muito após as evacuações,\npermanecendo por pelo menos duas horas, que aliviam após o banho morno. Ao exame físico:\npresença deplicoma às 18h exposição da musculatura do esfíncter interno e papila hipertrófica.\nAssinale a principal hipótese diagnóstica:","options":{"A":"Tumor anal.","B":"Fissura anal.","C":"Hemorróida interna.","D":"Hemorróida externa trombosada."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-137993","number":"137993","sourceNumber":"137993","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo feminino apresenta secreção purulenta nas vestes. Com relação a\nessa afecção, assinale a alternativa correta.","options":{"A":"A etiologia da grande maioria dos casos relaciona-se com inflamações nas glândulas de Chiari.","B":"Nas fístulas interesfincterianas ocorre o acometimento do esfíncter externo do ânus.","C":"A ausência do orifício externo da fístula obriga a realização de fistolografia pré-operatória.","D":"A colonoscopia é obrigatória no pré-operatório para afastar a possibilidade de doença\ninflamatória intestinal na etiologia.","E":"O abscesso anal é decorrente da fístula."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-138005","number":"138005","sourceNumber":"138005","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação às hemorragias digestivas, assinale a alternativa CORRETA.","options":{"A":"As doenças do trato digestivo alto não têm relação com as hemorragias digestivas baixas (HDB)\nmaciças.","B":"A principal causa de hemorragia digestiva baixa intermitente é o câncer colorretal.","C":"O sangramento da ectasia vascular na HDB é arterial.","D":"A aplicação do balão de Sengstaken-Blakemore deve ser feita em situações de hemorragias\ndigestivas altas varicosas com a ingestão de 40\nmmHg no balão esofágico e no balão gástrico, nos\ncasos em que não foram possíveis o sucesso de outros métodos.","E":"O início do tratamento das varizes esofagianas relaciona-se ao calibre destas."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-138033","number":"138033","sourceNumber":"138033","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem de 48 anos, com diagnóstico de cirrose secundária à hepatite C, estava\ninternado devido a sangramento digestivo por\nruptura de varizes esofagianas. No oitavo dia de\ninternação, passou a apresentar confusão mental, piora de icterícia, redução de volume urinário e\npiora de ascite; submetido à paracentese, mostrou = 900 leucócitos/mm³, com 90% de\npolimorfonucleares. A respeito desse caso, assinale a alternativa INCORRETA:","options":{"A":"A complicação adquirida é peritonite bacteriana espontânea.","B":"O antibiótico de escolha para tratamento desse caso é o ciprofloxacino.","C":"No sangramento digestivo em cirróticos, o uso de antibióticos profiláticos reduz a incidência\ndessa complicação.","D":"Nesse caso, está indicado uso de albumina intravenosa com aumento de sobrevida.","E":"A ocorrência dessas complicações pode ter se manifestado pelo uso de doses altas de inibidor\nde bomba de prótons para tratamento de\nsangramento digestivo."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-138032","number":"138032","sourceNumber":"138032","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A úlcera de estresse define as lesões erosivas ou ulceradas da mucosa gástrica,\nassociadas a estresse fisiológico extremo\n(sepse, politraumatismo ou queimadura grave). Nas\nUnidades de Terapia Intensiva (UTI), atualmente, estima-se uma incidência de 1,5% de\nsangramento digestivo clinicamente importante secundário à úlcera de estresse. Sobre a profilaxia\npara o Sangramento Digestivo por Úlcera de Estresse (SDUE), assinale a alternativa CORRETA:","options":{"A":"Está contraindicada a profilaxia medicamentosa em pacientes com coagulopatia.","B":"Está contraindicada essa profilaxia em pacientes em UTI pelo risco de desenvolvimento de\npneumonia associada à ventilação mecânica.","C":"Há superioridade do uso de sucralfato sobre uso de inibidor de bomba de prótons.","D":"São considerados de alto risco para sangramento digestivo por úlcera de estresse pacientes\ndependentes de suporte ventilatório invasivo por mais de 48 horas.","E":"Está indicada endoscopia digestiva alta profilática em pacientes com mais de 7 dias de\ninternação em UTI."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-130058","number":"130058","sourceNumber":"130058","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A principal causa de hemorragia digestiva alta em adultos é:","options":{"A":"Úlcera péptica.","B":"Varizes de esôfago.","C":"Neoplasias.","D":"Síndrome de Mallory-Weiss."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-111745","number":"111745","sourceNumber":"111745","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à fisiopatologia da hipertensão portal, em qual das alternativas abaixo\nconsta a ação desejada para estancar a hemorragia digestiva alta?","options":{"A":"Vasodilatação periférica.","B":"Vasodilatação esplâncnica.","C":"Vasoconstrição esplâncnica.","D":"Vasoconstrição periférica.","E":"Vasoconstrição periférica e vasodilatação esplâncnica."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-111781","number":"111781","sourceNumber":"111781","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual a principal causa da Hemorragia digestiva alta?","options":{"A":"Câncer gástrico.","B":"Úlcera Péptica Duodenal.","C":"Varizes Esofagianas.","D":"Esofagite.","E":"Gastrite hemorrágica aguda."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-111727","number":"111727","sourceNumber":"111727","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à Doença Diverticular dos Colons (DDC), assinale a alternativa\nINCORRETA:","options":{"A":"A doença diverticular pode ocorrer em todo o cólon, porém a região mais frequentemente\nacometida é o sigmóide e raramente há doença\nabaixo da reflexão peritoneal.","B":"Estima-se que 10-25 % dos pacientes com diverticulose cólica evoluirão com diverticulite.","C":"A cirurgia eletiva não é mandatória após diverticulite complicada ou que evoluiu com fístula ou\nestenose.","D":"A tomografia computadorizada (TC) é o melhor exame diagnóstico.","E":"O tratamento da diverticulite aguda não complicada é clínico e pode ser ambulatorial com dieta\nrica em fibras e antibioticoterapia oral de amplo espectro."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-107546","number":"107546","sourceNumber":"107546","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com 40 anos, sexo feminino, apresenta eliminação de secreção purulenta nas\nvestes. Na inspeção e exame proctológico nota-se orifício externo localizado a 2,0 cm do orifício\nanal, com apresentação posterior. O toque retal apresenta hipotônia do tônus esfincteriano. Nesse\ncaso:","options":{"A":"A colonoscopia deve ser realizada previamente.","B":"A fistulografia é útil na localização do orifício interno.","C":"A manometria anorretal pode ajudar no planejamento da cirurgia.","D":"A abordagem cirúrgica neste caso é facilitada pela introdução inicial do estilete, devido ao\ntrajeto\nradiado.","E":"Deve ser aplicado o sedenho."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-107600","number":"107600","sourceNumber":"107600","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à Hemorragia disgestiva baixa, assinale a alternativa correta:","options":{"A":"A doença hemorroidária é causa de sangramento baixo maciço.","B":"A cintilografia com hemácias marcadas é o padrão ouro no diagnóstico de sangramento\nproveniente do divertículo de Meckel.","C":"A anemia é o sintoma mais frequente nos casos de adenocarcinoma do cólon esquerdo.","D":"O sangramento por varizes colorretais causa hematoquezias e é facilmente controlado por\ncolonoscopia.","E":"No sangramento obscuro, a pesquisa de sangue oculto nas fezes é o primeiro exame a ser\nrealizado."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-81103","number":"81103","sourceNumber":"81103","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Quanto à vascularização do reto e canal anal, assinale a alternativa correta:","options":{"A":"A artéria retal superior é ramo direto da artéria mesentérica superior.","B":"A artéria pudenda é ramo direto da artéria ilíaca externa e irriga a junção retossigmoidiana.","C":"A artéria retal inferior é ramo da artéria pudenda interna.","D":"A artéria retal média é ramo direto da artéria mesentérica inferior.","E":"A artéria retal inferior é ramo direto da artéria mesentérica inferior."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-81118","number":"81118","sourceNumber":"81118","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Quanto às doenças do canal anal, é incorreto afirmar que:","options":{"A":"A fissura anal é mais frequente na região posterior.","B":"O PPH (Procedimento para Prolapso Hemorroidário) está indicado como tratamento de\nhemorroidas grau 2, 3 e 4.","C":"O PPH (Procedimento para Prolapso Hemorroidário) tem tempo cirúrgico curto, recuperação\npós-operatória rápida e bons resultados estéticos.","D":"A técnica de Ferguson (aberta) provê maior proteção para complicações sépticas nos casos de\nhemorroidas refratárias ao tratamento clínico.","E":"A principal complicação da ligadura elástica no tratamento da doença hemorroidária é a dor."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-83429","number":"83429","sourceNumber":"83429","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Você foi chamado para avaliar um paciente no CTI, em ventilação mecânica, vítima de\nacidente automobilístico com trauma cranioencefálico grave. Este paciente evoluiu no 6º dia de\ninternação com melena e choque. Assinale a alternativa que justifique o motivo desta complicação:","options":{"A":"O paciente desenvolveu hemorragia digestiva alta por ''úlcera de Cushing''.","B":"O paciente desenvolveu hemorragia digestiva alta pelo trauma abdominal.","C":"O paciente desenvolveu hemorragia digestiva alta por síndrome de Boerhaave.","D":"O paciente desenvolveu hemorragia digestiva baixa por trauma abdominal.","E":"O paciente desenvolveu hemorragia digestiva alta pelo uso de corticoides."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-83430","number":"83430","sourceNumber":"83430","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Dentre as causas de hemorragia digestiva baixa, assinale a principal causa de\nsangramento de grande volume em paciente de 55 anos.","options":{"A":"Neoplasia colorretal","B":"Divertículo de Meckel","C":"Angiodisplasia","D":"Doença hemorroidária","E":"Doença diverticular do cólon"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-60317","number":"60317","sourceNumber":"60317","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 32 anos, sexo feminino, dá entrada no pronto-socorro devido à\nhematêmese e melena há 12 horas. Realizadas\nmedidas clínicas para tratamento de Hemorragia\nDigestiva Alta (HDA). A paciente é encaminhada para Endoscopia Digestiva Alta e retorna com o\nseguinte laudo: esôfago e estômago sem alterações; presença de úlcera duodenal anterior Forrest\nlla. Assinale a alternativa CORRETA.","options":{"A":"Trata-se de sangramento ativo e a chance de persistência ou recorrência do sangramento é de\n75% a 90%.","B":"Trata-se de úlcera sem sangramento e deve-se pesquisar outras causa de HDA.","C":"Trata-se de coágulo aderido e a chance de persistência ou recorrência do sangramento é de\n75% a 90%.","D":"Trata-se de vaso visível e a chance de persistência ou recorrência do sangramento é de 38% a\n50%.","E":"Trata-se de hemorragia em gotejamento e a chance de persistência ou recorrência do\nsangramento é de 70%."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-60330","number":"60330","sourceNumber":"60330","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A complicação mais frequente da úlcera péptica gastroduodenal é:","options":{"A":"Perfuração.","B":"Sangramento.","C":"Estenose.","D":"Tenebrar para o pâncreas.","E":"Malignização."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-64925","number":"64925","sourceNumber":"64925","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com 46 anos, sexo masculino, antecedentes de etilismo, apresentou\nhemorragia digestiva. A frequência cardíaca era\nde 120 bpm. Este paciente recebeu acesso venoso\ncom soro fisiológico e outras medidas de ressuscitação e foi encaminhado para endoscopia\ndigestiva alta para diagnóstico e possível terapia. Após seis horas, o paciente encontrava-se com\nFC de 150 bpm, não ocorrendo aumento da PAS. Observando os critérios de Baveno, qual é a\nconduta admitida?","options":{"A":"Considerar o Balão de Sengstaken Blakemore.","B":"Realizar ligadura elástica.","C":"Encaminhar o paciente para cirurgia.","D":"Realizar nova endoscopia digestiva imediatamente.","E":"Aplicação do TIPS."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-64871","number":"64871","sourceNumber":"64871","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual é a principal etiologia de hematoquezia maciça em adultos?","options":{"A":"Divertículo de Meckel.","B":"Angiodisplasia.","C":"Neoplasia.","D":"Diverticulose.","E":"Colite ulcerativa."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-45439","number":"45439","sourceNumber":"45439","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 18 anos, sexo masculino, refere há 3 dias dor anal intensa às evacuações,\nque persiste por cerca de 2 horas após a\nevacuação, que teve início ao evacuar fezes endurecidas.\nAcompanha o quadro hematoquezia. O quadro clínico é mais compatível com:","options":{"A":"Doença hemorroidária.","B":"Condiloma anal.","C":"Fissura anal aguda.","D":"Câncer de canal anal.","E":"Fístula anal."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-45450","number":"45450","sourceNumber":"45450","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 44 anos, sexo masculino, apresenta dor na região anal há 3 dias, além de\ntumoração local e febre não aferida. Nega vazamento de secreção purulenta ou sangramento local.\nHábito intestinal diário, sem alterações. Ao exame físico, observa-se turnoração na borda anal de\naproximadamente 3 cm de diâmetro, endurecida, com aumento de temperatura e hiperemia. O\ntoque retal é doloroso, mas sem outras alterações. A conduta adequada é:","options":{"A":"Tomografia computadorizada de pelve.","B":"Ciprofloxacina e Metronidazol.","C":"Drenagem cirúrgica apenas, já que não há indicação de antibioticoterapia nessa situação.","D":"Ligadura elástica ou escleroterapia.","E":"Esfincterotomia lateral interna."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-45899","number":"45899","sourceNumber":"45899","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à etiologia da hemorragia digestiva alta (HDA), podemos afirmar que:","options":{"A":"A lesão de Dieulafoy consiste na laceração longitudinal da mucosa e submucosa a nível do\npiloro e pode ser tratada clinicamente.","B":"As anormalidades vasculares representam cerca de 30% dos sangramento da HDA.","C":"Na hipertensão portal, a maior causa de HDA é sangramento, principalmente de varizes\nesofagianas","D":"Fístulas aorticoentéricas responsáveis por HDA se localizam principalmente no corpo gástrico.","E":"A esofagite erosiva ocorre principalmente pelo refluxo gastroduodenal e raramente causa\nsangramento digestivo."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-45493","number":"45493","sourceNumber":"45493","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 60 anos, sexo masculino, dá entrada no pronto socorro com hematêmese -\n3 episódios e melena - 2 episódios, há 4 horas. Fez uso de antiinflamatório não esteroidal, um\ncomprimido há 12 horas por dor no pé. É tabagista, 20 cigarros/dia. Nega ser etilista ou apresentar\ndoenças do fígado. Está com frequência cardíaca de 118 batimentos por minuto e pressão arterial\nde 110 x 60 mmHg. Em relação a esse caso é correto afirmar, EXCETO:","options":{"A":"A causa mais provável para o sangramento é úlcera péptica e há 80% de chance de cessar\nespontaneamente.","B":"Caso demonstre tratar-se de úlcera duodenal posterior, há indicação de tratamento cirúrgico,\nconsiderando-se a situação clínica do paciente e o índice de ressangramento superior a 90%.","C":"Deve-se fazer endoscopia digestiva alta, que é o método diagnóstico com melhor acurácia.","D":"A lavagem gástrica com solução salina gelada está contraindicada, mas a passagem de sonda\ngástrica e lavagem do estômago com solução salina em temperatura ambiente pode e deve ser\nrealizada previamente à endoscopia.","E":"Os antiinflamatórios não esteroidais podem causar úlcera péptica tanto por efeito tóxico direto à\nmucosa quanto por efeito sistêmico por inibição da síntese das prostaglandinas."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-31902","number":"31902","sourceNumber":"31902","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação às doenças orificiais, assinale a alternativa INCORRETA.","options":{"A":"Hemorroidas de grau III são aquelas que sangram, exteriorizam-se e podem ser reduzidas por\nmanobras digitais. O tratamento cirúrgico ou ligadura elástica são opções válidas para tratamento.","B":"Dor anal após a evacuação que persiste por minutos ou horas, geralmente acompanhada de\nsangramento vivo rutilante, é altamente sugestiva de fissura anal aguda. Confirmado o diagnóstico,\no tratamento deve ser cirúrgico.","C":"As fístulas interesfinctéricas são mais frequentes. O tratamento é a fistulotomia ou\nfistuloctomia.","D":"Uso de pimenta, constipação intestinal e prática de sexo anal receptivo não são fatores\netiológicos da doença hemorroidária.","E":"Pacientes jovens, com sangramento anal às evacuações, que têm doença hemorroidária ao\nexame físico, necessitam, ainda assim, da\nrealização de retossigmoidoscopia para descartar outras\ndoenças que possam cursar com sangramento."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-31916","number":"31916","sourceNumber":"31916","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à Hemorragia Digestiva Alta (HDA), assinale a alternativa INCORRETA.","options":{"A":"Pacientes que apresentam HDA por úlcera péptica que, à endoscopia digestiva alta,\napresentam vaso visível com sinais de\nsangramento recente (Forrest Ila), têm 50% de chance de\nnovo sangramento.","B":"Após a estabilização clínica do paciente com HDA, a endoscopia digestiva alta deve ser\nrealizada visando o diagnóstico e o possível tratamento.","C":"Pacientes que apresentam novo episódio de sangramento em menos de 48 horas do quadro\ninicial, e que já têm diagnóstico feito por endoscopia realizada na admissão da úlcera duodenal\nsangrante, têm indicação de tratamento cirúrgico.","D":"Dos pacientes que, sabidamente, têm varizes de esôfago e apresentam HDA, somente um terço\nterá como causa do sangramento a ruptura\ndessas varizes. Os outros dois terços terão como causa\noutras fontes de sangramento, como, por exemplo, úlcera péptica.","E":"A ligadura elástica de varizes no esôfago tem melhor resultado do que a escleroterapia."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-34578","number":"34578","sourceNumber":"34578","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino de 48 anos dá entrada no pronto socorro do HRMS com história de\nque há 8 dias iniciou com fezes pretas\namolecidas e fétidas e há 2 horas atrás foi tomar banho teve\nlipotíma. Apresenta-se com fraqueza há três dias. Ao interrogatório complementar, etilista há 20\nanos fazendo uso de 3 garrafas de aguardente por semana. Assinale dentre as alternativas abaixo\na resposta correta em relação a conduta inicial do paciente:","options":{"A":"A administração oral de betabloqueadores com expansão rápida de 2000ml de colóide.","B":"Expansão volêmica rápida com 2000ml de água livre devido a retenção de sódio de tais\npacientes.","C":"Laparotomia exploradora de urgência para ráfia de prováveis varizes sangrantes.","D":"Solicitar Endoscopia digestiva alta expansão rápida com 2000ml de cristalóide.","E":"Solicitar vaga do CTI pois o paciente pode fazer parada cardiorespiratória."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-34573","number":"34573","sourceNumber":"34573","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente masculino de 48 anos dá entrada no pronto-socorro do HRMS com história de\nque há 8 dias iniciou com fezes pretas\namolecidas e fétidas e há 2 horas atrás, quando foi tomar\nbanho, teve lipotíma. Apresenta-se com fraqueza há três dias. Ao interrogatório complementar,\netilista há 20 anos fazendo uso de 3 garrafas de aguardente por semana. Em relação ao paciente\nacima, o mesmo faz um episódio de hematêmese e ficou torporoso. Dentre as abaixo todas estão\ncorretas para serem realizadas no pronto-socorro, EXCETO:","options":{"A":"Passagem sonda nasogástrica e lavagem do estômago com soro fisiológico na temperatura\nambiente.","B":"Entubação orotraqueal.","C":"Paciente em decúbito dorsal a zero grau.","D":"Passagem de balão Sengstaken-Blakemore.","E":"Solicitação concentrado de hemácias."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-22653","number":"22653","sourceNumber":"22653","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinale a alternativa correta em relação aos Divertículos de Meckel.","options":{"A":"É a malformação mais frequente do tubo digestivo.","B":"As manifestações clínicas, quando presentes, ocorrem mais frequentemente após a puberdade.","C":"As complicações mais frequentes são a obstrução em crianças pequenas e sangramento em\nadultos.","D":"Localizam-se, no máximo, até 40 cm da válvula ileocecal.","E":"O uso de grampeadores mecânicos é contraindicado no tratamento dessa afecção, por\ninduzirem o maior número de recidivas e estenoses do que com sutura manual."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-22660","number":"22660","sourceNumber":"22660","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação aos divertículos colônicos.","options":{"A":"Os divertículos do colo são mais corretamente denominados pseudodivertículos, uma vez que na\ngrande maioria dos casos, são formados apenas pelas camadas mucosa e serosa.","B":"Apesar de muito frequentes na população geral, apenas 20% dos indivíduos com divertículos\napresentam sintomas e menos de 1% apresenta complicações graves","C":"Na grande maioria dos casos de diverticulite, o processo inflamatório é drenado\nespontaneamente para dentro da luz colônica, de\nmodo que perfuração ou microperfuração\nbloqueada do colo são situações de exceção.","D":"A tomografia computadorizada de abdome tem boa indicação na suspeita de diverticulite, sendo\nachados frequentes nessa situação, a\ninfiltração da gordura pericólica e o espessamento da parede\ncólica maior que 4mm.","E":"Em média, 20% dos pacientes com diverticulite necessitam de tratamento cirúrgico de urgência."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-8819","number":"8819","sourceNumber":"8819","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As principais causas de hemorragia digestiva baixa em pacientes com mais de 50 anos\nsão:","options":{"A":"hemorroidas e doença diverticular dos colos.","B":"uso de antiinflamatório não esteroides e engiodisplasias.","C":"angiodisplasia e doença diverticular dos colos.","D":"hemorroidas e colite isquêmica.","E":"neoplasia de colo e angiodisplasia."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-301008","number":"301008","sourceNumber":"301008","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre o manejo da Hemorragia Digestiva Baixa (HDB) em adultos, assinale a\nalternativa CORRETA.","options":{"A":"A doença diverticular do cólon é a principal causa de HDB, sendo que, na maioria dos casos,\nocorre resolução espontânea do sangramento.","B":"A angiografia dos vasos mesentéricos pode ser indicada nos casos de HDB, contudo, há a\ndesvantagem de não serem possíveis as intervenções terapêuticas durante o exame.","C":"O exame de escolha para o diagnóstico topográfico e etiológico da HDB em pacientes\nhemodinamicamente estáveis é a cintilografia com hemácias marcadas.","D":"Em pacientes com enterorragia volumosa não está indicada a endoscopia digestiva alta, já que\nessa é a apresentação clínica típica dos\nsangramentos colônicos."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-238629","number":"238629","sourceNumber":"238629","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação ao papel da endoscopia na Hemorragia Digestiva Alta (HDA), assinale\ncom V as afirmativas Verdadeiras e com F\nas Falsas. ( ) A endoscopia é de extrema importância\nnos casos de sangramento do trato gastrintestinal superior, seja no diagnóstico, podendo classificar\na natureza da lesão, ou como terapia intervencionista. ( ) A endoscopia pode ser utilizada para\navaliar a mucosa visualmente, mas não permite a biópsia de lesões suspeitas de neoplasia. ( ) Nos\ncasos de sangramento do trato gastrintestinal superior, a endoscopia deve ser realizada dentro de\n24 horas. ( ) O desfecho de pacientes com HDA é afetado pelo tempo que a endoscopia é realizada\ne pela qualidade do tratamento endoscópico naqueles que dela necessitam. Assinale a sequência\nCORRETA.","options":{"A":"V?F?F?F.","B":"F?V?F?V.","C":"V?F ?V?V.","D":"F?V?V?F."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-238649","number":"238649","sourceNumber":"238649","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação às hemorragias agudas do trato gastrointestinal, assinale a alternativa\nINCORRETA.","options":{"A":"Hematoquezia geralmente está presente nos casos de sangramento digestivo baixo, embora\ntambém possa ocorrer em sangramentos originados no trato gastrointestinal alto.","B":"A hemorragia digestiva baixa é definida por sangramento que se origina do intestino grosso, ou\nseja, do ceco em diante.","C":"O sangramento cessa espontaneamente na maioria dos casos de hemorragia digestiva aguda\nbaixa.","D":"Colonoscopia, sigmoidoscopia e angiografia podem ser usados na propedêutica de hemorragia\ndigestiva baixa."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-174776","number":"174776","sourceNumber":"174776","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"F.G.H., 68 anos, sexo masculino, aposentado, deu entrada no serviço de urgência após\nser encontrado desfalecido, em seu domicílio,\nem meio a grande quantidade de sangue evacuado.\nApresentava PA de 100 x 60 mmHg; pulso de 112 bpm; descorado (2+/4+). Após estabilização, foi\nencaminhado para propedêutica. A esse respeito, assinale a alternativa CORRETA:","options":{"A":"A colonoscopia tem a vantagem sobre a arteriografia por ser, potencialmente, também\nterapêutica.","B":"A presença de sangue na luz intestinal implica em íleo funcional, prejudicando o preparo\nintestinal para a realização de colonoscopia.","C":"Angiografia esclarecedora necessita de, pelo menos, sangramento ativo de cerca de 0,5 ml/min.","D":"Cintilografia tem o inconveniente de detectar somente sangramento arterial."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-101821","number":"101821","sourceNumber":"101821","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"H.M., sexo feminino, 42 anos, comparece ao ambulatório relatando fraqueza. Foram\nsolicitados exames laboratoriais que evidenciaram anemia (Hb = 10,2 mg%). À anamnese e ao\nexame físico, não foi evidenciada nenhuma alteração. Dentre as opções abaixo, assinale a\nMELHOR conduta:","options":{"A":"Solicitar pesquisa de sangue oculto nas fezes.","B":"Prescrever sulfato ferroso por via oral.","C":"Prescrever ferro por via parenteral.","D":"Solicitar endoscopia digestiva alta e colonoscopia."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-78413","number":"78413","sourceNumber":"78413","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"UGV, 44 anos, sexo masculino, biólogo, diabético, informa dor na região anal há cerca\nde oito horas, com mal-estar e febre. Ao\nexame nota-se induração perianal com dor, calor e rubor,\nsem sinais de flutuação. Toque doloroso, sem massas. A conduta MAIS segura neste caso deve\nser:","options":{"A":"Administração de antibiótico na tentativa de regressão do processo.","B":"Colocação de calor local ou banhos de assento até que ocorra flutuação.","C":"Punção para identificação de loja, seguida de drenagem.","D":"Solicitar hemograma com leucograma, glicemia e ultrassonografia da região, e reavaliação em\n12 horas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-71488","number":"71488","sourceNumber":"71488","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação aos exames laboratoriais básicos em pacientes com hemorragia digestiva,\nassinale a afirmativa FALSA:","options":{"A":"A hemorragia grave é acompanhada de leucopenia","B":"Após quadro de hemorragia, em poucas horas ocorre elevação importante dos níveis de\nplaquetas","C":"É comum o surgimento de reticulocitose após 12 horas do início do episódio","D":"Nas hemorragias graves costuma ocorrer aparecimento de células jovens (eritoblastos e\nmetamielócitos) no sangue periférico"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-60374","number":"60374","sourceNumber":"60374","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher de 86 anos é atendida do pronto socorro do Hospital das Clínicas apresentando\nhematoquezia volumosa. É hipertensa e coronariopata e faz uso de ácido acetilsalicílico, atenolol,\nhidroclorotiazida e sinvastatina. Em relação à abordagem diagnóstica é ERRADO afirmar:","options":{"A":"Angiotomografia computadorizada, exame que também deve ser realizado durante sangramento\nativo, pode fornecer detalhes anatômicos de\nutilidade para intervenções subsequentes tais como\narteriografia.","B":"Arteriografia mesentérica é exame que deve ser realizado na vigência do sangramento, contudo\nrequer taxa de sangramento maior, quando\ncomparada à cintilografia.","C":"Cintilografia com tecnécio - 99 m detecta volumes reduzidos de sangramento, mas não é útil\npara avaliar o local de sangramento.","D":"Colonoscopia é o exame diagnóstico inicial, mas a sua realização precocemente não reduz o\ntempo de internação hospitalar."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-52426","number":"52426","sourceNumber":"52426","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma criança de quatro anos, previamente hígida, em tratamento de um processo febril\nagudo de curso benigno ? sendo necessário apenas o uso de sintomáticos, inicia com um quadro\nde vômitos de conteúdo alimentar, em pequena quantidade. Após alguns episódios, surgem raias\nde sangue nos vômitos. Ao exame clínico a criança apresenta-se bem, sem alterações ao exame\nfísico. O diagnóstico mais provável desse sangramento gastrintestinal é:","options":{"A":"Divertículo de Meckel","B":"Doença inflamatória intestinal","C":"Síndrome de Mallory-Weiss","D":"Varizes esofagianas."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-55354","number":"55354","sourceNumber":"55354","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à diverticulite aguda dos cólons assinale a afirmativa CORRETA:","options":{"A":"A obstrução geralmente é decorrente de processo maligno associado","B":"O enema opaco baritado é o método ideal para o diagnóstico","C":"Pela gravidade do processo, a conduta cirúrgica inicial deve ser só drenagem e colostomia\n(descompressiva)","D":"Recidivas frequentes é indicação de tratamento cirúrgico eletivo"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-55324","number":"55324","sourceNumber":"55324","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à colite isquêmica assinale a afirmativa FALSA:","options":{"A":"As causas podem ser oclusivas e não oclusivas","B":"Entre os medicamentos que podem induzi-la estão a cocaína e a digoxina","C":"O cólon esquerdo é o mais acometido","D":"O sangramento maciço aparece na maioria dos casos"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-31555","number":"31555","sourceNumber":"31555","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo feminino, 60 anos, apresentou hematêmese volumosa com\nhipotensão. Foi submetida à endoscopia\ndigestiva alta que identificou estenose parcial do piloro e\ngrande úlcera em bulbo duodenal com sangramento em jato, que não pôde ser interrompido por\nmanobras endoscópicas. Sua pressão arterial sistólica chegou a 70 mmHg e a equipe médica\ndecidiu submetê-la à cirurgia de urgência. Dentre as abaixo, assinale a alternativa de procedimento\n\n(s) cirúrgico (s) que, associada à ulcerorrafia, se mostra mais adequada neste caso:","options":{"A":"Antrectomia e anastomose gastroduodenal.","B":"Antrectomia e anastomose gastrojejunal.","C":"Cerclagem duodenal e anastomose gastrojejunal.","D":"Piloroplastia à Heineke-Mikulicz."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-31508","number":"31508","sourceNumber":"31508","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 42 anos chega ao Pronto-Socorro levado por populares, com relato de três\nepisódios de hemorragia digestiva alta de grande monta na última hora. Não recebeu nenhum tipo\nde reposição volêmica. Ao exame, apresenta-se hipocorado (3+/4+), sudorético, confuso, FC = 140\nbpm e PA = 80 x 60 mmHg. Em relação a este paciente, podemos afirmar, EXCETO:","options":{"A":"Deve apresentar vasoconstrição das arteríolas da pele, músculos e vísceras abdominais para\ndirecionar o sangue ao coração e cérebro.","B":"Deve receber reposição volêmica, preferencialmente, com coloides para manter o volume no\ncompartimento intravascular.","C":"Existe uma tentativa de compensação pelo estímulo adrenérgico.","D":"O hematócrito à admissão não é parâmetro confiável para se estimar a perda volêmica deste\npaciente."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-31513","number":"31513","sourceNumber":"31513","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente do sexo masculino, 26 anos, queixa-se de gotejamento intermitente de sangue\nvivo às evacuações nos últimos dois anos,\nalém de prurido anal esporádico. Nega dor abdominal,\nperda ponderal e alterações do hábito intestinal. Tia materna faleceu por câncer do cólon\nascendente aos 68 anos. O exame físico geral e abdominal não mostra alterações. A inspeção\nperianal revela grandes mamilos hemorroidários prolapsados, irredutíveis, sem sinais flogísticos ou\nde sangramento. Ao toque, a mucosa é lisa, o tônus anal é normal sem massas palpáveis. A\npróxima conduta indicada deve ser:","options":{"A":"Colonoscopia.","B":"Hemorroidectomia.","C":"Pesquisa de sangue oculto nas fezes.","D":"Retossigmoidoscopia."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-361730","number":"361730","sourceNumber":"361730","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Com relação à classificação de FORREST, utilizada nas hemorragias digestivas altas,\nassinale a afirmativa incorreta.","options":{"A":"Forrest II representa sinais de hemorragia recente, sendo a presença de coágulo aderido\nconsiderada llb, com risco de ressangramento em torno de 30%.","B":"Forrest III representa ausência de sinais de sangramento recente.","C":"Forrest I representa hemorragia ativa, com risco de ressangramento sempre alto, em torno de\n90%.","D":"Forrest III C representa úlceras cicatrizadas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-369749","number":"369749","sourceNumber":"369749","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente `de 52 anos dá entrada no setor de emergência com quadro de hemorragia\ndigestiva alta. Não é etilista nem tabagista, faz uso contínuo de candesartana para hipertensão\narterial e está tratando de dor lombar por hérnia de disco com anti-inflamatório não hormonal e\ncorticóide. Ao exame clínico apresenta taquicardia (FC= 120 bpm), hipotensão arterial (PA=\n80x40mmHg) com perfusão periférica lentificada (tempo de enchimento capilar > 3segundos). A\nconduta apropriada imediata é:","options":{"A":"Endoscopia digestiva alta em caráter de emergência","B":"Estabilização hemodinâmica com cristalóides e/ou hemoderivados","C":"Uso de terlipressina ou octreotídeo para varize esofageana","D":"Angioembolização de vasos gástricos em caráter de emergência"},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-365961","number":"365961","sourceNumber":"365961","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A Classificação de Forrest é um índice desenvolvido para a identificação e\nestratificação do risco de ressangramento\nde úlceras pépticas hemorrágicas. É realizada através da\nvisualização direta da lesão por meio da Endoscopia Digestiva Alta (EDA). O principal objetivo da\nsua utilização é, de acordo com os achados endoscópicos, avaliar a gravidade do sangramento\ngastrointestinal superior decorrente de úlcera gástrica e seu risco de recidiva, e decidir sobre\nalta\nou monitoramento do paciente. Sobre a classificação de Forrest, associe os graus apresentados na\ncoluna 1 com o seu respectivo achado na endoscopia, apresentado na Coluna 2. A associação\nCORRETA é: Coluna 1; 1. Forrest IA. 2. Forrest IIB. 3. Forrest III. Coluna 2; A. Base da úlcera\nlimpa, sem sangramento. B. Sangramento arterial em jato. C. Coágulo aderido.","options":{"A":"1A, 2B, 3C.","B":"3A, 1B, 2C.","C":"2A, 3B, 1C.","D":"1A, 3B, 2C."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-365959","number":"365959","sourceNumber":"365959","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A Hemorragia Digestiva engloba qualquer sangramento que ocorra no trato\ngastrointestinal. Sobre a Hemorragia Digestiva Alta (HDA), é CORRETO afirmar:","options":{"A":"A Síndrome de Mallory-Weiss é caracterizada pela má formação arteriovenosa, telangiectasias e\nectasias vasculares.","B":"É definida como um sangramento decorrente de uma lesão distal ao ligamento de Treitz,\nenvolvendo o esôfago, estômago ou duodeno.","C":"A esofagite erosiva e a lesão de Mallory-Weiss são responsáveis por mais de 90% das causas\nde HDA.","D":"Dentre os fatores de risco para HDA, encontram-se: uso de aspirina, infecção por H. pylori e uso\nde anti-inflamatórios não esteroidais."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-365932","number":"365932","sourceNumber":"365932","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre a Hemorragia Digestiva Baixa (HDB), é CORRETO afirmar:","options":{"A":"A presença de conteúdo biliar sem sangramento diz mais a favor de hemorragia digestiva alta.","B":"Aqueles com sangramento ativo e coagulopatia (RNI > 1,5) e/ou plaquetas < 50.000/mm3 devem\nreceber plasma fresco congelado e/ou\nplaquetas.","C":"O ideal é que a Endoscopia Digestiva Alta (EDA) seja realizada a partir de 48h.","D":"Cerca de 85% dos casos de HDB são causados por hemorragia digestiva alta."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-346199","number":"346199","sourceNumber":"346199","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 43 anos, chega para atendimento no pronto-socorro, relata vômitos com\nsangue, e fezes escurecidas e fétidas há 01 dia. Ao exame físico, encontra-se descorado,\ntaquicárdico e hipotenso. Realizou endoscopia digestiva alta que evidenciou úlcera péptica\n\npré-pilórica, Forrest 1A, sendo realizada hemostasia da ulceração com solução de adrenalina. Doze\nhoras após a terapêutica endoscópica,\napresentou novamente vômitos com sangue em grande\nquantidade, FC = 110bpm, PA:80x40mmHg. Com base no caso e dados clínicos, o tratamento\nadequado deve ser:","options":{"A":"Reposição volêmica e nova endoscopia para terapêutica endoscópica.","B":"Terapia intensiva, inibidor de bomba de prótons e tratamento cirúrgico.","C":"Transferência para angiografia terapêutica e embolização em hospital terciário.","D":"Terapia intensiva e dobrar a dose de inibidor de bomba de prótons endovenoso.","E":"Apenas a introdução de noradrenalina irá solucionar o sangramento, pois além de aumentar a\npressão arterial irá causar vasoconstrição, não sendo necessária nenhuma outra atuação ou\ninvestigação."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-330293","number":"330293","sourceNumber":"330293","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinale a alternativa que apresenta CORRETAMENTE três causas de hemorragia\ndigestiva alta.","options":{"A":"Angiodisplasia, neoplasia de estômago e divertículo de Meckel.","B":"Angiodisplasia, úlcera péptica gastroduodenal e divertículo de Meckel.","C":"Angiodisplasia, úlcera péptica gastroduodenal e neoplasia de estômago.","D":"Úlcera péptica gastroduodenal, neoplasia de estômago e divertículo de Meckel."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-330294","number":"330294","sourceNumber":"330294","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 34 anos apresenta-se no consultório médico com queixa de constipação\nintestinal crônica e hematoquezia há um mês, sem\noutras queixas ou antecedentes pessoais ou\nfamiliares relevantes. Ao exame proctológico completo, foram diagnosticadas hemorroidas internas\nde grau II. É CORRETO afirmar que a medida a ser implementada imediatamente para esse\npaciente deve ser:","options":{"A":"Orientações dietéticas com aumento de ingestão de fibras.","B":"Hemorroidectomia fechada.","C":"Colonoscopia virtual.","D":"Hemorroidopexia grampeada."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-326009","number":"326009","sourceNumber":"326009","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com história conhecida de hipertensão portal esquistossomótica e varizes de\nesôfago de grande calibre, apresenta-se com novo episódio de hemorragia digestiva alta (HDA) e\nrepercussão hemodinâmica grave, mas com estabilização clínica rápida e adequada. Em relação às\nprincipais causas de hemorragias digestivas altas, assinale a alternativa CORRETA.","options":{"A":"Nos pacientes com cirrose hepática e varizes por hipertensão portal deve-se manter a\nhemoglobina acima de 12 g/dL.","B":"A endoscopia digestiva alta terapêutica deve ser feita imediatamente, pois evita o\nressangramento nas primeiras 24h.","C":"Cerca de 80% das HDA de origem não varicosas cessam espontaneamente o sangramento a\ndespeito do início do tratamento.","D":"A HDA de origem não varicosa é causada principalmente por lesão aguda de mucosa\ngastroduodenal e tumores gástricos."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-300998","number":"300998","sourceNumber":"300998","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente feminino, 46 anos de idade, procura atendimento médico de urgência em\ndecorrência de sangramento anal em gotejamento. No exame físico, o cirurgião detectou\nabaulamento de mamilo hemorroidário posterior direito, proximal à linha pectínea, que exteriorizou\nà manobra de Valsalva e reduziu espontaneamente. Assinale a alternativa que classifica\ncorretamente a doença hemorroidária da paciente em questão.","options":{"A":"Hemorroidas internas de primeiro grau.","B":"Hemorroidas externas de terceiro grau.","C":"Hemorroidas internas de segundo grau.","D":"Hemorroidas internas de terceiro grau."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-311278","number":"311278","sourceNumber":"311278","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"É o tumor funcionante mais comum do pâncreas endócrino. São tipicamente pequenos\ne o marco diagnóstico é caracterizado pela\ntríade de Whipple.","options":{"A":"Insulinoma.","B":"Glucagonoma.","C":"Gastrinoma.","D":"ViPoma."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-311283","number":"311283","sourceNumber":"311283","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Gestante de 30 anos, atualmente com 32 semanas de gestação, queixa-se de\nsangramento nas fezes ao evacuar, em pequena\nquantidade, associado à nodulação em região\nanal. Ao exame físico, nota-se mamilo hemorroidário interno, que se exterioriza com manobras de\naumento da pressão intra-abdominal, porém retorna espontaneamente para o canal anal. A\nconduta mais adequada para o tratamento é:","options":{"A":"Excisão Cirúrgica.","B":"Tratamento Endoscópico.","C":"Ligadura Cirúrgica.","D":"Tratamento Clínico."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-287629","number":"287629","sourceNumber":"287629","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Na endoscopia digestiva alta indicada por hemorragia digestiva em que se encontra um\ncoto vascular visível, é classificada por Forrest em:","options":{"A":"IA.","B":"IB.","C":"IIA.","D":"IIB."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-262949","number":"262949","sourceNumber":"262949","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem de 32 anos de idade, obeso, procura atendimento médico de urgência devido a\ndor anal de quatro dias de evolução. Afirma que procurou atendimento por ter ficado preocupado\ncom a presença de secreção purulenta que se desenvolveu nas últimas horas. Qual é a hipótese\nmais provável de se confirmar após o exame objetivo realizado pelo cirurgião plantonista?","options":{"A":"Trombose hemorroidária.","B":"Fístula anal.","C":"Abscesso perianal.","D":"Fissura anal crônica."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-262959","number":"262959","sourceNumber":"262959","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A respeito das hemorragias digestivas baixas (HDB), assinale a alternativa correta.","options":{"A":"A colonoscopia é o método diagnóstico mais eficaz, com capacidade de identificação da causa\ndo sangramento em até 82% dos casos.","B":"Em caso de exteriorização de sangue vivo pelo reto, a endoscopia digestiva alta não é\nnecessária, já que se pode excluir completamente as causas altas de sangramento.","C":"Na retite actínica, a cirurgia é a primeira escolha, já que tem baixa morbidade e os tratamentos\nclínicos possuem altas taxas de insucesso.","D":"As baixas taxas de recidiva e mortalidade justificam a realização de colectomia parcial às cegas,\nem caso de sangramento ativo sem sítio\nidentificado."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-260607","number":"260607","sourceNumber":"260607","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Fistulas perianais são classificadas como sendo um pertuito entre a margem e canal\nanal. Podemos dizer que o trajeto mais comum encontrado nas fistulas perianais são as fistulas:","options":{"A":"Extraesfincterianas.","B":"Supraesfincterianas.","C":"Transesfincterianas.","D":"Interesfincterianas."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-254982","number":"254982","sourceNumber":"254982","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Nos pacientes idosos que apresentam hemorragia gastrointestinal e com endoscopia\ndigestiva alta e colonoscopia sem indicação\nda fonte do sangramento, a causa mais comum a ser\nsuspeitada é a presença de:","options":{"A":"Úlcera da doença de Crohn.","B":"Angiodisplasia jejunal.","C":"Divertículo de Meckel.","D":"Divertículo Zenker.","E":"Divertículo duodenal."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-254566","number":"254566","sourceNumber":"254566","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com 20 anos, sexo feminino, apresenta quadro recorrente de dor abdominal\nem cólica associada a distensão abdominal nos\núltimos dois anos. Interna para realização de\ncirurgia ginecológica (ressecção de cisto de ovário). Durante a laparotomia a estrutura abaixo é\nencontrada no íleo terminal (45 cm do ceco): Qual a melhor conduta:","options":{"A":"Ressecção apenas da lesão, sem ressecção do intestino ao qual está implantado.","B":"Ressecção da lesão conjuntamente com o segmento de intestino ao qual está implantado.","C":"Ressecção da lesão conjuntamente com o segmento de intestino ao qual está implantado,\nmantendo 10 cm de margem proximal e distal.","D":"Não há indicação para ressecção da lesão."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-217140","number":"217140","sourceNumber":"217140","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com hematêmese e melena se apresenta com FC = 110 bpm e pressão\narterial média = 65 mmHg. A prioridade no atendimento é:","options":{"A":"Endoscopia digestiva alta sem sedação para evitar hipotensão.","B":"Colonoscopia ou retossigmoidoscopia rígida.","C":"Infusão de cristaloide para estabilização hemodinâmica.","D":"Uso de vasopressor, preferencialmente noradrenalina."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-200452","number":"200452","sourceNumber":"200452","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinale a afirmativa em que a técnica de ligadura elástica das hemorroidas está\nindicada:","options":{"A":"Hemorroidas com pseudo estrangulamento.","B":"Hemorroidas sangrantes graus II e III.","C":"Hemorroidas prolapsadas grau IV.","D":"Hemorroidas trombosadas."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-210422","number":"210422","sourceNumber":"210422","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre Hemorragia Digestiva Baixa (HDB) é correto afirmar, EXCETO:","options":{"A":"A maioria das HDB representa emergência médica devido à instabilidade hemodinâmica que\ngrande parte dos pacientes manifesta.","B":"Por definição é aquela hemorragia em que a etiologia se situa abaixo do ângulo duodenojejunal","C":"O exame endoscópico pode ser feito na vigência do sangramento.","D":"Doença diverticular, tumores e angiodisplasia são as principais causas de HDB no idoso."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-200504","number":"200504","sourceNumber":"200504","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As variáveis abaixo predizem o risco de ressangramento na hemorragia digestiva alta\naguda, EXCETO:","options":{"A":"Idade superior a 70 anos de idade.","B":"Sangue vermelho vivo no toque retal.","C":"Pressão arterial sistólica inferior a 90mmHg.","D":"Hemoglobina inicial à admissão inferior ou igual a 10g/dL."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-201644","number":"201644","sourceNumber":"201644","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem de 58 anos, com história de etilismo importante, foi admitido no\npronto-socorro do Hospital da Polícia Militar,\napós 2 episódios de hematêmese volumosa. Ao\n\nexame físico, havia ginecomastia, eritema palmar e circulação colateral exuberante em abdome,\nsem ascite. Endoscopia digestiva alta\ndemonstrou variz esofagiana de grosso calibre, com ponto de\nruptura. Sobre esse caso, marque a alternativa CORRETA:","options":{"A":"A profilaxia secundária de hemorragia digestiva alta varicosa, iniciada no momento da alta\nhospitalar, deve ser realizada,\npreferencialmente, através de terapia combinada de betabloqueador\nseletivo e escleroterapia de varizes de esôfago.","B":"Vasoconstritores esplâncnicos devem ser imediatamente iniciados após admissão hospitalar,\nvisando à redução do risco de\nressangramento.","C":"O uso de antibiótico profilático deve ser recomendado e mantido a longo prazo para redução do\nrisco de translocação bacteriana e peritonite bacteriana espontânea.","D":"A endoscopia digestiva alta deve ser realizada, preferencialmente, nas primeiras 24 horas após\no sangramento, independentemente do estado\nhemodinâmico do paciente."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-201639","number":"201639","sourceNumber":"201639","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre as patologias orificiais, é CORRETO afirmar que:","options":{"A":"A doença hemorroidária é um distúrbio anal benigno e o diagnóstico pode ser feito com exame\nproctológico completo. O tratamento conservador é eficaz em muitos pacientes, podendo a\nhemorroidectomia ser indicada nos casos de falha terapêutica.","B":"Deve-se evitar hemorroidectomia com anestesia local, devido ao risco elevado de contaminação\ne gangrena de fournier.","C":"As fissuras anais são de diagnóstico clínico ? anamnese e exame proctológico em consultório. A\nhistória típica é de sangramento com ausência de dor às evacuações. A melhora dos hábitos\ndietéticos e evacuatórios faz parte das medidas clínicas indicadas.","D":"De acordo com as regras de Goodsall para as fístulas anais, um orifício externo posterior a uma\nlinha traçada transversalmente ao ânus, levará a um trajeto radial reto."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-201636","number":"201636","sourceNumber":"201636","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre a hemorragia digestiva, marque a alternativa CORRETA:","options":{"A":"Exames laboratoriais iniciais são indispensáveis nos casos de hemorragia digestiva, pois\nrefletem sempre o grau de hemorragia e irão definir a necessidade de reposição volêmica e\nhemotransfusão.","B":"Pacientes com hemorragia digestiva devem ser submetidos a exames laboratoriais como\nhemoglobina e hematócrito em avaliação laboratorial inicial.","C":"Na hemorragia digestiva, a endoscopia é essencial para o diagnóstico, devendo sempre ser\nrealizada nas primeiras 6 horas, havendo instabilidade hemodinâmica ou não.","D":"Na maioria dos pacientes com hemorragia digestiva, o sangramento não para espontaneamente\ne existe necessidade de terapêutica\nendoscópica."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-179229","number":"179229","sourceNumber":"179229","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A fístula é um trajeto com infecção crônica, ligando duas superfícies de revestimento\nepitelial. Na fístula anal, o orifício interno\nlocaliza-se, geralmente, na linha pectínea, e o orifício\nexterno, na pele perineal. Já o abscesso perianal é a mais frequente causa de intervenções\ncirúrgicas de urgência na área proctológica. Assinale a alternativa que apresenta\nCORRETAMENTE a relação dos abscessos perianais com as fístulas anais.","options":{"A":"Os abscessos perianais precedem a formação das fístulas, pois na sua maioria são decorrentes\nde\n\ninfecção criptoglandular não específica.","B":"Não há relação alguma, pois as fístulas anais são manifestações clínicas de outras doenças,\ncomo\n\ndoença de Crohn, tuberculose, neoplasia e doenças sexualmente transmissíveis.","C":"As fístulas perianais são decorrentes de trauma local secundário a diarreia ou fezes\nendurecidas,\n\ncausando fissuras que evoluem para fístulas.","D":"Os abscessos perianais têm íntima relação com as fístulas, por isso as suas classificações são\nas mesmas."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-179082","number":"179082","sourceNumber":"179082","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 32 anos, sexo masculino, com dor durante esforço evacuatório há cerca\nde 60 dias. Refere que está fazendo apenas\n\"banhos de assento\", sem melhora do quadro. Nega\ncirurgias prévias. Relata ter constipação intestinal. Sem outras queixas. À inspeção local é\nobservada lesão linear com cerca de 3 mm, rasa, com bordas elevadas e fibróticas, dolorosa ao\ntoque, em região médio-posterior do ânus. Qual o tratamento mais indicado para este caso?","options":{"A":"Sutura da lesão com fio de Nylon 3-0","B":"Esfincterotomia lateral interna e curetagem da lesão","C":"Isossorbida tópica por 4 semanas","D":"Hemorroidectomia aberta (Técnica de Milligan -Morgan)"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-178042","number":"178042","sourceNumber":"178042","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre hemorragia digestiva alta de origem ulcerosa, marque a alternativa ERRADA:","options":{"A":"A realização precoce de EDA com algum método terapêutico que vise a hemostasia diminui o\níndice de ressangramento, a chance de cirurgia de emergência e a mortalidade.","B":"A classificação de Forrest é a mais utilizada e tem como objetivo maior prognosticar a chance de\nressangramento.","C":"A úlcera duodenal classificada como Forrest II ? B tem alta chance de necessitar de cirurgia de\nurgência para conseguir hemostasia.","D":"As úlceras duodenais de parede posterior sangram mais do que parede anterior."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-179139","number":"179139","sourceNumber":"179139","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma mulher de 62 anos foi admitida em Pronto Socorro, trazida por familiares, com\nfranca enterorragia e certa palidez cutaneomucosa.\nNegava dor abdominal. Fazia uso de aspirina e\nclopidogrel por ser portadora de Cardiopatia Isquêmica, já em seguimento com especialista. Dados\nvitais: Sat. O? = 96% com cateter de O? a 2L/min. FR: 18 irpm. FC: 96 bpm. PA: 120x70 mmHg.\n\nQual é o primeiro exame complementar necessário para a investigação etiológica do quadro?","options":{"A":"Anteriografia seletiva da artéria mesentérica superior","B":"Tomografia computadorizada de abdome contrastada","C":"Colonoscopia","D":"Endoscopia digestiva alta"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-181998","number":"181998","sourceNumber":"181998","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A respeito da fisiopatologia da doença hemorroidária marque a alternativa correta:","options":{"A":"Plexo hemorroidário interno inclui ramos terminais da artéria retal superior (anterior direito,\nposterior direito, lateral esquerdo), drena para a\ncirculação sistêmica (veia cava inferior) por meio\ndas veias retais inferiores; situa-se acima da linha pectínea.","B":"Plexo hemorroidário externo inclui ramos terminais da artéria retal inferior, drena para a veia\nporta por meio da veia retal superior, tributária da mesentérica inferior, tributárias das veias\npudenda e ilíaca interna; situa-se abaixo da linha pectínea.","C":"Não existe lugar para tratamento não operatório de doença hemorroidária.","D":"O pseudo estrangulamento hemorroidário é uma complicação de hemorróidas internas de 3o. e\n4o. graus e decorre de espasmo esfincteriano que comprime os mamilos, impedindo o retorno\nvenoso e levando a anóxia, infecção e gangrena."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-181032","number":"181032","sourceNumber":"181032","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre a hemorragia digestiva, marque a alternativa CORRETA:","options":{"A":"As lesões agudas de mucosa gástrica são identificadas predominantemente no antro gástrico. O\nsangramento pode ser difuso e maciço, não permitindo a terapia endoscópica.","B":"A probabilidade de novo episódio de sangramento em paciente portador de úlcera gástrica pode\nser estimada com base na aparência endoscópica,\ntendo um vaso visível visibilizado à endoscopia\num baixo risco de nova hemorragia.","C":"A terapia endoscópica pode ser utilizada em pacientes Forrest I, Forrest IIa e Forrest IIb, não\nhavendo necessidade de manutenção do paciente\ninternado após o procedimento.","D":"Em relação à hemorragia digestiva baixa, podem ser identificadas com acurácia as lesões\nmucosas responsáveis pela hemorragia aguda do cólon\npela colonoscopia, sendo a diverticulose e\na angiodisplasia as etiologias mais comuns."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-181036","number":"181036","sourceNumber":"181036","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre os abscessos perianais, é CORRETO afirmar:","options":{"A":"Decorrem de oclusão do orifício apopilossebáceo por queratina, com infecção secundaria das\nglândulas sudoríparas.","B":"A drenagem deve ser protelada até a presença de flutuação, devendo-se iniciar\nantibioticoterapia o maior precocemente possível.","C":"Doenças inflamatórias intestinais, principalmente a retocolite ulcerativa, podem cursar com a\nformação de abscessos anorretais.","D":"A disseminação do processo inflamatório e infeccioso pode ocorrer para a região perineal, bolsa\nescrotal ou grandes lábios vaginais e para extensões variáveis da parede abdominal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-184620","number":"184620","sourceNumber":"184620","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Qual a localização preferencial da fissura anal no sexo masculino:","options":{"A":"Linha média posterior do canal anal.","B":"Parede lateral do canal anal.","C":"Linha média anterior do canal anal.","D":"Borda lateral do reto."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-184623","number":"184623","sourceNumber":"184623","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A melhor conduta frente a um paciente com abscesso perianal:","options":{"A":"Esfriar o processo com compressas quentes e antibióticos","B":"Proceder a incisão e drenagem imediata do abscesso","C":"Esperar que ocorra a flutuação para melhor definição do local do abscesso","D":"Nunca incisar junto ao ânus pelo perigo de contaminação que possa agravar o processo\ninflamatório"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-157988","number":"157988","sourceNumber":"157988","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A complicação mais temida da ruptura de esôfago é:","options":{"A":"Pneumotórax.","B":"Mediastinite.","C":"Hematêmese.","D":"Estenose cicatricial do esôfago."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-157800","number":"157800","sourceNumber":"157800","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Nádia, 83 anos, é internada em unidade de terapia intensiva por apresentar quadro de\ninsuficiência coronária. Tem antecedentes de obstipação crônica em uso crônico de laxantes. Há\num ano, hemorragia digestiva baixa, sendo que a colonoscopia evidenciou moléstia diverticular dos\ncólons. No momento, já apresentou oito episódios de evacuações sanguinolentas, havendo\ninstabilidade hemodinâmica, com PA = 80 x 50 mmHg e FC = 120 bpm. O exame enviado ao\nlaboratório mostrou Hb = 6,8 g, sendo que no dia anterior era de 12,3 g. O plantonista da UTI já\nsolicitou endoscopia digestiva alta, que evidenciou gastrite leve de antro sem sinais de\nsangramento. Qual seria a conduta mais indicada, além da reposição de sangue?","options":{"A":"Colonoscopia.","B":"Hemicolectomia esquerda.","C":"Hemicolectomia direita.","D":"Colectomia subtotal.","E":"Colectomia total."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-158202","number":"158202","sourceNumber":"158202","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Márcio, 65 anos, apresenta episódio de Hemorragia Digestiva Baixa (HDB) com\nrepercussão hemodinâmica que foi controlada com tratamento clínico, não necessitando de\ntransfusão sanguínea. A causa mais comum de HDB para esse paciente é a","options":{"A":"Doença hemorroidária.","B":"Angiodisplasias.","C":"Neoplasia do cólon","D":"Doença diverticular."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-153073","number":"153073","sourceNumber":"153073","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com doença hemorroidária apresentando prolapso que exige redução manual.\nEsta fase da doença está classificada no\ngrau:","options":{"A":"I.","B":"II.","C":"III.","D":"IV.","E":"V."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-157770","number":"157770","sourceNumber":"157770","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Otávio, 26 anos, procura serviço médico com queixa de dor anal há dois dias e\naparecimento de abaulamento local. Refere já ter apresentado quadro semelhante há um ano. Ao\nexame, diagnostica-se abcesso ano retal com abaulamento na região perianal endurecido e\nhiperemiada. Qual a melhor conduta para esta caso?","options":{"A":"Esfriar o processo com compressas quantes e antibióticos e posterior drenagem.","B":"Proceder a incisão e drenagem imediata de abscesso.","C":"Esperar que ocorra a flutuação para melhor difinição do local do abscesso.","D":"Não incisar junto ao ânus pelo perigo de contaminação que possa agravar a processo\ninflamatório.","E":"Nos abscessos interesfincterianos altos, deve-se proteger a área com uma derivação intestinal\ntipo colostomia."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-155211","number":"155211","sourceNumber":"155211","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Quanto aos divertículos duodenais, é INCORRETO afirmar que:","options":{"A":"O divertículo duodenal que compromete a papila duodenal é raro e de descoberta fortuita\ndurante exames endoscópicos com outras indicações.","B":"A localização duodenal é a segunda em ocorrência dos divertículos, só suplantada pelo cólon.","C":"No duodeno, o local mais comum é a segunda porção.","D":"A taxa de mortalidade das diverticulectomias duodenais permanece alta atingindo até 30% em\nalgumas series."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-160260","number":"160260","sourceNumber":"160260","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente jovem do sexo masculino chega ao hospital com um quadro de\nhemorragia digestiva alta, vomitando sangue\nvivo, em choque hipovolêmico. Relata que não faz\nuso de anti-inflamatórios, nega dor epigástrica, e relata que bebe socialmente uma ou duas latinhas\nde cerveja em finais de semana. Depois de fazer dois acessos venosos calibrosos e tipar o sangue,\nvocê liga para o endoscopista que lhe pergunta: qual a causa MAIS PROVÁVEL para esta\nhemorragia?","options":{"A":"varizes de esôfago.","B":"úlcera gástrica.","C":"úlcera duodenal.","D":"síndrome de Mallory-Weiss."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-135604","number":"135604","sourceNumber":"135604","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente procura proctologista com queixa de sangramento anal, mas não há dor\nperianal. Com apenas estes sinais e sintomas, qual doença orificial é mais provável?","options":{"A":"Abscesso perianal.","B":"Fissura anal.","C":"Cisto pilonidal sacrococcígeo.","D":"Doença hemorroidária."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-131723","number":"131723","sourceNumber":"131723","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Matheus, 85 anos, chega ao pronto-socorro com hemorragia digestiva baixa de grande\nvolume e instabilidade hemodinâmica, sem resposta adequada às medidas de reposição. Qual a\nconduta CORRETA?","options":{"A":"Colonoscopia.","B":"Arteriografia.","C":"Colectomia total de urgência.","D":"Colectomia parcial (a ser avaliado no ato da cirurgia) de urgência.","E":"Cintilografia."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-137517","number":"137517","sourceNumber":"137517","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à Hemorragia Digestiva Baixa (HDB), qual das opções apresenta uma\nafirmação incorreta?","options":{"A":"As causas mais comuns de HDB são doença diverticular, angiodisplasias, doença intestinal\ninflamatória, neoplasias e doença hemorroidária.","B":"O esforço de localizar a fonte do sangramento é útil porque a colectomia ?cega? é\nacompanhada de uma taxa de mortalidade significativa.","C":"Paciente com história de vários episódios de HDB secundários à doença diverticular tem\nindicação de ressecção colônica eletiva.","D":"Paciente com sangramento maciço deve sempre ser submetido anteriormente à arteriografia e\nposteriormente a colonoscopia."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-107944","number":"107944","sourceNumber":"107944","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 35 anos, com etilista, com hematêmese e síncope, procura PS às 23:00.\nApresenta FC = 100 bpm, PA = 100 x 60 mmHg,\naspirado gástrico de cor vermelha.Tem múltiplos\nspiders, abdome distendido e macicez móvel. Recebeu 2000 ml de soro fisiológico e octreotida\n(infusão continua está em curso). Seus sinais vitais estabilizaram. Qual é a conduta ideal para este\npaciente?","options":{"A":"Realizar endoscopia imediatamente.","B":"Realizar endoscopia pela manhã pelo risco de ressangramento.","C":"Preparar o paciente para cirurgia de derivação.","D":"Colocação de derivação portossistêmica intra-hepática transjugular (TIPS).","E":"Laparotomia exploradora."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-103082","number":"103082","sourceNumber":"103082","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente com idade acima de 60 anos é levado a um Pronto Atendimento hospitalar\ndevido a quadro de franca hemorragia\ndigestiva baixa. Considerando o caso descrito, assinale a\nalternativa que apresenta a PRIMEIRA suspeita diagnóstica baseada em frequência.","options":{"A":"Colite isquêmica.","B":"Proctite actínica.","C":"Doença inflamatória intestinal.","D":"Doença diverticular."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-103047","number":"103047","sourceNumber":"103047","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Quanto às opções terapêuticas endoscópicas da Hemorragia Digestiva Baixa ? HDB ?,\nassinale a alternativa INCORRETA.","options":{"A":"Hemoclips, ligaduras elásticas e ligaduras com alças são métodos mecânicos de abordagem\nendoscópica de HDB.","B":"Pinças diatérmicas e plasma de argônio são métodos térmicos de abordagem endoscópica de\nHDB.","C":"Adrenalina, álcool e etanolamina são métodos químicos de abordagem endoscópica de HDB.","D":"Eletrocoagulação monopolar, bipolar e laser não devem ser usados na abordagem endoscópica\nda HDB."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-105827","number":"105827","sourceNumber":"105827","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Tiago, 16 anos, procurou o serviço de urgência referindo eliminação de sangue vivo\npelo reto em três ocasiões nas últimas 24h.\nEle está em bom estado geral e não usa medicações.\nRefere episódio semelhante há um ano, quando realizou endoscopia digestiva alta e colonoscopia\nnormais, sendo rotulado como portador de hemorroidas. Seu exame físico geral é normal, abdome\nnormotenso, indolor e sem massas palpáveis. Ele não tem hemorroidas e o sangramento continua.\nSeu hematócrito é 32 mg/dl. Diante deste caso, qual deve ser a causa mais provável do seu\nsangramento?","options":{"A":"Divertículo de Meckel.","B":"Angiodisplasia.","C":"Pólipo juvenil.","D":"Doença de Crohn.","E":"Colite ulcerativa."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-109891","number":"109891","sourceNumber":"109891","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A hemorragia digestiva ocasionada pela lesão de Dieulafoy é:","options":{"A":"O sangramento proveniente de lacerações da mucosa na junção do estômago e esôfago,\nnormalmente causada por esforço ao tossir ou vomitar.","B":"Manifestada classicamente como sangramento oculto, epigastralgia e anemia crônica.","C":"O sangramento de uma lesão gástrica causada por uma artéria tortuosa, anormalmente grande\n(1 a 3 mm), que faz um trajeto através da\nsubmucosa.","D":"O sangramento decorrente do GIST gástrico."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-87938","number":"87938","sourceNumber":"87938","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 23 anos comparece ao serviço de pronto atendimento com quadro de\nsangramento anal. Quando arguido, o paciente relata que não há dor local, nem dor abdominal, e\nque o sangue tem aspecto vermelho-rutilante, não é em grande quantidade. Não há antecedentes\nmórbidos. A hipótese diagnóstica mais provável é:","options":{"A":"Doença hemorroidária.","B":"Fístula perianal.","C":"Fissura anal.","D":"Abscesso perianal."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-86035","number":"86035","sourceNumber":"86035","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"As varizes gástricas, geralmente decorrentes de hipertensão portal, são amplamente\nclassificadas em gastroesofágicas e gástricas isoladas. As varizes gástricas isoladas são, por sua\nvez, subclassificadas. Aquelas situadas no fundo gástrico são do tipo:","options":{"A":"I","B":"II","C":"III","D":"IV"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-58939","number":"58939","sourceNumber":"58939","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Assinalar a afirmativa CORRETA em relação às seguintes urgências intestinais:","options":{"A":"A colorrafia é o melhor procedimento cirúrgico em casos de perfuração intestinal com peritonite\nfecal.","B":"O trânsito digestivo é ideal na propedêutica de hemorragias intestinais.","C":"A radiografia simples de abdome não encontra mais utilidade frente a um quadro de suspeita\nde obstrução intestinal.","D":"A tomografia abdominal e pélvica é o exame padrão-ouro na suspeita de diverticulite de\nsigmoide."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-58954","number":"58954","sourceNumber":"58954","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 50 anos, sexo masculino, deu entrada no pronto-socorro por\nhematêmese volumosa (dez episódios nas últimas\ntrês horas). Teve o diagnóstico de cirrose\nalcoólica Child B há um ano e meio e, desde então, mantém-se abstêmio. Trouxe sua prescrição de\npropranolol 20 mg BID, espironolactona 100 mg MID e furosemida 40 mg MID. O exame clínico\nrevelou: PA: 70 x 56 mmHg; FC: 104 bpm; FR: 40 irpm; SpO2: 88%. Paciente confuso e agitado,\nhipocorado, com extremidades frias, edema periférico e ascite volumosa. Sobre o manejo desse\ncaso, marque a alternativa INCORRETA:","options":{"A":"A terapia endoscópica de urgência está contraindicada no momento pela instabilidade\nhemodinâmica do paciente.","B":"A terlipressina deve ser usada de forma intermitente enquanto se aguarda a endoscopia\ndigestiva alta.","C":"Há indicação de profilaxia para peritonite bacteriana espontânea com quinolonas ou\ncefalosporinas de terceira geração.","D":"A terapia endoscópica mais eficaz para o tratamento da hemorragia varicosa é a\nescleroterapia."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-69337","number":"69337","sourceNumber":"69337","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"O principal sinal clínico da doença hemorroidária é:","options":{"A":"sangramento anal.","B":"dor perianal.","C":"exteriorização de muco e pus.","D":"flatulência."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-62525","number":"62525","sourceNumber":"62525","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sr. Constância, 72 anos, portadora de insuficiência coronariana, veio encaminhada de\noutro serviço com quadro de hematoquezia franca há 1 (um) dia. Traz consigo exame de\nendoscopia digestiva alta realizada no dia anterior cujo achado foi de uma gastrite antral leve sem\nsinais de sangramento recente. O acompanhante refere que a paciente recebeu ontem, 3 (três)\nunidades de concentrado de hemácias. Ela está hipotensa e taquicárdica. Após medidas iniciais de\nreanimação a paciente fica estável e é encaminhada para exame de colonoscopia que não\nconsegue identificar o sítio de sangramento devido ao preparo de cólon inadequado. Com relação\nao caso clínico, assinale a alternativa CORRETA:","options":{"A":"Uma angiografia normal durante o sangramento ativo exclui a angiodisplasia como causa da\nhemorragia","B":"A angiodisplasia é a principal causa de sangramento no idoso e quando não se identifica o local\nde sangramento, a colectomia direita está bem indicada","C":"Na doença diverticular, o sigmoide é o local de maior incidência de hemorragia digestiva baixa","D":"A doença diverticular hipotônica e a retocolite ulcerativa são as causas de maior incidência de\nhemorragia digestiva baixa.","E":"A colonoscopia identifica o local de sangramento em até 70% dos casos de hemorragia\nmoderada"},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-44295","number":"44295","sourceNumber":"44295","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação às hemorragias digestivas, marque a alternativa CORRETA:","options":{"A":"Melena indica que o sangue está presente no trato gastrointestinal por pelo menos 14 horas, e\ntanto tempo quanto 3 a 5 dias.","B":"Há nítida vantagem da escleroterapia em relação à ligadura elástica para o tratamento\nendoscópico dos sangramentos por varizes de esôfago.","C":"A hematoquezia, quando sinal de uma hemorragia alta, geralmente aparece como quadro\ncrônico e oligossintomático.","D":"As gastropatias hemorrágicas e erosivas (frequentemente chamadas de gastrites)\n\ncaracterizam-se por lesões de mucosa, e quando sangram, frequentemente levam às repercursões\ndo estado circulatório do paciente (como\ntaquicardia e hipotensão arterial sistêmica)."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-51449","number":"51449","sourceNumber":"51449","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A respeito da doença hemorroidária, qual afirmação incorreta:","options":{"A":"os sinais mais comuns são sangramento vermelho rutilante, em volume variado, durante as\nevacuações; e\n\nprolapso de mamilos","B":"há relação entre a intensidade do sangramento e o tamanho dos mamilos hemorroidários","C":"A maioria dos pacientes não tem dor, apenas sentem-se incomodados com o prolapso","D":"O diagnóstico se faz pela história clínica e exame proctológico"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-33468","number":"33468","sourceNumber":"33468","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Você está de plantão no CTI e admite um paciente cirrótico Child C com hemorragia\ndigestiva alta, em choque hipovolêmico e com rebaixamento do nível de consciência. Qual das\nmedidas abaixo não deve ser realizada?","options":{"A":"Intubação orotraqueal e reposição volêmica vigorosa.","B":"Iniciar terlipressina ou octreotide.","C":"Iniciar antibioticoprofilaxia para peritonite bacteriana espontânea.","D":"Iniciar propranolol para reduzir a pressão nas varizes de esôfago."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-9776","number":"9776","sourceNumber":"9776","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação à fissura anal, assinale a alternativa correta.","options":{"A":"É causa mais frequente de hematoquezia nas crianças.","B":"Localiza-se preferencialmente na linha média anterior.","C":"O tratamento clínico das fissuras com cremes a base de nitroglicerina ou derivados produzem\ntaxas de curas inferiores a 20% e devem ser\ndesestimulados.","D":"O tratamento cirúrgico é reservado aos casos refratários ao tratamento clínico e consiste na\nesfincterotomia interna parcial posterior."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-9662","number":"9662","sourceNumber":"9662","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma senhora de 45 anos de idade, em uso crônico de anti-inflamatórios não esteroides\n(AINE), apresenta-se para atendimento emergencial\ncom quadro de hematêmese. Após\nestabilização hemodinâmica, é encaminhada para endoscopia digestiva, que revela úlcera\nduodenal, sem sangramento atual, com coágulo firmemente aderido na base. Qual das condutas\nabaixo não diminui a ocorrência de ressangramento?","options":{"A":"Inibidores de bomba de prótons.","B":"Injeção endoscópica de álcool absoluto ou adrenalina.","C":"Antagonistas H2.","D":"Suspensão dos AINE."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-347420","number":"347420","sourceNumber":"347420","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem com 45 anos, em uso de anti-inflamatório não hormonal há 20 dias devido a\ntendinite de ombro esquerdo, chega ao pronto-socorro com quadro de melena há 24 horas, de\nmoderado volume, associado a epigastralgia intensa e mal-estar. Nega doenças preexistentes. Ao\nexame físico, apresenta-se em bom estado geral, consciente, orientado, com mucosas anictéricas\nhidratadas e hipocoradas (+1/+4), fáceis atípica, tempo de enchimento capilar de 2 segundos,\nfrequência cardíaca de 90 batimentos por minuto, pressão arterial de 120 x 80 mmHg, abdome\nflácido, com ruídos hidroaéreos aumentados, dor à palpação de epigástrio. Os resultados de seus\nexames complementares apresentaram: hemácias: 4.500.000; hemoglobina: 13%; hematócrito:\n39%; leucócitos: 4.400; plaquetas: 220.000; INR: 1,2 (valor de referência [VR]: 1-1,4); ureia: 45\n\nmg/dl (VR: 16-40), creatina: 1,2 mg/dL (VR 0,7-1,3); Potássio: 5,4 mEq/L (VR: 3,5-5,5); tipagem\nsanguínea: A+, endoscopia digestiva alta com erosões agudas de mucosa gástrica em região de\nantro e bulbo. A conduta inicial mais adequada ao caso seria dieta zero e","options":{"A":"transfusão de plaquetas e de plasma fresco congelado.","B":"transfusão de concentrado de hemácias em até duas horas.","C":"reposição volêmica com cristaloides e uso de inibidores da bomba protônica (IBP).","D":"reposição volêmica com cristaloides e transfusão de concentrado de hemácias e plaquetas."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-347426","number":"347426","sourceNumber":"347426","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um paciente com 40 anos, diabético e obeso, comparece ao pronto-socorro, com\nevolução de 24 horas de dor em nádega\ndireita e febre. O exame físico indica nádega direita sem\nsinais de flogose, com dor à palpitação perianal. Ao exame de toque retal, notam-se fezes e\ndiscreta elevação da mucosa, a cerca de 6 cm da margem anal. Nesse caso, devem ser prescritos\nao paciente o uso de","options":{"A":"anti-inflamatório e a realização de anuscopia.","B":"antibiótico e o retorno em 7 dias para reavaliação.","C":"antibiótico e a realização de tratamento cirúrgico.","D":"anti-inflamatório e a realização de banho de assento."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-349092","number":"349092","sourceNumber":"349092","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma mulher de 26 anos é atendida em unidade básica de saúde relatando que, há 15\ndias, sente dor significativa ao evacuar e possui pequeno sangramento anal vivo, notado durante a\nhigiene local. Ela afirma que a dor persiste com menor intensidade por alguns minutos após a\neliminação das fezes e que o sangramento se repete em cada evacuação. A paciente refere\nconstipação habitual, com eliminação de fezes ressecadas em média 3 vezes por semana. Com\nbase na história clínica dessa paciente, ao realizar o exame físico, o médico provavelmente\nencontrará","options":{"A":"fissura anal na linha média posterior com fundo raso.","B":"veias do plexo hemorroidário com sinais de sangramento.","C":"fístula anorretal com sinais de sangramento pelo orifício cutâneo.","D":"abscesso perianal com sinais flogísticos e drenagem de secreção local."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-318539","number":"318539","sourceNumber":"318539","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem com 33 anos de idade chega para atendimento no Pronto-Socorro de\nhospital de nível secundário. Relata vômitos\ncom sangue assim como fezes escurecidas e fétidas\nhá 1 dia. Ao exame físico, encontra-se descorado, taquicardíaco, hipotenso. Realizou endoscopia\ndigestiva alta que evidenciou úlcera péptica pre-pilórica (tipo III de Johnson), com sangramento em\njato proveniente da lesão (Classificação la de Forrest), sendo realizada hemostasia da ulceração\ncom solução de adrenalina. Doze horas após a terapêutica endoscópica, apresentou novamente\nvômitos com sangue em grande quantidade, frequência cardíaca de 110 batimentos por minuto e\npressão arterial de 80 x 40 mmHg. Com base na história clínica do paciente e nos dados do exame\nfísico, o tratamento adequado deve ser","options":{"A":"reposição volêmica e nova endoscopia para terapêutica endoscópica.","B":"terapia intensiva, inibidor de bomba de prótons e tratamento operatório.","C":"transferência para angiografia terapêutica e embolização em hospital terciário.","D":"terapia intensiva e dobrar a dose de inibidor de bomba de prótons endovenoso."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-319905","number":"319905","sourceNumber":"319905","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem de 45 anos, sem comorbidades, procurou o pronto-socorro por apresentar dor\nem região anal havia 5 dias, acompanhada por prostração e calafrios. No exame físico,\nencontrava-se em regular estado geral, consciente, contactuante, corado, hidratado, subfebril\n\n(temperatura axilar de 37,5 °C), com frequência cardíaca de 105 batimentos por minuto, frequência\nrespiratória de 20 incursões respiratórias por minuto, pressão arterial de 120 x 80 mmHg. Inspeção\nda região perianal evidenciou abaulamento à direita, sem ponto de flutuação, aumento de\ntemperatura e vermelhidão. Toque retal com dor à palpação em quadrante posterior direito. Com\nbase no quadro apresentado, qual é a conduta mais adequada?","options":{"A":"Antibioticoterapia venosa.","B":"Drenagem cirúrgica imediata.","C":"Termoterapia local e observação.","D":"Tomografia computadorizada da pelve."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-240452","number":"240452","sourceNumber":"240452","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente, 60 anos, fumante, deu entrada no pronto-socorro com dor epigástrica de forte\nintensidade com história de melanoma. Fez endoscopia digestiva alta com fundo de Forrest tipo ?\n\nIB. Esse quadro corresponde a:","options":{"A":"Sangramento em jato.","B":"Sangramento em porejamento (babando).","C":"Sem sinal de sangramento.","D":"Colo vascular visível.","E":"Fundo hemático."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-352621","number":"352621","sourceNumber":"352621","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A Hemorragia Digestiva Alta pode ser definida como sangramentos digestivos de\npontos oriundos até o ligamento de Treitz como\nreferência. Mais comum acima dos 60 anos, com\nmortalidade em torno de 10% na maioria dos pacientes, exceto quando associado à comorbidades.\nConduzir os riscos desses pacientes de forma estratificada é recomendável, portanto, de acordo\ncom Escore de Rockall, um paciente de 70 anos com história de sangramento gástrico por lesão\nneoplásica ulcerada confirmada por endoscopia digestiva, apresentando-se taquicárdico (FC\n110bat/mim), com PAS >100 mmhg, apresenta risco de ressangramento e mortalidade\nrespectivamente de:","options":{"A":"Risco médio, ressangramento em torno de 14% com mortalidade de 5%","B":"Risco alto, ressangramento em torno de 52% e mortalidade de 30%","C":"Risco baixo, ressangramento inferior a 5% e mortalidade menor que 1%","D":"Risco e mortalidade não podem ser estimados por esse Escore, pois ess é específico para\nmonitorização de HDB (Hemorragia digestiva Baixa)."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-369429","number":"369429","sourceNumber":"369429","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Mulher de 72 anos foi encontrada no chão do banheiro, após segundo episódio de\nhematoquezia no mesmo dia. Como antecedente pessoal relevante, paciente é tabagista\ninveterada há 40 anos. Após medidas iniciais para expansão volêmica, controle dos sinais vitais e\ncoleta de exames laboratoriais, a melhor conduta é:","options":{"A":"endoscopia digestiva alta","B":"colonoscopia","C":"aspiração nasogástrica","D":"arteriografia seletiva","E":"cintilografia"},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-369367","number":"369367","sourceNumber":"369367","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente foi examinado e apresenta mamilos hemorroidários com redução espontânea.\nAssinale a alternativa que contém a\ncorreta classificação da doença hemorroidária apresentada por\neste paciente.","options":{"A":"Grau I","B":"Grau II","C":"Grau III","D":"Grau IV","E":"Grau V"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-326284","number":"326284","sourceNumber":"326284","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 48 anos sabidamente portador de hipertensão portal em investigação\netiológica, contudo já apresentando varizes\nesofágicas de médio e grosso calibres, ao ser atendido\nno PS por ter apresentado sangramento importante (3 episódios de hematêmese nas últimas 4h).\nDentre as medidas gerais de tratamento para estabilização clínica listadas abaixo, podemos\nconsiderar adequada:","options":{"A":"2 L de ringer lactato por acesso venoso calibrosso, para manter PAM em torno de 80mmhg.","B":"Terlipressina 2mg em bolus e 1mg 4/4h por 3 a 5 dias.","C":"Evitar uso de IBP nas primeiras 24h.","D":"Evitar IOT por risco de vômitos com aumento do sangramento."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-326285","number":"326285","sourceNumber":"326285","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Thomson, em 1975, descreveu as hemorroidas como sendo coxins vasculares\ncompostos por arteríolas, sinusoides e\nvênulas sustentados por tecido fibromuscular. Em torno de\n5% da população geral apresenta sintomas relacionados à doença hemorroidária, sendo que na\nmaioria das vezes, o tratamento conservador com medidas locais e dietéticas é preferível. Contudo\nas indicações de tratamento cirúrgico na doença hemorroidária encontram-se mais adequadamente\nrepresentada na alternativa:","options":{"A":"Nas tromboses hemorroidárias agudas.","B":"Nas protusões hemorroidários Grau II.","C":"Na classificação Graus III e IV de doença interna, assim como na doença externa severa\nsintomática.","D":"Após o primeiro episódio de sangramento, independentemente de ser interna ou externa."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-331178","number":"331178","sourceNumber":"331178","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre doença hemorroidária, é correto afirmar:","options":{"A":"Doença hemorroidária grau III corresponde a prolapso e retorno espontâneo ao canal anal.","B":"Não se utiliza técnica fechada em cirurgia de ressecção hemorroidária.","C":"Ligadura elástica pode ser utilizada em doença grau II com prolapso ou sangramento.","D":"A hemorroidectomia por grampeamento baseia-se na ressecção da mucosa redundante,\ndiminuição do fluxo sanguíneo e fixação da mucosa na sua posição de origem.","E":"A queixa mais comum do paciente com essa patologia é dor."},"answer":"","answerPending":true,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"missing","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-343714","number":"343714","sourceNumber":"343714","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente submetido a ressonância magnética foi diagnosticado com uma fístula anal\ntransesficteriana. A classificação de Parks correta do achado, é:","options":{"A":"Parks tipo 1","B":"Parks tipo 2","C":"Parks tipo 3","D":"Parks tipo 4","E":"Parks tipo 5"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-320147","number":"320147","sourceNumber":"320147","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente 32 anos com quadro de dor escrotal e perineal que se iniciou há 4 dias\nacompanhado de febre de 39oC. Foi ao pronto socorro em 3 ocasiões e realizou exames\nlaboratoriais que mostraram leucócitos aumentados (20.000 leucócitos sem desvio) e discreta\nelevação da creatinina (1,5 mg/dl). Foi solicitado um USG que mostrou coleção de 30 ml em linha\nmédia do períneo (provável abscesso). Foi iniciado antibioticoterapia com ciprofloxacina via oral. O\npaciente chega em seu consultório com queixa de muita dor, não conseguindo sentar-se. No\nexame físico há abaulamento perineal, muito doloroso ao toque e turgido. Os testículos estão\nnormais e há pequena hemorroida e fissura anal. A melhor conduta a ser tomada, neste caso, é:","options":{"A":"trocar o antibiótico para ampliar o espectro de ação, associar à analgésicos opioides e reavaliar\nem 48 horas.","B":"internar o paciente, iniciar o protocolo de sepse e solicitar RNM da pelve com contraste para\ndefinir a necessidade de cirurgia.","C":"realizar retossigmoidoscopia para afastar o diagnóstico de provável fístula anal.","D":"internar o paciente para realizar drenagem do abscesso e desbridamento de tecidos necróticos e\nescalonar antibioticoterapia.","E":"manter antibioticoterapia, iniciar banho de assento com água morna e pomadas analgésicas e\ncicatrizantes devido à fissura anal."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-277708","number":"277708","sourceNumber":"277708","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Paciente de 54 anos, masculino, com relato de constipação crônica tratada de forma\nirregular, chega ao consultório com queixas\nde sangramento (pouca quantidade), dor importante à\nevacuação e medo ao evacuar por causa da dor. Durante o exame físico, observou-se presença de\nfissura anal posterior. A tríade que caracteriza essa fissura e o tratamento cirúrgico atual são,\nrespectivamente,","options":{"A":"dor, orifício externo e leito da fissura; esfincterotomia no leito da fissura.","B":"plicoma sentinela, papila hipertrófica e leito da fissura; esfincterotomia lateral.","C":"orifício interno, trajeto e orifício externo; fissurectomia.","D":"sangramento, dor e leito da fissura; avanço de retalho V-Y","E":"dor, esfíncter externo hipertônico e secreção; cauterização da fissura."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-269771","number":"269771","sourceNumber":"269771","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A investigação de sangramento em trato digestivo baixo (HDB) deve incluir a\nlocalização e a causa do sangramento. Diante\nde um caso HDB analise as afirmativas abaixo: I.\nAnuscopia: deve sempre ser realizada. Pode ser efetuada adequadamente sem preparo. II.\nColonoscopia: representa o procedimento diagnóstico de escolha, desde que o ritmo do\nsangramento permita a realização de preparo intestinal, devido à sua alta acurácia no diagnóstico\ndo sangramento de origem no cólon, bem como à possibilidade terapêutica. III. Arteriografia:\nindicada preferencialmente quando o sangramento é importante o suficiente para contraindicar o\npreparo intestinal para colonoscopia ou após achado positivo à cintilografia. A alternativa que\ncontém todas as afirmativas corretas é:","options":{"A":"I e II","B":"I e III","C":"II e III","D":"III","E":"I, II e III"},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-269772","number":"269772","sourceNumber":"269772","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A Hemorragia Digestiva Aguda, evidenciada clinicamente pela exteriorização de\nhematêmese, melena ou enterorragia, é uma causa frequente de hospitalização de urgência.\nHabitualmente, a hemorragia digestiva alta (HDA) se expressa por hematêmese e/ou melena,\nenquanto a enterorragia é a principal manifestação da hemorragia digestiva baixa (HDB). Acerca\ndas hemorragias digestivas, assinale a alternativa correta.","options":{"A":"O exame endoscópico é o método mais sensível e específico no diagnóstico da HDA e deve ser\nrealizado, preferencialmente, nas primeiras 24 horas de internação, já com o paciente\nhemodinamicamente estável.","B":"As HDAs de etiologia não varicosa são causadas, principalmente, por doença do refluxo,\nesofagite eosinofílica e tumores gastrointestinais (gastrinomas).","C":"A doença diverticular, apesar de predominar no cólon direito, tem a maioria dos sangramentos\noriundos de divertículos situados no cólon\nesquerdo. A hemorragia é súbita, discreta e\nhabitualmente autolimitada, raramente é profusa com instabilidade hemodinâmica.","D":"A etiologia da HDB é variável segundo a faixa etária. No adulto, a doença de Chron, as\nangiodisplasias e as doenças proctológicas, sobretudo as fístulas, são mais relevantes.","E":"A gastrite tipo erosiva causada por antiinflamatórios não hormonais é a principal causa de HDA\nem adultos e crianças, com grande repercussão\nhemodinâmica."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-240442","number":"240442","sourceNumber":"240442","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Homem, 47 anos, apresenta 7 episódios de vômitos após grande ingesta alcoólica\ndurante uma festa. Três horas depois, o\npaciente evolui com tontura e hematêmese. A principal\ncausa do sangramento é","options":{"A":"varizes de esôfago.","B":"laceração de Mallory-Weiss.","C":"úlcera péptica duodenal.","D":"úlcera péptica gástrica.","E":"câncer gástrico."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-254718","number":"254718","sourceNumber":"254718","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre a hemorragia digestiva alta, assinale V para as afirmativas verdadeiras e F para\nas falsas. ( ) Em caso de sangramento tipo\nForrest IA é sempre indicado tratamento cirúrgico. ( ) O\nuso da sonda nasogástrica pode ser indicado em situações especiais, não havendo necessidade de\npassar em todos os pacientes. ( ) A conduta inicial para pacientes com este tipo de hemorragia é\nassegurar via aérea. ( ) A precocidade do exame endoscópico está relacionada ao menor índice de\ntransfusão sanguínea, à diminuição do tempo de internação e dos custos hospitalares e ao maior\níndice de detecção do foco do hemograma. ( ) O balão esofágico (Sengstaken ? Blakemore) é o\nmais eficaz para sangramento das varizes esofagianas. A sequência correta é","options":{"A":"V, V, V, V, F.","B":"V, V, V, V, V.","C":"V, V, F, F, V.","D":"F, V, V, V, V.","E":"F, V, V, V, F."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-254728","number":"254728","sourceNumber":"254728","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"São causas mais frequentes de hemorragia digestiva baixa grave em indivíduo com\nidade acima de 60 anos:","options":{"A":"Neoplasia dos cólons e neoplasia do reto.","B":"Retocolite ulcerativa e doença diverticular dos cólons.","C":"Hemorroidas e neoplasia dos cólons.","D":"Doença diverticular dos cólons e angiodisplasia.","E":"Doença diverticular dos cólons e neoplasia do reto."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-227659","number":"227659","sourceNumber":"227659","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Uma mulher de 18 anos, sofre dor abdominal de início súbito que piora ao deambular,\ncom hiporexia, nega atraso menstrual e faz uso de\nanticoncepcional via oral há 1 ano, com febre\n(temp. Axilar 38,5 ), leucocitose ( 16 mil total ), com dor a descompressão brusca em fossa ilíaca\ndireita, o clínico de plantão faz ultrassonografia abdominal que mostra apenas um pouco de líquido\nno fundo de saco posterior, o diagnóstico presuntivo é de abdome agudo inflamatório. O cirurgião\nde sobreaviso é acionado e indica vídeo laparoscopia para apendicectomia, mas durante o\nprocedimento o diagnóstico não é de apendicite aguda, mas sim de uma lesão sacular\n\nanti-mesentérica com dor enegrecida ainda não perfurada, situada a 50cm da válvula íleo cecal em\níleo terminal de aspecto sacular com edema intenso, líquido inflamatório. O cirurgião realiza o\ntratamento correto e a paciente evolui muito bem. Sobre a lesão que a paciente sofria, é correto\nafirmar que:","options":{"A":"trata-se de persistência do ducto vitelínico( ducto onfalo mesentérico ).","B":"provoca rubor cutâneo e episódios de taquicardia.","C":"com frequência tem mucosa gástrica ou pancreática.","D":"deverá se fazer uma colectomia direita com íleo transverso anastomose pois deve ser neoplasia\nmesmo.","E":"trata-se de perfuração de ceco por salmonelose."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-227662","number":"227662","sourceNumber":"227662","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Um homem de 60 anos, alcoólatra habitual há mais de 30 anos, sofreu agudamente de\nvômitos volumosos com sangue vivo (hematêmese franca), foi admitido na urgência de hospital\ngeral com PA: 100/60 mmHg, pulso 129 bpm, pele fria, mas consciente e orientado, anictérico e\nacianótico. Abdome distendido sem sinais de peritonite com ascite de médio volume,\nesplenomegalia, no hemograma mostrou hematócrito de 27%, na passagem da sonda nasogástrica\nse aspirou 300 ml de sangue vivo. Após ser encaminhado à UTI, e todos os protocolos de\nmonitorização e reposições iniciais, esse paciente deve ser submetido a:","options":{"A":"tamponamento esofágico com balão","B":"esofagograma baritado","C":"angiografia seletiva","D":"vídeo endoscopia digestiva alta","E":"vídeo laparoscopia de urgência"},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-203787","number":"203787","sourceNumber":"203787","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Em relação ao diagnóstico das fístulas anais, é CORRETO afirmar que:","options":{"A":"Na maioria das vezes, o exame proctológico não é suficiente para indicar o tratamento de um\npaciente com fístula anal.","B":"Orifícios externos localizados na fossa isquiorretal geralmente estão associados a fístulas\nsupraesfincterianas e interesfincterianas.","C":"A regra de Goodsall tem maior acurácia nas fístulas anteriores.","D":"Na presença de múltiplos orifícios e quando não se identifica o orifício interno, os exames de\nimagem podem ser necessários.","E":"Ultrassom endorretal tem pouca eficácia no diagnóstico das fístulas complexas."},"answer":"E","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-216220","number":"216220","sourceNumber":"216220","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre hemorragia digestiva alta, é CORRETO afirmar que:","options":{"A":"É mais frequente no sexo feminino.","B":"85% dos sangramentos cessam espontaneamente.","C":"Os sangramentos altos são decorrentes de lesões abaixo do ângulo de Treitz.","D":"Hemorroidas, diverticulose, doença de Crohn e fissura anal são as principais causas de\nhemorragia digestiva alta.","E":"Varizes esofagogástricas não são causas de hemorragia digestiva alta."},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-215789","number":"215789","sourceNumber":"215789","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Menina de 18 anos dá entrada em hospital de referência em vias biliares com quadro\nde icterícia, colúria, acolia fecal, febre e dor\nem hipocôndrio direito, além de melena. Referiu já ter\nfeito transfusão de 2 bolsas de sangue na cidade de origem, onde fez também um ultrassom que\ndemonstrou a presença de coágulos na vesícula e no colédoco. Apresentava coagulograma\nnormal. A paciente foi abordada cirurgicamente e realizada colecistectomia (vesícula cheia de\ncoágulos), coledocotomia, retirada de coágulos do coledoco e coledocostomia a Kher. Sobre este\ncaso, é correto afirmar que:","options":{"A":"o dreno de Kher deve permanecer aberto por 30 dias.","B":"a fonte do sangramento deve ser hemofilia.","C":"é de suma importância a realização de arteriografia de tronco celíaco.","D":"o dreno de Kher pode ser retirado no terceiro dia pós operatório caso não haja sangramento\npelo Kher.","E":"a fonte do sangramento deve ser hiperesplenismo."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-216180","number":"216180","sourceNumber":"216180","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre o manejo da hemorragia digestiva alta em adultos, é correto afirmar que:","options":{"A":"o exame de escolha para o dignóstico topográfico e etiológico da HDB em pacientes\nhemodinamicamente estáveis é a cintilografia com hemácias marcadas.","B":"a angiografia dos vasos mesentéricos pode ser indicada nos casos de HDB, contudo tem a\ndesvantagem de não serem possíveis as intervenções terapêuticas durante o exame.","C":"a doença diverticular dos cólons é a principal causa de HDB, sendo que na maioria dos casos,\nocorre resolução espontânea do sangramento.","D":"a pacientes com enterorragia volumosa não está indicada a endoscopia digestiva alta, já que\nessa é a presentação clinica tipica dos\nsangramentos colonicos.","E":"em casos de HDB causada exclusivamente por doença diverticular dos cólons, deve-se ter o\ncuidado necessário com hemorragias pois a resolução do sangramento, por qualquer meio, é\nimpossível."},"answer":"C","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-181870","number":"181870","sourceNumber":"181870","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"A investigação de hematêmese passa necessariamente por uma classificação do\nsangramento digestivo associado ou não a\nvarizes esofagianas. A história e o exame clínico do\npaciente são muito importantes na definição da causa de hematêmese. A investigação passa\nobrigatoriamente pelo exame diagnóstico de endoscopia digestiva alta. O tratamento farmacológico\nmais indicado para o sangramento digestivo alto, é:","options":{"A":"Bloqueadres H2","B":"Omeprazol endovenoso em infusão contínua.","C":"Clipes metálicos","D":"Tamponamento com balões","E":"Cauterização termoelétrica"},"answer":"B","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-175246","number":"175246","sourceNumber":"175246","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Não é causa de hemorragia digestiva alta:","options":{"A":"Divertículo Meckel.","B":"Síndrome de Mallory-Weiss.","C":"Varizes de esôfago.","D":"Doença ulcerosa péptica.","E":"Lesão de Dieulafay."},"answer":"A","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-03-156739","number":"156739","sourceNumber":"156739","collectionBlock":"med:med-cirurgia-med-cir-03","collectionLabel":"MED · MED CIR 03","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 03","subtopic":"","stem":"Sobre hemorragia digestiva, é INCORRETO afirmar:","options":{"A":"A hematêmese com sangue fresco e os sinais de hipoperfusão periféricas sugerem hemorragia\nativa e volumosa.","B":"Vômitos em borra de café indicam perda sanguínea de menor monta, e provavelmente inativa.","C":"A presença de sangue fresco ou coágulo no toque retal com paciente com queixa de\nhematêmese recente reforça a hipótese de sangramento volumoso e ativo.","D":"A endoscopia digestiva alta não deve ser realizada em pacientes hemodinamicamente instáveis.","E":"Pacientes hemodinamicamente estáveis e controlados com terapia clínica podem ser\n\nsubmetidos à endoscopia mais tardiamente."},"answer":"D","answerPending":false,"source":"Cirurgia/MED CIR 03/MED CIR 03.txt","sourceLabel":"MED · MED CIR 03","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 03","MED"],"answerSource":"explicit","commentDeferred":true}]};
